// MeshObject — SceneNode that holds an editable mesh + a material id.

import { SceneNode } from './SceneNode';
import type { Id } from '../core/Id';
import type { EditableMesh } from '../mesh/EditableMesh';

export class MeshObject extends SceneNode {
  mesh: EditableMesh | null = null;
  materialId: Id | null = null;

  constructor(name = 'Mesh') {
    super(name, 'mesh');
  }
}
