// UV editor renderer — draws the loops/edges/faces of every mesh in UV
// space (0..1 + a 1-tile padding). Uses StripBatch for edges and the
// MeshRenderer's textured mode for the texture background. Selection
// highlighting is delegated to a second StripBatch.

import { StripBatch } from './StripRenderer';
import { ShaderProgram } from './ShaderProgram';
import { GpuMesh } from './Buffers';
import type { Camera } from './Camera';
import type { Scene } from '../scene/Scene';
import type { MeshObject } from '../scene/MeshObject';
import type { Material } from '../scene/Material';
import * as Mat4 from '../core/math/Mat4';
import type { Id } from '../core/Id';

const VERT = `#version 300 es
precision highp float;
layout(location=0) in vec2 aUv;
uniform mat4 uViewProj;
out vec2 vUv;
void main() {
  vUv = aUv;
  gl_Position = uViewProj * vec4(aUv.x, 0.0, aUv.y, 1.0);
}`;

const FRAG = `#version 300 es
precision highp float;
in vec2 vUv;
uniform sampler2D uTexture;
uniform float uHasTexture;
uniform vec3 uTint;
out vec4 fragColor;
void main() {
  if (uHasTexture > 0.5) fragColor = texture(uTexture, vUv);
  else fragColor = vec4(uTint, 1.0);
}`;

interface TextureSlot {
  tex: WebGLTexture;
  version: number;
}

export interface UvSelection {
  uvLoops: Set<Id>; // selected loop ids
}

export class UvRenderer {
  readonly gl: WebGL2RenderingContext;
  private bgProgram: ShaderProgram;
  private bgQuad: GpuMesh;
  private edges: StripBatch;
  private highlight: StripBatch;
  private texCache = new Map<Id, TextureSlot>();
  private fallback: WebGLTexture | null = null;

  constructor(gl: WebGL2RenderingContext) {
    this.gl = gl;
    this.bgProgram = new ShaderProgram(gl, VERT, FRAG);
    this.bgQuad = new GpuMesh(gl);
    this.bgQuad.uploadAttributes([
      {
        attribIndex: 0,
        componentsPerVertex: 2,
        data: new Float32Array([0, 0, 1, 0, 1, 1, 0, 1]),
      },
    ]);
    this.bgQuad.uploadIndices(new Uint32Array([0, 1, 2, 0, 2, 3]));
    this.edges = new StripBatch(gl);
    this.edges.width = 1.5;
    this.edges.alpha = 0.92;
    this.highlight = new StripBatch(gl);
    this.highlight.width = 3.0;
    this.highlight.alpha = 1.0;
  }

  private ensureTexture(mat: Material): WebGLTexture | null {
    if (!mat.texture || !mat.texture.data) return null;
    let slot = this.texCache.get(mat.id);
    if (!slot) {
      const tex = this.gl.createTexture();
      if (!tex) return null;
      slot = { tex, version: -1 };
      this.texCache.set(mat.id, slot);
    }
    if (slot.version !== mat.textureVersion) {
      const { gl } = this;
      gl.bindTexture(gl.TEXTURE_2D, slot.tex);
      gl.pixelStorei(gl.UNPACK_ALIGNMENT, 1);
      gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, mat.texture.width, mat.texture.height, 0, gl.RGBA, gl.UNSIGNED_BYTE, mat.texture.data);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.REPEAT);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.REPEAT);
      slot.version = mat.textureVersion;
    }
    return slot.tex;
  }

  private ensureFallback(): WebGLTexture {
    if (this.fallback) return this.fallback;
    const { gl } = this;
    const tex = gl.createTexture()!;
    gl.bindTexture(gl.TEXTURE_2D, tex);
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, 1, 1, 0, gl.RGBA, gl.UNSIGNED_BYTE, new Uint8Array([255, 255, 255, 255]));
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST);
    this.fallback = tex;
    return tex;
  }

  draw(scene: Scene, camera: Camera, aspect: number, vpW: number, vpH: number, sel: UvSelection | null): void {
    const { gl } = this;
    // 1) Texture background: pick the first material that has a texture.
    let bgMat: Material | null = null;
    for (const m of scene.materials()) {
      if (m.texture && m.texture.data) { bgMat = m; break; }
    }
    let tex: WebGLTexture;
    let hasTex = 0;
    if (bgMat) {
      const t = this.ensureTexture(bgMat);
      if (t) { tex = t; hasTex = 1; }
      else tex = this.ensureFallback();
    } else {
      tex = this.ensureFallback();
    }
    this.bgProgram.use();
    this.bgProgram.setMat4('uViewProj', camera.viewProj(aspect) as Float32Array);
    this.bgProgram.setFloat('uHasTexture', hasTex);
    this.bgProgram.setVec3('uTint', 0.25, 0.25, 0.27);
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, tex);
    const texLoc = this.bgProgram.loc('uTexture');
    if (texLoc) gl.uniform1i(texLoc, 0);
    this.bgQuad.drawTriangles();

    // 2) Edges of every mesh's UV loops.
    this.edges.reset();
    for (const node of allMeshNodes(scene)) {
      const mesh = node.mesh;
      if (!mesh) continue;
      for (const face of mesh.faces.values()) {
        const loops = face.loops.map((lid) => mesh.loops.get(lid)!);
        for (let i = 0; i < loops.length; i++) {
          const a = loops[i].uv;
          const b = loops[(i + 1) % loops.length].uv;
          this.edges.add(a[0], 0, a[1], b[0], 0, b[1], 0.85, 0.85, 0.85);
        }
      }
    }
    this.edges.draw(camera, aspect, vpW, vpH);

    // 3) Selection highlights.
    if (sel && sel.uvLoops.size > 0) {
      this.highlight.reset();
      for (const node of allMeshNodes(scene)) {
        const mesh = node.mesh;
        if (!mesh) continue;
        for (const face of mesh.faces.values()) {
          for (let i = 0; i < face.loops.length; i++) {
            const lid = face.loops[i];
            if (!sel.uvLoops.has(lid)) continue;
            const loop = mesh.loops.get(lid)!;
            const next = mesh.loops.get(face.loops[(i + 1) % face.loops.length])!;
            this.highlight.add(loop.uv[0], 0, loop.uv[1], next.uv[0], 0, next.uv[1], 1.0, 0.55, 0.15);
          }
        }
      }
      this.highlight.draw(camera, aspect, vpW, vpH);
    }
  }

  dispose(): void {
    const { gl } = this;
    this.bgProgram.dispose();
    this.bgQuad.dispose();
    for (const slot of this.texCache.values()) gl.deleteTexture(slot.tex);
    this.texCache.clear();
    if (this.fallback) gl.deleteTexture(this.fallback);
    this.fallback = null;
  }

}
void Mat4;

function* allMeshNodes(scene: Scene): IterableIterator<MeshObject> {
  const stack = [scene.root];
  while (stack.length) {
    const n = stack.pop()!;
    if (n.kind === 'mesh') yield n as MeshObject;
    for (const c of n.children) stack.push(c);
  }
}
