// Icosphere: icosahedron + N midpoint subdivisions, projected back to a sphere.

import { EditableMesh } from '../EditableMesh';
import type { Id } from '../../core/Id';

export interface IcoSphereParams {
  radius?: number;
  subdivisions?: number;
}

export function buildIcoSphere(params: IcoSphereParams = {}): EditableMesh {
  const r = params.radius ?? 1;
  const subdiv = Math.max(0, Math.min(5, Math.floor(params.subdivisions ?? 1)));
  const t = (1 + Math.sqrt(5)) / 2;
  // 12 base vertices.
  let positions: Array<[number, number, number]> = [
    [-1, t, 0], [1, t, 0], [-1, -t, 0], [1, -t, 0],
    [0, -1, t], [0, 1, t], [0, -1, -t], [0, 1, -t],
    [t, 0, -1], [t, 0, 1], [-t, 0, -1], [-t, 0, 1],
  ];
  let faces: Array<[number, number, number]> = [
    [0, 11, 5], [0, 5, 1], [0, 1, 7], [0, 7, 10], [0, 10, 11],
    [1, 5, 9], [5, 11, 4], [11, 10, 2], [10, 7, 6], [7, 1, 8],
    [3, 9, 4], [3, 4, 2], [3, 2, 6], [3, 6, 8], [3, 8, 9],
    [4, 9, 5], [2, 4, 11], [6, 2, 10], [8, 6, 7], [9, 8, 1],
  ];

  for (let s = 0; s < subdiv; s++) {
    const cache = new Map<string, number>();
    const newFaces: Array<[number, number, number]> = [];
    const mid = (a: number, b: number): number => {
      const key = a < b ? `${a}_${b}` : `${b}_${a}`;
      const cached = cache.get(key);
      if (cached !== undefined) return cached;
      const pa = positions[a], pb = positions[b];
      const mx = (pa[0] + pb[0]) * 0.5;
      const my = (pa[1] + pb[1]) * 0.5;
      const mz = (pa[2] + pb[2]) * 0.5;
      positions.push([mx, my, mz]);
      const idx = positions.length - 1;
      cache.set(key, idx);
      return idx;
    };
    for (const [a, b, c] of faces) {
      const ab = mid(a, b);
      const bc = mid(b, c);
      const ca = mid(c, a);
      newFaces.push([a, ab, ca], [b, bc, ab], [c, ca, bc], [ab, bc, ca]);
    }
    faces = newFaces;
  }

  // Project to sphere and build mesh.
  const m = new EditableMesh();
  const vertexIds: Id[] = [];
  for (const p of positions) {
    const len = Math.hypot(p[0], p[1], p[2]) || 1;
    vertexIds.push(m.addVertex((p[0] / len) * r, (p[1] / len) * r, (p[2] / len) * r).id);
  }
  for (const [a, b, c] of faces) {
    const f = m.addFace([vertexIds[a], vertexIds[b], vertexIds[c]]);
    // UV per-corner using spherical coords (will have seams).
    const loops = m.faceLoops(f.id);
    for (const l of loops) {
      const v = m.vertices.get(l.vertexId);
      if (!v) continue;
      const nx = v.position[0] / r;
      const ny = v.position[1] / r;
      const nz = v.position[2] / r;
      l.uv[0] = 0.5 + Math.atan2(nz, nx) / (2 * Math.PI);
      l.uv[1] = 0.5 - Math.asin(ny) / Math.PI;
    }
  }

  m.recomputeFaceNormals();
  return m;
}
