// Scene — root container of the scene graph + materials registry.

import { SceneNode } from './SceneNode';
import { MeshObject } from './MeshObject';
import { ReferenceImage } from './ReferenceImage';
import { Material } from './Material';
import type { Id } from '../core/Id';

export class Scene {
  readonly root = new SceneNode('Root', 'empty');
  private _materials = new Map<Id, Material>();
  private _nodesById = new Map<Id, SceneNode>();

  constructor() {
    this.registerNode(this.root);
  }

  addNode(node: SceneNode, parent?: SceneNode): SceneNode {
    const p = parent ?? this.root;
    p.addChild(node);
    this.registerNode(node);
    return node;
  }

  removeNode(node: SceneNode): void {
    if (!node.parent) return;
    node.parent.removeChild(node);
    this.unregisterNode(node);
  }

  findNodeById(id: Id): SceneNode | null {
    return this._nodesById.get(id) ?? null;
  }

  forEachNode(visit: (n: SceneNode) => void, from: SceneNode = this.root): void {
    visit(from);
    for (const c of from.children) this.forEachNode(visit, c);
  }

  addMaterial(mat: Material): Material {
    this._materials.set(mat.id, mat);
    return mat;
  }

  getMaterial(id: Id): Material | null {
    return this._materials.get(id) ?? null;
  }

  materials(): readonly Material[] {
    return Array.from(this._materials.values());
  }

  /** Build a default scene: root + default material + placeholder cube node. */
  static createDefault(): Scene {
    const scene = new Scene();
    const defaultMat = scene.addMaterial(Material.createDefaultGray());
    const cube = new MeshObject('Mesh_Cube');
    cube.materialId = defaultMat.id;
    scene.addNode(cube);
    return scene;
  }

  private registerNode(n: SceneNode): void {
    this._nodesById.set(n.id, n);
    for (const c of n.children) this.registerNode(c);
  }

  private unregisterNode(n: SceneNode): void {
    this._nodesById.delete(n.id);
    for (const c of n.children) this.unregisterNode(c);
  }
}

// Re-export common scene classes for the rest of the codebase.
export { SceneNode, MeshObject, ReferenceImage, Material };
