// OBJ import / export tests.

import { defineTest, assert, assertEquals } from '../harness';
import { Scene, MeshObject } from '../scene/Scene';
import { Material } from '../scene/Material';
import { buildCube } from '../mesh/primitives/Cube';
import { buildPlane } from '../mesh/primitives/Plane';
import { EditableMesh } from '../mesh/EditableMesh';
import { exportObj, importObj, parseObj, parseMtl } from './ObjFormat';
import type { Id } from '../core/Id';

const SUITE = 'objIo';

defineTest(SUITE, 'parseObj parses verts/uvs/normals/faces', () => {
  const src = `
# header
v 0 0 0
v 1 0 0
v 0 1 0
vt 0 0
vt 1 0
vt 0 1
vn 0 0 1
o myObj
f 1/1/1 2/2/1 3/3/1
`;
  const parsed = parseObj(src);
  assertEquals(parsed.positions.length, 3);
  assertEquals(parsed.uvs.length, 3);
  assertEquals(parsed.normals.length, 1);
  assertEquals(parsed.groups.length, 1);
  assertEquals(parsed.groups[0].faceRefs.length, 1);
});

defineTest(SUITE, 'parseMtl parses Kd / Ka / Ks / Ns / d', () => {
  const mtl = `
newmtl Blue
Kd 0.2 0.4 0.8
Ka 0.1 0.1 0.1
Ks 0.5 0.5 0.5
Ns 32.0
d 0.5
`;
  const parsed = parseMtl(mtl);
  assertEquals(parsed.length, 1);
  assert(Math.abs(parsed[0].Kd![0] - 0.2) < 1e-6);
  assertEquals(parsed[0].Ns, 32);
});

defineTest(SUITE, 'importObj creates valid editable topology', () => {
  const scene = new Scene();
  const cube = new MeshObject('Cube');
  cube.mesh = buildCube();
  scene.addNode(cube);
  const { obj } = exportObj(scene);
  const imported = importObj(obj);
  assertEquals(imported.meshes.length, 1);
  const m = imported.meshes[0].mesh!;
  assertEquals(m.vertexCount(), 8);
  assertEquals(m.faceCount(), 6);
  assert(m.validate().ok);
});

defineTest(SUITE, 'roundtrip OBJ preserves vert/face counts and UVs', () => {
  const scene = new Scene();
  const plane = new MeshObject('Plane');
  plane.mesh = buildPlane({ segmentsX: 2, segmentsZ: 2 });
  scene.addNode(plane);
  // Set deterministic UVs.
  let uIdx = 0;
  for (const loop of plane.mesh.loops.values()) {
    loop.uv[0] = (uIdx++ / 10) % 1;
    loop.uv[1] = ((uIdx++) / 10) % 1;
  }
  const { obj } = exportObj(scene);
  const re = importObj(obj);
  const m = re.meshes[0].mesh!;
  assertEquals(m.vertexCount(), plane.mesh!.vertexCount());
  assertEquals(m.faceCount(), plane.mesh!.faceCount());
});

defineTest(SUITE, 'exportObj + parseObj preserves multiple objects', () => {
  const scene = new Scene();
  const a = new MeshObject('First');
  a.mesh = buildCube();
  scene.addNode(a);
  const b = new MeshObject('Second');
  b.mesh = buildPlane({ segmentsX: 1, segmentsZ: 1 });
  scene.addNode(b);
  const { obj } = exportObj(scene);
  const re = importObj(obj);
  assertEquals(re.meshes.length, 2);
  const names = re.meshes.map((n) => n.name);
  assert(names.includes('First'));
  assert(names.includes('Second'));
});

defineTest(SUITE, 'exportObj + importObj round-trips materials via MTL', () => {
  const scene = new Scene();
  const cube = new MeshObject('Cube');
  cube.mesh = buildCube();
  const mat = new Material('Red');
  mat.setBaseColor(0.9, 0.1, 0.1);
  mat.opacity = 0.6;
  scene.addMaterial(mat);
  scene.addNode(cube);
  cube.materialId = mat.id;
  const { obj, mtl } = exportObj(scene, { mtlPath: 'out.mtl' });
  assert(mtl != null);
  const re = importObj(obj, mtl);
  assertEquals(re.materials.length, 1);
  const reMat = re.materials[0];
  assert(Math.abs(reMat.baseColor.r - 0.9) < 1e-4);
  assert(Math.abs(reMat.opacity - 0.6) < 1e-4);
});

defineTest(SUITE, 'n-gon faces survive round-trip', () => {
  const scene = new Scene();
  const mesh = new EditableMesh();
  const ids: Id[] = [];
  for (let i = 0; i < 6; i++) {
    const a = (i / 6) * Math.PI * 2;
    ids.push(mesh.addVertex(Math.cos(a), 0, Math.sin(a)).id);
  }
  mesh.addFace(ids);
  const node = new MeshObject('Hex');
  node.mesh = mesh;
  scene.addNode(node);
  const { obj } = exportObj(scene);
  const re = importObj(obj);
  const m = re.meshes[0].mesh!;
  assertEquals(m.vertexCount(), 6);
  const face = Array.from(m.faces.values())[0];
  assertEquals(face.loops.length, 6);
});
