// Mesh-snapshot wrapping for face-mode ops.

import type { Command } from '../Commands';
import { MeshObject } from '../../scene/MeshObject';
import { cloneMeshPreservingIds } from '../../mesh/MeshClone';
import {
  translateFaces, rotateFaces, scaleFaces,
  extrudeFaces, insetFaces, pokeFaces,
  triangulateFaces, deleteFaces, separateFaces,
} from '../../mesh/OperationsFace';
import type { Id } from '../../core/Id';
import type { Vec3 as Vec3T } from '../../core/math/Vec3';
import type { Scene } from '../../scene/Scene';

abstract class FaceSnapshotCommand implements Command {
  protected node: MeshObject;
  private snap: ReturnType<typeof cloneMeshPreservingIds>;
  abstract readonly label: string;
  constructor(node: MeshObject) {
    this.node = node;
    if (!node.mesh) throw new Error('FaceSnapshotCommand: missing mesh');
    this.snap = cloneMeshPreservingIds(node.mesh);
  }
  do(): void { if (this.node.mesh) this.apply(); }
  undo(): void { this.node.mesh = cloneMeshPreservingIds(this.snap); }
  protected abstract apply(): void;
}

export class TranslateFacesCommand extends FaceSnapshotCommand {
  readonly label = 'Move Faces';
  constructor(node: MeshObject, private faceIds: Id[], private dx: number, private dy: number, private dz: number) { super(node); }
  protected apply(): void { translateFaces(this.node.mesh!, this.faceIds, this.dx, this.dy, this.dz); }
}

export class RotateFacesCommand extends FaceSnapshotCommand {
  readonly label = 'Rotate Faces';
  constructor(node: MeshObject, private faceIds: Id[], private axis: 'x' | 'y' | 'z', private rad: number) { super(node); }
  protected apply(): void { rotateFaces(this.node.mesh!, this.faceIds, this.axis, this.rad); }
}

export class ScaleFacesCommand extends FaceSnapshotCommand {
  readonly label = 'Scale Faces';
  constructor(node: MeshObject, private faceIds: Id[], private sx: number, private sy: number, private sz: number) { super(node); }
  protected apply(): void { scaleFaces(this.node.mesh!, this.faceIds, this.sx, this.sy, this.sz); }
}

export class ExtrudeFacesCommand extends FaceSnapshotCommand {
  readonly label = 'Extrude Faces';
  constructor(node: MeshObject, private faceIds: Id[], private offset: Vec3T) { super(node); }
  protected apply(): void { extrudeFaces(this.node.mesh!, this.faceIds, this.offset); }
}

export class InsetFacesCommand extends FaceSnapshotCommand {
  readonly label = 'Inset';
  constructor(node: MeshObject, private faceIds: Id[], private amount = 0.1) { super(node); }
  protected apply(): void { insetFaces(this.node.mesh!, this.faceIds, this.amount); }
}

export class PokeFacesCommand extends FaceSnapshotCommand {
  readonly label = 'Poke';
  constructor(node: MeshObject, private faceIds: Id[]) { super(node); }
  protected apply(): void { pokeFaces(this.node.mesh!, this.faceIds); }
}

export class TriangulateFacesCommand extends FaceSnapshotCommand {
  readonly label = 'Triangulate';
  constructor(node: MeshObject, private faceIds: Id[]) { super(node); }
  protected apply(): void { triangulateFaces(this.node.mesh!, this.faceIds); }
}

export class DeleteFacesCommand extends FaceSnapshotCommand {
  readonly label = 'Delete Faces';
  constructor(node: MeshObject, private faceIds: Id[]) { super(node); }
  protected apply(): void { deleteFaces(this.node.mesh!, this.faceIds); }
}

/**
 * Separate the selected faces into a new mesh object added to the scene
 * (parented to root). Undo removes the new node and restores the source mesh.
 */
export class SeparateFacesCommand implements Command {
  readonly label = 'Separate';
  private sourceSnap: ReturnType<typeof cloneMeshPreservingIds>;
  private newNode: MeshObject | null = null;
  constructor(private source: MeshObject, private scene: Scene, private faceIds: Id[]) {
    if (!source.mesh) throw new Error('SeparateFacesCommand: missing mesh');
    this.sourceSnap = cloneMeshPreservingIds(source.mesh);
  }
  do(): void {
    if (!this.source.mesh) return;
    if (this.newNode == null) {
      const sep = separateFaces(this.source.mesh, this.faceIds);
      const node = new MeshObject('Separated');
      node.mesh = sep;
      this.scene.addNode(node);
      this.newNode = node;
    } else {
      // Redo path.
      this.source.mesh = cloneMeshPreservingIds(this.sourceSnap);
      const sep = separateFaces(this.source.mesh, this.faceIds);
      this.newNode.mesh = sep;
      if (!this.newNode.parent) this.scene.addNode(this.newNode);
    }
  }
  undo(): void {
    if (this.source.mesh) this.source.mesh = cloneMeshPreservingIds(this.sourceSnap);
    if (this.newNode && this.newNode.parent) {
      this.scene.removeNode(this.newNode);
    }
  }
}
