// Commands for material assignment + property edits.

import type { Command } from '../Commands';
import type { MeshObject } from '../../scene/MeshObject';
import type { Material, MaterialTextureImage, RGB } from '../../scene/Material';
import type { Id } from '../../core/Id';

export class AssignMaterialCommand implements Command {
  readonly label = 'Assign Material';
  private prev: Id | null;
  constructor(private node: MeshObject, private materialId: Id | null) {
    this.prev = node.materialId;
  }
  do(): void { this.node.materialId = this.materialId; }
  undo(): void { this.node.materialId = this.prev; }
}

export class SetMaterialColorCommand implements Command {
  readonly label = 'Set Color';
  private prev: RGB;
  constructor(private mat: Material, private next: RGB) {
    this.prev = { ...mat.baseColor };
  }
  do(): void { this.mat.setBaseColor(this.next.r, this.next.g, this.next.b); }
  undo(): void { this.mat.setBaseColor(this.prev.r, this.prev.g, this.prev.b); }
}

export class SetMaterialOpacityCommand implements Command {
  readonly label = 'Set Opacity';
  private prev: number;
  constructor(private mat: Material, private next: number) {
    this.prev = mat.opacity;
  }
  do(): void { this.mat.opacity = this.next; }
  undo(): void { this.mat.opacity = this.prev; }
}

export class SetMaterialShininessCommand implements Command {
  readonly label = 'Set Shininess';
  private prev: number;
  constructor(private mat: Material, private next: number) {
    this.prev = mat.shininess;
  }
  do(): void { this.mat.shininess = this.next; }
  undo(): void { this.mat.shininess = this.prev; }
}

export class SetMaterialTextureCommand implements Command {
  readonly label = 'Set Texture';
  private prev: MaterialTextureImage | null;
  constructor(private mat: Material, private next: MaterialTextureImage | null) {
    this.prev = mat.texture;
  }
  do(): void { this.mat.setTexture(this.next); }
  undo(): void { this.mat.setTexture(this.prev); }
}
