// Unit tests for the command + history system.

import { defineTest, assert, assertEquals } from '../harness';
import { History, type Command } from './Commands';
import { SetTransformCommand } from './commands/SetTransformCommand';
import { SceneNode } from '../scene/SceneNode';

const SUITE = 'commands';

function makeCmd(name: string, log: string[]): Command {
  let didCount = 0;
  return {
    label: name,
    do(): void { log.push(`do:${name}`); didCount++; },
    undo(): void { log.push(`undo:${name}`); didCount--; },
  };
}

defineTest(SUITE, 'execute pushes to undo stack and runs do()', () => {
  const log: string[] = [];
  const h = new History();
  h.execute(makeCmd('A', log));
  assert(h.canUndo());
  assert(!h.canRedo());
  assertEquals(log[0], 'do:A');
});

defineTest(SUITE, 'undo pops and calls undo(); redo replays', () => {
  const log: string[] = [];
  const h = new History();
  h.execute(makeCmd('A', log));
  h.undo();
  assert(!h.canUndo());
  assert(h.canRedo());
  assertEquals(log[1], 'undo:A');
  h.redo();
  assertEquals(log[2], 'do:A');
  assert(h.canUndo());
});

defineTest(SUITE, 'execute clears the redo stack', () => {
  const log: string[] = [];
  const h = new History();
  h.execute(makeCmd('A', log));
  h.undo();
  assert(h.canRedo());
  h.execute(makeCmd('B', log));
  assert(!h.canRedo());
});

defineTest(SUITE, 'undo / redo state transitions on a transform command', () => {
  const node = new SceneNode('Test');
  const start: [number, number, number] = [node.transform.position[0], node.transform.position[1], node.transform.position[2]];
  const cmd = new SetTransformCommand(node, {
    position: [5, 0, 0],
    rotation: [0, 0, 0, 1],
    scale: [1, 1, 1],
  }, 'Move X');
  const h = new History();
  h.execute(cmd);
  assertEquals(node.transform.position[0], 5);
  h.undo();
  assertEquals(node.transform.position[0], start[0]);
  h.redo();
  assertEquals(node.transform.position[0], 5);
});

defineTest(SUITE, 'replaceTop replaces last command and clears redo', () => {
  const node = new SceneNode('Test');
  const h = new History();
  h.execute(new SetTransformCommand(node, { position: [1, 0, 0], rotation: [0, 0, 0, 1], scale: [1, 1, 1] }, 'Move 1'));
  h.replaceTop(new SetTransformCommand(node, { position: [3, 0, 0], rotation: [0, 0, 0, 1], scale: [1, 1, 1] }, 'Move 3'));
  assertEquals(node.transform.position[0], 3);
  // Undo returns to original.
  h.undo();
  assertEquals(node.transform.position[0], 0);
});

defineTest(SUITE, 'replaceTop fires only "replace" event (not execute)', () => {
  const node = new SceneNode('Test');
  const h = new History();
  h.execute(new SetTransformCommand(node, { position: [1, 0, 0], rotation: [0, 0, 0, 1], scale: [1, 1, 1] }, 'M1'));
  const events: string[] = [];
  h.on((e) => events.push(e.type));
  h.replaceTop(new SetTransformCommand(node, { position: [2, 0, 0], rotation: [0, 0, 0, 1], scale: [1, 1, 1] }, 'M2'));
  assertEquals(events.length, 1);
  assertEquals(events[0], 'replace');
});

defineTest(SUITE, 'maxDepth caps the undo stack', () => {
  const log: string[] = [];
  const h = new History();
  h.maxDepth = 3;
  for (let i = 0; i < 5; i++) h.execute(makeCmd(`C${i}`, log));
  assertEquals(h.undoLabels().length, 3);
  assertEquals(h.undoLabels()[0], 'C2');
  assertEquals(h.undoLabels()[2], 'C4');
});

defineTest(SUITE, 'app integration: transform command updates render mesh dirty + footer', () => {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const app = (globalThis as any).BrutalMeshApp;
  if (!app) return;
  const cube = app.scene.root.children[0];
  const before = cube.transform.position[0];
  app.history.execute(new SetTransformCommand(cube, {
    position: [before + 1, cube.transform.position[1], cube.transform.position[2]],
    rotation: [cube.transform.rotation[0], cube.transform.rotation[1], cube.transform.rotation[2], cube.transform.rotation[3]],
    scale: [cube.transform.scale[0], cube.transform.scale[1], cube.transform.scale[2]],
  }, 'Move +X'));
  assertEquals(cube.transform.position[0], before + 1);
  app.history.undo();
  assertEquals(cube.transform.position[0], before);
});
