// Plane: stored as (normal, d) where the plane is { p : dot(normal, p) = d }.

import * as Vec3 from './Vec3';
import type { Vec3 as Vec3T } from './Vec3';
import type { Ray } from './Ray';

export interface Plane {
  normal: Vec3T;
  d: number;
}

export function create(): Plane {
  return { normal: Vec3.fromValues(0, 1, 0), d: 0 };
}

export function fromNormalAndPoint(out: Plane, normal: Readonly<Vec3T>, point: Readonly<Vec3T>): Plane {
  Vec3.normalize(out.normal, normal);
  out.d = Vec3.dot(out.normal, point);
  return out;
}

/** Returns the parametric `t` along the ray for the intersection, or NaN if parallel/behind. */
export function intersectRay(plane: Plane, ray: Ray): number {
  const denom = Vec3.dot(plane.normal, ray.direction);
  if (Math.abs(denom) < 1e-7) return NaN;
  const t = (plane.d - Vec3.dot(plane.normal, ray.origin)) / denom;
  if (t < 0) return NaN;
  return t;
}
