// Browser-side unit tests for the math module. Registered in main.ts so
// `BrutalMeshHarness.runTests({ suite: 'math' })` exercises them.

import { defineTest, assert, assertClose, assertEquals, assertThrows } from '../../harness';
import * as Vec2 from './Vec2';
import * as Vec3 from './Vec3';
import * as Mat4 from './Mat4';
import * as Quat from './Quat';
import * as Ray from './Ray';
import * as Plane from './Plane';
import * as Aabb from './Aabb';
import * as Project from './Project';

const SUITE = 'math';

// ---------------------------------------------------------------------------
// Vec3
// ---------------------------------------------------------------------------

defineTest(SUITE, 'Vec3.add / sub / scale', () => {
  const a = Vec3.fromValues(1, 2, 3);
  const b = Vec3.fromValues(4, 5, 6);
  const o = Vec3.create();
  Vec3.add(o, a, b);
  assert(Vec3.equalsApprox(o, Vec3.fromValues(5, 7, 9)));
  Vec3.sub(o, b, a);
  assert(Vec3.equalsApprox(o, Vec3.fromValues(3, 3, 3)));
  Vec3.scale(o, a, 2);
  assert(Vec3.equalsApprox(o, Vec3.fromValues(2, 4, 6)));
});

defineTest(SUITE, 'Vec3.dot / cross / normalize / length', () => {
  const x = Vec3.fromValues(1, 0, 0);
  const y = Vec3.fromValues(0, 1, 0);
  assertClose(Vec3.dot(x, y), 0);
  assertClose(Vec3.dot(x, x), 1);
  const o = Vec3.create();
  Vec3.cross(o, x, y);
  assert(Vec3.equalsApprox(o, Vec3.fromValues(0, 0, 1)));
  Vec3.set(o, 2, 0, 0);
  Vec3.normalize(o, o);
  assertClose(Vec3.length(o), 1);
});

// ---------------------------------------------------------------------------
// Mat4: identity, multiply, transform, invert, perspective, lookAt
// ---------------------------------------------------------------------------

defineTest(SUITE, 'Mat4.identity is the multiplicative identity', () => {
  const id = Mat4.identity(Mat4.create());
  const m = Mat4.create();
  Mat4.fromTranslation(m, Vec3.fromValues(1, 2, 3));
  const o = Mat4.create();
  Mat4.multiply(o, m, id);
  assert(Mat4.equalsApprox(o, m));
  Mat4.multiply(o, id, m);
  assert(Mat4.equalsApprox(o, m));
});

defineTest(SUITE, 'Mat4.transformPoint with translation matrix', () => {
  const m = Mat4.fromTranslation(Mat4.create(), Vec3.fromValues(10, 20, 30));
  const p = Vec3.fromValues(1, 2, 3);
  const out = Vec3.create();
  Mat4.transformPoint(out, p, m);
  assert(Vec3.equalsApprox(out, Vec3.fromValues(11, 22, 33)));
});

defineTest(SUITE, 'Mat4.transformDirection skips translation', () => {
  const m = Mat4.fromTranslation(Mat4.create(), Vec3.fromValues(10, 20, 30));
  const d = Vec3.fromValues(1, 0, 0);
  const out = Vec3.create();
  Mat4.transformDirection(out, d, m);
  assert(Vec3.equalsApprox(out, Vec3.fromValues(1, 0, 0)));
});

defineTest(SUITE, 'Mat4.invert and multiply gives identity', () => {
  const m = Mat4.create();
  Mat4.fromTranslation(m, Vec3.fromValues(5, -3, 2));
  Mat4.multiply(m, m, Mat4.fromRotationY(Mat4.create(), 0.7));
  Mat4.multiply(m, m, Mat4.fromScale(Mat4.create(), Vec3.fromValues(2, 3, 1.5)));
  const inv = Mat4.create();
  assert(Mat4.invert(inv, m) !== null);
  const id = Mat4.create();
  Mat4.multiply(id, m, inv);
  assert(Mat4.equalsApprox(id, Mat4.identity(Mat4.create()), 1e-4));
});

defineTest(SUITE, 'Mat4.perspective projection w=1 maps eye-forward to ndc near/far', () => {
  const fov = Math.PI / 4;
  const aspect = 1;
  const near = 0.1;
  const far = 100;
  const proj = Mat4.perspective(Mat4.create(), fov, aspect, near, far);
  // Point on the negative Z (camera forward) at -near should map close to ndc.z = -1.
  const near3 = Vec3.fromValues(0, 0, -near);
  const o = Vec3.create();
  Mat4.transformPoint(o, near3, proj);
  // After perspective divide, ndc.z near plane ~ -1.
  assertClose(o[2], -1, 1e-3);
  const far3 = Vec3.fromValues(0, 0, -far);
  Mat4.transformPoint(o, far3, proj);
  assertClose(o[2], 1, 1e-3);
});

defineTest(SUITE, 'Mat4.lookAt produces a view that maps target to camera-forward', () => {
  const eye = Vec3.fromValues(0, 0, 5);
  const target = Vec3.fromValues(0, 0, 0);
  const up = Vec3.fromValues(0, 1, 0);
  const view = Mat4.lookAt(Mat4.create(), eye, target, up);
  const o = Vec3.create();
  Mat4.transformPoint(o, target, view);
  // Target sits along -Z 5 units in front of camera.
  assert(Vec3.equalsApprox(o, Vec3.fromValues(0, 0, -5), 1e-4));
});

// ---------------------------------------------------------------------------
// Quat
// ---------------------------------------------------------------------------

defineTest(SUITE, 'Quat.setAxisAngle 90° about Y rotates X→-Z', () => {
  const q = Quat.create();
  Quat.setAxisAngle(q, Vec3.fromValues(0, 1, 0), Math.PI / 2);
  const out = Vec3.create();
  Quat.transformVec3(out, Vec3.fromValues(1, 0, 0), q);
  assert(Vec3.equalsApprox(out, Vec3.fromValues(0, 0, -1), 1e-5));
});

defineTest(SUITE, 'Quat.multiply: combining two 45° rotations equals one 90°', () => {
  const q1 = Quat.create();
  Quat.setAxisAngle(q1, Vec3.fromValues(0, 1, 0), Math.PI / 4);
  const q2 = Quat.create();
  Quat.setAxisAngle(q2, Vec3.fromValues(0, 1, 0), Math.PI / 4);
  const q3 = Quat.create();
  Quat.multiply(q3, q1, q2);
  const expected = Quat.create();
  Quat.setAxisAngle(expected, Vec3.fromValues(0, 1, 0), Math.PI / 2);
  assert(Quat.equalsApprox(q3, expected, 1e-5));
});

defineTest(SUITE, 'Mat4.trs(t, q, s) builds a matching transform', () => {
  const t = Vec3.fromValues(5, 0, 0);
  const q = Quat.fromValues(0, 0, 0, 1); // identity
  const s = Vec3.fromValues(2, 2, 2);
  const m = Mat4.trs(Mat4.create(), t, q, s);
  const o = Vec3.create();
  Mat4.transformPoint(o, Vec3.fromValues(1, 1, 1), m);
  // (1,1,1) scaled by 2 → (2,2,2); plus translate (5,0,0) → (7,2,2).
  assert(Vec3.equalsApprox(o, Vec3.fromValues(7, 2, 2)));
});

// ---------------------------------------------------------------------------
// Ray + Plane + Triangle + AABB
// ---------------------------------------------------------------------------

defineTest(SUITE, 'Plane.intersectRay hits the XY plane from above', () => {
  const plane = Plane.create();
  Plane.fromNormalAndPoint(plane, Vec3.fromValues(0, 1, 0), Vec3.fromValues(0, 0, 0));
  const ray: Ray.Ray = { origin: Vec3.fromValues(0, 5, 0), direction: Vec3.fromValues(0, -1, 0) };
  const t = Plane.intersectRay(plane, ray);
  assertClose(t, 5, 1e-6);
});

defineTest(SUITE, 'Plane.intersectRay misses when ray points away', () => {
  const plane = Plane.create();
  Plane.fromNormalAndPoint(plane, Vec3.fromValues(0, 1, 0), Vec3.fromValues(0, 0, 0));
  const ray: Ray.Ray = { origin: Vec3.fromValues(0, 5, 0), direction: Vec3.fromValues(0, 1, 0) };
  const t = Plane.intersectRay(plane, ray);
  assert(Number.isNaN(t));
});

defineTest(SUITE, 'Ray.intersectTriangle hits a flat triangle on the XY plane', () => {
  const v0 = Vec3.fromValues(-1, -1, 0);
  const v1 = Vec3.fromValues(1, -1, 0);
  const v2 = Vec3.fromValues(0, 1, 0);
  const ray: Ray.Ray = { origin: Vec3.fromValues(0, 0, 5), direction: Vec3.fromValues(0, 0, -1) };
  const t = Ray.intersectTriangle(ray, v0, v1, v2);
  assertClose(t, 5, 1e-6);
});

defineTest(SUITE, 'Ray.intersectTriangle misses outside the triangle', () => {
  const v0 = Vec3.fromValues(-1, -1, 0);
  const v1 = Vec3.fromValues(1, -1, 0);
  const v2 = Vec3.fromValues(0, 1, 0);
  const ray: Ray.Ray = { origin: Vec3.fromValues(5, 5, 5), direction: Vec3.fromValues(0, 0, -1) };
  const t = Ray.intersectTriangle(ray, v0, v1, v2);
  assert(Number.isNaN(t));
});

defineTest(SUITE, 'Aabb.expandPoint / containsPoint', () => {
  const box = Aabb.create();
  Aabb.expandPoint(box, Vec3.fromValues(-1, -1, -1));
  Aabb.expandPoint(box, Vec3.fromValues(1, 1, 1));
  assert(Aabb.containsPoint(box, Vec3.fromValues(0, 0, 0)));
  assert(!Aabb.containsPoint(box, Vec3.fromValues(2, 0, 0)));
});

defineTest(SUITE, 'Aabb.intersectRay slab test on the unit box', () => {
  const box = Aabb.create();
  Aabb.expandPoint(box, Vec3.fromValues(-1, -1, -1));
  Aabb.expandPoint(box, Vec3.fromValues(1, 1, 1));
  const ray: Ray.Ray = { origin: Vec3.fromValues(0, 0, 5), direction: Vec3.fromValues(0, 0, -1) };
  const t = Aabb.intersectRay(box, ray);
  assertClose(t, 4, 1e-6);
});

// ---------------------------------------------------------------------------
// Projection / unprojection
// ---------------------------------------------------------------------------

defineTest(SUITE, 'project ↔ unproject roundtrips on identity view-projection', () => {
  const vp = { x: 0, y: 0, w: 800, h: 600 };
  const proj = Mat4.create(); // identity
  const out = new Float32Array(3);
  // Point at (0, 0, 0) projects to viewport center.
  Project.project(out, Vec3.fromValues(0, 0, 0), vp, proj);
  assertClose(out[0], 400, 1e-3);
  assertClose(out[1], 300, 1e-3);
  // Unprojecting the same screen pixel + NDC z=0 returns origin.
  const back = Vec3.create();
  Project.unproject(back, 400, 300, 0, vp, proj);
  assert(Vec3.equalsApprox(back, Vec3.fromValues(0, 0, 0), 1e-3));
});

defineTest(SUITE, 'screenPointToRay center ray is camera-forward', () => {
  const eye = Vec3.fromValues(0, 0, 5);
  const target = Vec3.fromValues(0, 0, 0);
  const up = Vec3.fromValues(0, 1, 0);
  const view = Mat4.lookAt(Mat4.create(), eye, target, up);
  const proj = Mat4.perspective(Mat4.create(), Math.PI / 4, 800 / 600, 0.1, 100);
  const vpMat = Mat4.create();
  Mat4.multiply(vpMat, proj, view);
  const vpRect = { x: 0, y: 0, w: 800, h: 600 };
  const ray = Ray.create();
  Project.screenPointToRay(ray, 400, 300, vpRect, vpMat);
  // Direction must point toward the target (i.e., -Z in world).
  assert(ray.direction[2] < -0.99);
});

