defineTest(SUITE, 'Vec2.distance / dot / cross', () => {
  const a = Vec2.fromValues(0, 0);
  const b = Vec2.fromValues(3, 4);
  assertClose(Vec2.distance(a, b), 5);
  assertEquals(Vec2.dot(Vec2.fromValues(1, 0), Vec2.fromValues(0, 1)), 0);
  assertEquals(Vec2.cross(Vec2.fromValues(1, 0), Vec2.fromValues(0, 1)), 1);
});

defineTest(SUITE, 'assertThrows works', () => {
  assertThrows(() => {
    throw new Error('expected');
  });
});
