// UV sphere primitive: (rings-1) latitude rings + 2 poles. Quad middle bands,
// triangle pole fans.

import { EditableMesh } from '../EditableMesh';
import type { Id } from '../../core/Id';

export interface UvSphereParams {
  radius?: number;
  segments?: number; // around equator
  rings?: number;    // including poles
}

export function buildUvSphere(params: UvSphereParams = {}): EditableMesh {
  const r = params.radius ?? 1;
  const seg = Math.max(3, Math.floor(params.segments ?? 24));
  const rings = Math.max(3, Math.floor(params.rings ?? 16));
  const m = new EditableMesh();

  const top = m.addVertex(0, r, 0).id;
  const bottom = m.addVertex(0, -r, 0).id;

  // Latitude rings (excluding poles).
  const grid: Id[][] = [];
  for (let j = 1; j < rings; j++) {
    const v = j / rings;
    const phi = v * Math.PI; // 0..π
    const y = Math.cos(phi) * r;
    const ringRadius = Math.sin(phi) * r;
    const row: Id[] = [];
    for (let i = 0; i < seg; i++) {
      const t = (i / seg) * Math.PI * 2;
      row.push(m.addVertex(Math.cos(t) * ringRadius, y, Math.sin(t) * ringRadius).id);
    }
    grid.push(row);
  }

  // Top fan.
  for (let i = 0; i < seg; i++) {
    const j = (i + 1) % seg;
    const f = m.addFace([top, grid[0][i], grid[0][j]]);
    const loops = m.faceLoops(f.id);
    const u0 = i / seg, u1 = (i + 1) / seg, uMid = (u0 + u1) * 0.5;
    const uvs: Array<[number, number]> = [[uMid, 0], [u0, 1 / rings], [u1, 1 / rings]];
    for (let k = 0; k < loops.length; k++) { loops[k].uv[0] = uvs[k][0]; loops[k].uv[1] = uvs[k][1]; }
  }

  // Quad bands.
  for (let row = 0; row < grid.length - 1; row++) {
    const rA = grid[row];
    const rB = grid[row + 1];
    for (let i = 0; i < seg; i++) {
      const j = (i + 1) % seg;
      const f = m.addFace([rA[i], rA[j], rB[j], rB[i]]);
      const loops = m.faceLoops(f.id);
      const u0 = i / seg, u1 = (i + 1) / seg;
      const v0 = (row + 1) / rings, v1 = (row + 2) / rings;
      const uvs: Array<[number, number]> = [[u0, v0], [u1, v0], [u1, v1], [u0, v1]];
      for (let k = 0; k < loops.length; k++) { loops[k].uv[0] = uvs[k][0]; loops[k].uv[1] = uvs[k][1]; }
    }
  }

  // Bottom fan.
  const lastRow = grid[grid.length - 1];
  for (let i = 0; i < seg; i++) {
    const j = (i + 1) % seg;
    const f = m.addFace([bottom, lastRow[j], lastRow[i]]);
    const loops = m.faceLoops(f.id);
    const u0 = i / seg, u1 = (i + 1) / seg, uMid = (u0 + u1) * 0.5;
    const vTop = (rings - 1) / rings;
    const uvs: Array<[number, number]> = [[uMid, 1], [u1, vTop], [u0, vTop]];
    for (let k = 0; k < loops.length; k++) { loops[k].uv[0] = uvs[k][0]; loops[k].uv[1] = uvs[k][1]; }
  }

  m.recomputeFaceNormals();
  return m;
}
