// Object-mode commands: each captures a full mesh snapshot for undo.

import type { Command } from '../Commands';
import { MeshObject } from '../../scene/MeshObject';
import { SceneNode } from '../../scene/SceneNode';
import { cloneMesh, cloneMeshPreservingIds } from '../../mesh/MeshClone';
import { shadeFlat, shadeSmooth, subdivide, mirror, append } from '../../mesh/OperationsObject';
import { EditableMesh } from '../../mesh/EditableMesh';
import type { Scene } from '../../scene/Scene';

abstract class MeshSnapshotCommand implements Command {
  protected node: MeshObject;
  protected prev: EditableMesh;
  abstract readonly label: string;
  constructor(node: MeshObject) {
    this.node = node;
    if (!node.mesh) throw new Error('MeshSnapshotCommand: node has no mesh');
    this.prev = cloneMeshPreservingIds(node.mesh);
  }
  abstract apply(mesh: EditableMesh): void;
  do(): void {
    if (!this.node.mesh) return;
    this.apply(this.node.mesh);
  }
  undo(): void {
    this.node.mesh = cloneMeshPreservingIds(this.prev);
  }
}

export class ShadeSmoothCommand extends MeshSnapshotCommand {
  readonly label = 'Shade Smooth';
  apply(mesh: EditableMesh): void { shadeSmooth(mesh); }
}

export class ShadeFlatCommand extends MeshSnapshotCommand {
  readonly label = 'Shade Flat';
  apply(mesh: EditableMesh): void { shadeFlat(mesh); }
}

export class SubdivideCommand extends MeshSnapshotCommand {
  readonly label = 'Subdivide';
  apply(mesh: EditableMesh): void { subdivide(mesh); }
}

export class CatmullClarkCommand extends MeshSnapshotCommand {
  readonly label = 'Catmull-Clark';
  apply(mesh: EditableMesh): void {
    // First-pass placeholder: same topology split as Subdivide.
    subdivide(mesh);
  }
}

export class MirrorCommand extends MeshSnapshotCommand {
  readonly label = 'Mirror';
  constructor(node: MeshObject, private axis: 'x' | 'y' | 'z', private mergeAtPlane = true) {
    super(node);
  }
  apply(mesh: EditableMesh): void { mirror(mesh, this.axis, this.mergeAtPlane); }
}

/**
 * Duplicate the active mesh object — adds a new MeshObject sibling.
 * Undo removes the new node.
 */
export class DuplicateCommand implements Command {
  readonly label = 'Duplicate';
  private newNode: MeshObject;
  constructor(private scene: Scene, private original: MeshObject) {
    if (!original.mesh) throw new Error('DuplicateCommand: original has no mesh');
    this.newNode = new MeshObject(original.name + ' Copy');
    this.newNode.mesh = cloneMesh(original.mesh);
    this.newNode.materialId = original.materialId;
    this.newNode.transform.setPosition(original.transform.position[0], original.transform.position[1], original.transform.position[2]);
    this.newNode.transform.setRotationQuat(original.transform.rotation[0], original.transform.rotation[1], original.transform.rotation[2], original.transform.rotation[3]);
    this.newNode.transform.setScale(original.transform.scale[0], original.transform.scale[1], original.transform.scale[2]);
  }
  do(): void {
    this.scene.addNode(this.newNode, this.original.parent ?? this.scene.root);
  }
  undo(): void {
    this.scene.removeNode(this.newNode);
  }
}

/** Delete a mesh object. Undo re-inserts it under the same parent. */
export class DeleteObjectCommand implements Command {
  readonly label = 'Delete';
  private prevParent: SceneNode;
  constructor(private scene: Scene, private node: MeshObject) {
    this.prevParent = node.parent ?? scene.root;
  }
  do(): void { this.scene.removeNode(this.node); }
  undo(): void { this.scene.addNode(this.node, this.prevParent); }
}

/**
 * Combine multiple mesh objects into a single new MeshObject. Removes the
 * inputs from the scene; undo re-inserts them and removes the combined one.
 */
export class CombineCommand implements Command {
  readonly label = 'Combine';
  private combined: MeshObject;
  private prevParents = new Map<MeshObject, SceneNode>();
  constructor(private scene: Scene, private inputs: MeshObject[]) {
    this.combined = new MeshObject('Combined');
    const m = new EditableMesh();
    for (const obj of inputs) {
      if (!obj.mesh) continue;
      append(m, obj.mesh);
      this.prevParents.set(obj, obj.parent ?? scene.root);
    }
    this.combined.mesh = m;
  }
  do(): void {
    for (const obj of this.inputs) this.scene.removeNode(obj);
    this.scene.addNode(this.combined, this.scene.root);
  }
  undo(): void {
    this.scene.removeNode(this.combined);
    for (const [obj, parent] of this.prevParents) this.scene.addNode(obj, parent);
  }
}
