// Command + History. Every undoable operation implements this interface;
// History maintains the do/undo stacks and runs lifecycle hooks (mark
// render meshes dirty, refresh footer stats, etc.) on each transition.
//
// Commands are immutable values once committed. To "edit" the last
// operation from the action bar, callers either (a) build a fresh command
// and replace the top of the stack via `History.replaceTop`, or (b) the
// command exposes a custom `merge(next)` method that fuses two adjacent
// commands.

export interface Command {
  /** Short human-readable label shown in the History panel. */
  readonly label: string;
  do(): void;
  undo(): void;
  /** Optional: merge a second command of the same kind into this one. Return true on success. */
  merge?(next: Command): boolean;
  /**
   * Optional: re-snapshot the "previous" state. History.replaceTop calls
   * this after undoing the prior command, so that this command's `undo`
   * returns the model to the same baseline as the command it replaced.
   */
  rebasePrev?(): void;
}

export interface HistoryListener {
  (event: HistoryEvent): void;
}

export type HistoryEvent =
  | { type: 'execute'; cmd: Command }
  | { type: 'undo'; cmd: Command }
  | { type: 'redo'; cmd: Command }
  | { type: 'replace'; cmd: Command }
  | { type: 'clear' };

export class History {
  private undoStack: Command[] = [];
  private redoStack: Command[] = [];
  private listeners = new Set<HistoryListener>();

  /** Cap on stack length so long-running sessions don't grow unbounded. */
  maxDepth = 200;

  /** Run a command and push it on the undo stack. */
  execute(cmd: Command): void {
    cmd.do();
    this.undoStack.push(cmd);
    if (this.undoStack.length > this.maxDepth) this.undoStack.shift();
    this.redoStack.length = 0;
    this.emit({ type: 'execute', cmd });
  }

  canUndo(): boolean {
    return this.undoStack.length > 0;
  }

  canRedo(): boolean {
    return this.redoStack.length > 0;
  }

  undo(): boolean {
    const cmd = this.undoStack.pop();
    if (!cmd) return false;
    cmd.undo();
    this.redoStack.push(cmd);
    this.emit({ type: 'undo', cmd });
    return true;
  }

  redo(): boolean {
    const cmd = this.redoStack.pop();
    if (!cmd) return false;
    cmd.do();
    this.undoStack.push(cmd);
    this.emit({ type: 'redo', cmd });
    return true;
  }

  /**
   * Replace the most recent command with `cmd` after undoing the old one
   * and applying the new one. Used by the action bar to edit the last
   * operation in-place.
   */
  replaceTop(cmd: Command): void {
    const old = this.undoStack.pop();
    if (old) old.undo();
    // Let the replacement re-snapshot now that the prior command has been
    // undone — otherwise its captured `prev` may reflect the post-old state,
    // and its undo() would not return to the model's true baseline.
    if (cmd.rebasePrev) cmd.rebasePrev();
    cmd.do();
    this.undoStack.push(cmd);
    this.redoStack.length = 0;
    this.emit({ type: 'replace', cmd });
  }

  clear(): void {
    this.undoStack.length = 0;
    this.redoStack.length = 0;
    this.emit({ type: 'clear' });
  }

  /** Labels of commands in the undo stack (oldest → newest). */
  undoLabels(): string[] {
    return this.undoStack.map((c) => c.label);
  }

  redoLabels(): string[] {
    return this.redoStack.map((c) => c.label);
  }

  topLabel(): string | null {
    const top = this.undoStack[this.undoStack.length - 1];
    return top ? top.label : null;
  }

  on(fn: HistoryListener): () => void {
    this.listeners.add(fn);
    return () => this.listeners.delete(fn);
  }

  /**
   * Emit a synthetic `replace` event for the current top command — used when
   * a command mutates in place (e.g., a primitive's parameters changed via
   * the action bar) and listeners need to refresh render meshes.
   */
  notifyTopChanged(): void {
    const top = this.undoStack[this.undoStack.length - 1];
    if (!top) return;
    this.emit({ type: 'replace', cmd: top });
  }

  private emit(e: HistoryEvent): void {
    for (const fn of this.listeners) fn(e);
  }
}
