// Tests for triangulation + normals + render mesh.

import { defineTest, assert, assertEquals } from '../harness';
import { EditableMesh } from './EditableMesh';
import { earClip } from './Triangulation';
import { RenderMesh, buildRenderMesh } from './RenderMesh';
import { recomputeLoopNormals } from './Normals';
import { buildCube } from './primitives/Cube';
import { buildUvSphere } from './primitives/UvSphere';
import * as Vec3 from '../core/math/Vec3';

const SUITE = 'renderMesh';

defineTest(SUITE, 'triangulation: a triangle is 1 triangle', () => {
  const tris = earClip(
    [Vec3.fromValues(0, 0, 0), Vec3.fromValues(1, 0, 0), Vec3.fromValues(0, 1, 0)],
    Vec3.fromValues(0, 0, 1),
  );
  assertEquals(tris.length, 3);
  assertEquals(tris[0], 0);
  assertEquals(tris[1], 1);
  assertEquals(tris[2], 2);
});

defineTest(SUITE, 'triangulation: quad → 2 triangles (4 verts, 6 indices)', () => {
  const verts = [
    Vec3.fromValues(0, 0, 0),
    Vec3.fromValues(1, 0, 0),
    Vec3.fromValues(1, 1, 0),
    Vec3.fromValues(0, 1, 0),
  ];
  const tris = earClip(verts, Vec3.fromValues(0, 0, 1));
  assertEquals(tris.length, 6);
});

defineTest(SUITE, 'triangulation: convex pentagon → 3 triangles', () => {
  const verts: Vec3.Vec3[] = [];
  for (let i = 0; i < 5; i++) {
    const t = (i / 5) * Math.PI * 2;
    verts.push(Vec3.fromValues(Math.cos(t), Math.sin(t), 0));
  }
  const tris = earClip(verts, Vec3.fromValues(0, 0, 1));
  assertEquals(tris.length, 9);
});

defineTest(SUITE, 'triangulation: concave L-shape → 4 triangles', () => {
  // L-shape (6 verts) → 4 triangles.
  const verts = [
    Vec3.fromValues(0, 0, 0),
    Vec3.fromValues(2, 0, 0),
    Vec3.fromValues(2, 1, 0),
    Vec3.fromValues(1, 1, 0),
    Vec3.fromValues(1, 2, 0),
    Vec3.fromValues(0, 2, 0),
  ];
  const tris = earClip(verts, Vec3.fromValues(0, 0, 1));
  assertEquals(tris.length / 3, 4);
});

defineTest(SUITE, 'render mesh for cube: 24 verts (6 faces × 4) and 12 tris', () => {
  const mesh = buildCube();
  const buf = buildRenderMesh(mesh);
  assertEquals(buf.vertexCount, 24);
  assertEquals(buf.triangleCount, 12);
  assertEquals(buf.indices.length, 36);
});

defineTest(SUITE, 'render mesh produces valid normals (unit length)', () => {
  const mesh = buildCube();
  const buf = buildRenderMesh(mesh);
  for (let i = 0; i < buf.vertexCount; i++) {
    const nx = buf.normals[i * 3 + 0];
    const ny = buf.normals[i * 3 + 1];
    const nz = buf.normals[i * 3 + 2];
    const len = Math.hypot(nx, ny, nz);
    assert(Math.abs(len - 1) < 1e-3, `vertex ${i} normal length ${len}`);
  }
});

defineTest(SUITE, 'render mesh uvs are populated (finite values in [0,1])', () => {
  const mesh = buildCube();
  const buf = buildRenderMesh(mesh);
  for (let i = 0; i < buf.vertexCount; i++) {
    const u = buf.uvs[i * 2];
    const v = buf.uvs[i * 2 + 1];
    assert(Number.isFinite(u) && Number.isFinite(v));
    assert(u >= 0 && u <= 1 && v >= 0 && v <= 1);
  }
});

defineTest(SUITE, 'render mesh marks dirty on construction; rebuild clears dirty', () => {
  const mesh = buildCube();
  const rm = new RenderMesh();
  assert(rm.isDirty());
  rm.rebuild(mesh);
  assert(!rm.isDirty());
});

defineTest(SUITE, 'render mesh rebuilds when topology changes (dirty propagation)', () => {
  const mesh = buildCube();
  const rm = new RenderMesh();
  rm.rebuild(mesh);
  const v0 = rm.version;
  rm.markDirty();
  rm.rebuild(mesh);
  assert(rm.version > v0);
});

defineTest(SUITE, 'render mesh for uv sphere has finite buffers and non-zero tris', () => {
  const m = buildUvSphere({ rings: 8, segments: 12 });
  const buf = buildRenderMesh(m);
  assert(buf.triangleCount > 0);
  for (let i = 0; i < buf.vertexCount * 3; i++) {
    assert(Number.isFinite(buf.positions[i]));
    assert(Number.isFinite(buf.normals[i]));
  }
});

defineTest(SUITE, 'hard edges break loop normals into discontinuous neighbours', () => {
  // Two adjacent quads sharing one edge. Mark it hard → loop normals on either side differ.
  const m = new EditableMesh();
  const a = m.addVertex(0, 0, 0).id;
  const b = m.addVertex(1, 0, 0).id;
  const c = m.addVertex(1, 1, 0).id;
  const d = m.addVertex(0, 1, 0).id;
  const e = m.addVertex(2, 0, 0).id;
  const f = m.addVertex(2, 1, 0).id;
  m.addFace([a, b, c, d]);
  // Second face shares b-c, bent up out of plane.
  // Re-add b and c at offset positions? Actually we share verts; just put e/f above the plane.
  // Move e and f to z=1 so the second face is in a different plane.
  m.vertices.get(e)!.position[2] = 1;
  m.vertices.get(f)!.position[2] = 1;
  m.addFace([b, e, f, c]);
  // Find edge b-c.
  let bc = null;
  for (const ed of m.edges.values()) {
    if ((ed.a === b && ed.b === c) || (ed.a === c && ed.b === b)) { bc = ed; break; }
  }
  m.recomputeFaceNormals();

  // Soft first — both loops at b across the seam should average normals.
  m.setEdgeHard(bc!.id, false);
  recomputeLoopNormals(m);
  const loopsAtB_soft: number[][] = [];
  for (const l of m.loops.values()) {
    if (l.vertexId === b) loopsAtB_soft.push([l.normal[0], l.normal[1], l.normal[2]]);
  }
  // Now hard — the two loops at b should land on their respective face normals.
  m.setEdgeHard(bc!.id, true);
  recomputeLoopNormals(m);
  const loopsAtB_hard: number[][] = [];
  for (const l of m.loops.values()) {
    if (l.vertexId === b) loopsAtB_hard.push([l.normal[0], l.normal[1], l.normal[2]]);
  }
  // Soft case: loops average to the same vector; hard case: they should diverge.
  // Distance between the two soft normals should be ~0.
  const dSoft = Math.hypot(
    loopsAtB_soft[0][0] - loopsAtB_soft[1][0],
    loopsAtB_soft[0][1] - loopsAtB_soft[1][1],
    loopsAtB_soft[0][2] - loopsAtB_soft[1][2],
  );
  const dHard = Math.hypot(
    loopsAtB_hard[0][0] - loopsAtB_hard[1][0],
    loopsAtB_hard[0][1] - loopsAtB_hard[1][1],
    loopsAtB_hard[0][2] - loopsAtB_hard[1][2],
  );
  assert(dHard > dSoft, `expected hard-edge normals to diverge more than soft (soft=${dSoft}, hard=${dHard})`);
});
