// Scene renderer — orchestrates grid + mesh passes per sub-viewport.

import { GridRenderer } from './GridRenderer';
import { MeshRenderer } from './MeshRenderer';
import { RenderMesh } from '../mesh/RenderMesh';
import { ViewportLayout } from './ViewportLayout';
import { StripBatch } from './StripRenderer';
import { UvRenderer } from './UvRenderer';
import { ReferenceImageRenderer } from './ReferenceImageRenderer';
import type { ReferenceImage } from '../scene/ReferenceImage';
import * as Vec3 from '../core/math/Vec3';
import * as Mat4 from '../core/math/Mat4';
import type { Scene } from '../scene/Scene';
import type { MeshObject } from '../scene/MeshObject';
import type { Selection } from '../app/Selection';
import type { ToolController } from '../app/ToolController';

interface MeshSlot {
  node: MeshObject;
  rm: RenderMesh;
}

export class Renderer {
  readonly gl: WebGL2RenderingContext;
  readonly layout = new ViewportLayout();
  private grid: GridRenderer;
  meshRenderer: MeshRenderer;
  uvRenderer: UvRenderer;
  refRenderer: ReferenceImageRenderer;
  private wireBatch: StripBatch;
  private highlightBatch: StripBatch;
  /** Toggled by App.setWireOverlay. */
  showWireOverlay = true;
  /** Optional selection — when set, edges/vertices belonging to selected objects render highlighted. */
  selection: Selection | null = null;
  /** Optional active-tool — when set, the current gizmo is rendered over the active object. */
  tools: ToolController | null = null;
  private gizmoBatch: StripBatch | null = null;
  private slots = new Map<number, MeshSlot>();

  constructor(gl: WebGL2RenderingContext) {
    this.gl = gl;
    this.grid = new GridRenderer(gl);
    this.meshRenderer = new MeshRenderer(gl);
    this.uvRenderer = new UvRenderer(gl);
    this.refRenderer = new ReferenceImageRenderer(gl);
    this.wireBatch = new StripBatch(gl);
    this.wireBatch.width = 1.2;
    this.wireBatch.alpha = 0.85;
    this.highlightBatch = new StripBatch(gl);
    this.highlightBatch.width = 3.0;
    this.highlightBatch.alpha = 1.0;
    this.gizmoBatch = new StripBatch(gl);
    this.gizmoBatch.width = 2.5;
    this.gizmoBatch.alpha = 1.0;
  }

  /** Ensure every mesh object in the scene has a RenderMesh slot. */
  syncScene(scene: Scene): void {
    const seen = new Set<number>();
    scene.forEachNode((n) => {
      if (n.kind !== 'mesh') return;
      const mo = n as MeshObject;
      if (!mo.mesh) return;
      seen.add(mo.id as unknown as number);
      let slot = this.slots.get(mo.id as unknown as number);
      if (!slot) {
        slot = { node: mo, rm: new RenderMesh() };
        slot.rm.markDirty();
        this.slots.set(mo.id as unknown as number, slot);
      }
    });
    // Drop orphaned slots.
    for (const key of Array.from(this.slots.keys())) {
      if (!seen.has(key)) this.slots.delete(key);
    }
  }

  /** Force rebuild of every render mesh — used after primitive creation. */
  markAllDirty(): void {
    for (const slot of this.slots.values()) slot.rm.markDirty();
  }

  setViewMode(mode: 'shaded' | 'xray' | 'textured' | 'unlit'): void {
    this.meshRenderer.mode = { shaded: 0, xray: 1, textured: 2, unlit: 3 }[mode];
  }

  /** Called from App.scenePass. */
  draw(scene: Scene, hostRect: { x: number; y: number; w: number; h: number }, dpr: number): void {
    const subviewports = this.layout.layout(hostRect);
    const { gl } = this;
    gl.enable(gl.SCISSOR_TEST);
    for (const sub of subviewports) {
      const sx = Math.floor(sub.rect.x * dpr);
      const sy = Math.floor(this.canvasHeight() - (sub.rect.y + sub.rect.h) * dpr);
      const sw = Math.max(1, Math.floor(sub.rect.w * dpr));
      const sh = Math.max(1, Math.floor(sub.rect.h * dpr));
      gl.viewport(sx, sy, sw, sh);
      gl.scissor(sx, sy, sw, sh);
      gl.clearColor(0.149, 0.149, 0.149, 1);
      gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);

      const aspect = sub.rect.w / Math.max(1, sub.rect.h);
      if (sub.name === 'uv') {
        const uvSel = this.selection
          ? { uvLoops: this.selection.selectedUvLoops }
          : null;
        this.uvRenderer.draw(scene, sub.camera, aspect, sub.rect.w * dpr, sub.rect.h * dpr, uvSel);
        continue;
      }
      this.grid.draw(sub.camera, aspect);
      // Reference images render behind meshes (no depth write — see ReferenceImageRenderer).
      scene.forEachNode((n) => {
        if (n.kind === 'reference') this.refRenderer.draw(n as ReferenceImage, sub.camera, aspect);
      });
      for (const slot of this.slots.values()) {
        if (!slot.node.mesh) continue;
        slot.rm.rebuild(slot.node.mesh, false);
        this.meshRenderer.upload(slot.rm);
        const mat = slot.node.materialId != null ? scene.getMaterial(slot.node.materialId) : null;
        this.meshRenderer.setMaterial(mat);
        this.meshRenderer.draw(slot.node, sub.camera, aspect);
      }
      if (this.showWireOverlay) {
        this.drawWireOverlay(sub.camera, aspect, sub.rect.w * dpr, sub.rect.h * dpr);
        if (this.selection) {
          this.drawSelectionHighlights(sub.camera, aspect, sub.rect.w * dpr, sub.rect.h * dpr);
        }
      }
      if (this.tools && this.gizmoBatch) {
        this.drawGizmo(sub.camera, sub.rect, aspect, dpr);
      }
    }
    gl.disable(gl.SCISSOR_TEST);
  }

  private canvasHeight(): number {
    return (this.gl.canvas as HTMLCanvasElement).height;
  }

  private drawGizmo(camera: ReturnType<ViewportLayout['layout']>[number]['camera'], rect: { x: number; y: number; w: number; h: number }, aspect: number, dpr: number): void {
    if (!this.tools || !this.gizmoBatch) return;
    const gizmo = this.tools.getActiveGizmo();
    if (!gizmo) return;
    const activeId = this.selection?.activeObjectId;
    if (!activeId) return;
    // Find the active scene node.
    let node = null;
    for (const slot of this.slots.values()) {
      if ((slot.node.id as unknown as number) === (activeId as unknown as number)) {
        node = slot.node;
        break;
      }
    }
    if (!node) return;
    this.gizmoBatch.reset();
    gizmo.render(this.gizmoBatch, node, camera, rect, aspect);
    // Render on top of mesh — clear depth comparison (still respect depth so
    // gizmo doesn't render through close geometry weirdly).
    this.gizmoBatch.draw(camera, aspect, rect.w * dpr, rect.h * dpr);
  }

  private drawWireOverlay(camera: ReturnType<ViewportLayout['layout']>[number]['camera'], aspect: number, vpW: number, vpH: number): void {
    this.wireBatch.reset();
    const tmpA = Vec3.create();
    const tmpB = Vec3.create();
    for (const slot of this.slots.values()) {
      const mesh = slot.node.mesh;
      if (!mesh) continue;
      const world = slot.node.getWorldMatrix();
      for (const edge of mesh.edges.values()) {
        const va = mesh.vertices.get(edge.a);
        const vb = mesh.vertices.get(edge.b);
        if (!va || !vb) continue;
        Mat4.transformPoint(tmpA, va.position, world);
        Mat4.transformPoint(tmpB, vb.position, world);
        const r = edge.hard ? 0.95 : 0.82;
        const g = edge.hard ? 0.55 : 0.82;
        const b = edge.seam ? 0.4 : 0.82;
        this.wireBatch.add(tmpA[0], tmpA[1], tmpA[2], tmpB[0], tmpB[1], tmpB[2], r, g, b);
      }
    }
    if (this.wireBatch.segmentCount() > 0) {
      this.wireBatch.draw(camera, aspect, vpW, vpH);
    }
  }

  private drawSelectionHighlights(camera: ReturnType<ViewportLayout['layout']>[number]['camera'], aspect: number, vpW: number, vpH: number): void {
    if (!this.selection) return;
    this.highlightBatch.reset();
    const tmpA = Vec3.create();
    const tmpB = Vec3.create();
    for (const slot of this.slots.values()) {
      const mesh = slot.node.mesh;
      if (!mesh) continue;
      const world = slot.node.getWorldMatrix();
      const objSelected = this.selection.isObjectSelected(slot.node.id);
      const edgeIds = this.selection.selectedEdges.get(slot.node.id);
      const faceIds = this.selection.selectedFaces.get(slot.node.id);
      const vertexIds = this.selection.selectedVertices.get(slot.node.id);

      // Object selected → outline the whole mesh (every edge in highlight color).
      if (objSelected) {
        for (const e of mesh.edges.values()) {
          const va = mesh.vertices.get(e.a);
          const vb = mesh.vertices.get(e.b);
          if (!va || !vb) continue;
          Mat4.transformPoint(tmpA, va.position, world);
          Mat4.transformPoint(tmpB, vb.position, world);
          this.highlightBatch.add(tmpA[0], tmpA[1], tmpA[2], tmpB[0], tmpB[1], tmpB[2], 1.0, 0.55, 0.15);
        }
      }
      // Selected face → outline its loops.
      if (faceIds) {
        for (const fid of faceIds) {
          const face = mesh.faces.get(fid);
          if (!face) continue;
          const verts = mesh.faceVertices(fid);
          for (let i = 0; i < verts.length; i++) {
            const next = verts[(i + 1) % verts.length];
            Mat4.transformPoint(tmpA, verts[i].position, world);
            Mat4.transformPoint(tmpB, next.position, world);
            this.highlightBatch.add(tmpA[0], tmpA[1], tmpA[2], tmpB[0], tmpB[1], tmpB[2], 0.95, 0.85, 0.2);
          }
          void face;
        }
      }
      // Selected edge → highlight.
      if (edgeIds) {
        for (const eid of edgeIds) {
          const e = mesh.edges.get(eid);
          if (!e) continue;
          const va = mesh.vertices.get(e.a);
          const vb = mesh.vertices.get(e.b);
          if (!va || !vb) continue;
          Mat4.transformPoint(tmpA, va.position, world);
          Mat4.transformPoint(tmpB, vb.position, world);
          this.highlightBatch.add(tmpA[0], tmpA[1], tmpA[2], tmpB[0], tmpB[1], tmpB[2], 1.0, 0.4, 0.1);
        }
      }
      // Selected vertex → draw a short cross at the vertex (4 short strips).
      if (vertexIds) {
        for (const vid of vertexIds) {
          const v = mesh.vertices.get(vid);
          if (!v) continue;
          Mat4.transformPoint(tmpA, v.position, world);
          const px = 0.02; // world-space offset for the cross; size scales with zoom but is fine for highlights.
          this.highlightBatch.add(tmpA[0] - px, tmpA[1], tmpA[2], tmpA[0] + px, tmpA[1], tmpA[2], 1.0, 0.85, 0.1);
          this.highlightBatch.add(tmpA[0], tmpA[1] - px, tmpA[2], tmpA[0], tmpA[1] + px, tmpA[2], 1.0, 0.85, 0.1);
          this.highlightBatch.add(tmpA[0], tmpA[1], tmpA[2] - px, tmpA[0], tmpA[1], tmpA[2] + px, 1.0, 0.85, 0.1);
        }
      }
    }
    if (this.highlightBatch.segmentCount() > 0) {
      this.highlightBatch.draw(camera, aspect, vpW, vpH);
    }
  }
}
