// ToolController — owns the active tool (Select / Move / Rotate / Scale),
// the active gizmo, and routes pointer events on the viewport. On gizmo
// drag, it modifies the node's transform live; on pointer-up, commits a
// single SetTransformCommand to the history.

import * as Vec3 from '../core/math/Vec3';
import type { App } from './App';
import { MoveGizmo } from '../gizmos/MoveGizmo';
import { RotateGizmo } from '../gizmos/RotateGizmo';
import { ScaleGizmo } from '../gizmos/ScaleGizmo';
import type { Gizmo, GizmoAxis } from '../gizmos/Gizmo';
import { SetTransformCommand, type TransformSnapshot } from './commands/SetTransformCommand';
import type { SceneNode } from '../scene/SceneNode';

export type ToolName = 'select' | 'move' | 'rotate' | 'scale';
export type TransformSpace = 'world' | 'object' | 'normal';

const TOOL_GIZMOS: Record<ToolName, Gizmo | null> = {
  select: null,
  move: new MoveGizmo(),
  rotate: new RotateGizmo(),
  scale: new ScaleGizmo(),
};

export class ToolController {
  private app: App;
  tool: ToolName = 'select';
  space: TransformSpace = 'world';
  private dragging: { axis: GizmoAxis; node: SceneNode; startSnapshot: TransformSnapshot; startX: number; startY: number } | null = null;

  constructor(app: App) {
    this.app = app;
  }

  setTool(t: ToolName): void {
    this.tool = t;
  }

  setSpace(s: TransformSpace): void {
    this.space = s;
  }

  getActiveGizmo(): Gizmo | null {
    return TOOL_GIZMOS[this.tool];
  }

  /** Try to start a gizmo drag at (screenX, screenY). Returns true on hit. */
  tryStartDrag(screenX: number, screenY: number): boolean {
    const gizmo = this.getActiveGizmo();
    if (!gizmo) return false;
    const node = this.activeNode();
    if (!node) return false;
    const sub = this.app.sceneRenderer.layout.subviewportAt(screenX, screenY);
    if (!sub) return false;
    const aspect = sub.rect.w / Math.max(1, sub.rect.h);
    const hit = gizmo.hit(screenX, screenY, node, sub.camera, sub.rect, aspect);
    if (!hit) return false;
    this.dragging = {
      axis: hit.axis,
      node,
      startSnapshot: snapshot(node),
      startX: screenX,
      startY: screenY,
    };
    return true;
  }

  isDragging(): boolean {
    return this.dragging != null;
  }

  drag(screenX: number, screenY: number): void {
    const d = this.dragging;
    if (!d) return;
    const dx = screenX - d.startX;
    const dy = screenY - d.startY;
    if (this.tool === 'move') this.applyMove(d, dx, dy);
    else if (this.tool === 'rotate') this.applyRotate(d, dx, dy);
    else if (this.tool === 'scale') this.applyScale(d, dx, dy);
  }

  endDrag(): void {
    const d = this.dragging;
    if (!d) return;
    const next = snapshot(d.node);
    // Avoid pushing a zero-delta command.
    const same =
      eq3(next.position, d.startSnapshot.position) &&
      eq4(next.rotation, d.startSnapshot.rotation) &&
      eq3(next.scale, d.startSnapshot.scale);
    if (!same) {
      // Revert before pushing so do() reapplies it.
      restore(d.node, d.startSnapshot);
      this.app.history.execute(new SetTransformCommand(d.node, next, this.commandLabelFor()));
    }
    this.dragging = null;
  }

  /** Drag state introspection (used by tests). */
  inspect(): { axis: GizmoAxis | null; tool: ToolName } {
    return { axis: this.dragging?.axis ?? null, tool: this.tool };
  }

  private activeNode(): SceneNode | null {
    if (!this.app.selection.activeObjectId) return null;
    return this.app.scene.findNodeById(this.app.selection.activeObjectId);
  }

  private commandLabelFor(): string {
    if (this.tool === 'move') return 'Move';
    if (this.tool === 'rotate') return 'Rotate';
    if (this.tool === 'scale') return 'Scale';
    return 'Transform';
  }

  private applyMove(d: NonNullable<ToolController['dragging']>, dx: number, dy: number): void {
    // Translate using pixel deltas converted to world units via the active camera distance.
    const sub = this.app.sceneRenderer.layout.subviewports()[0] ?? null;
    const cam = sub?.camera ?? this.app.sceneRenderer.layout.perspectiveCam;
    const origin = Vec3.create();
    const m = d.node.getWorldMatrix();
    origin[0] = m[12]; origin[1] = m[13]; origin[2] = m[14];
    const dist = Vec3.distance(origin, cam.position());
    const worldPerPx = 2 * Math.tan(cam.fovY / 2) * dist / Math.max(1, sub?.rect.h ?? 600);
    const wx = dx * worldPerPx;
    const wy = -dy * worldPerPx; // screen y down = world y up
    const newPos: [number, number, number] = [
      d.startSnapshot.position[0],
      d.startSnapshot.position[1],
      d.startSnapshot.position[2],
    ];
    if (d.axis === 'x') newPos[0] += wx;
    else if (d.axis === 'y') newPos[1] += wy;
    else if (d.axis === 'z') newPos[2] -= wx; // depth follows horizontal drag direction
    else { newPos[0] += wx; newPos[1] += wy; }
    d.node.transform.setPosition(newPos[0], newPos[1], newPos[2]);
    d.node.markWorldDirty();
  }

  private applyRotate(d: NonNullable<ToolController['dragging']>, dx: number, dy: number): void {
    // Compute angle from pixel delta along the gizmo's tangent direction.
    const angle = (dx + dy) * 0.005;
    const q = quatFromAxisAngle(d.axis, angle);
    const combined = quatMultiply(q, d.startSnapshot.rotation as [number, number, number, number]);
    d.node.transform.setRotationQuat(combined[0], combined[1], combined[2], combined[3]);
    d.node.markWorldDirty();
  }

  private applyScale(d: NonNullable<ToolController['dragging']>, dx: number, dy: number): void {
    const factor = 1 + (dx - dy) * 0.005;
    const s: [number, number, number] = [
      d.startSnapshot.scale[0],
      d.startSnapshot.scale[1],
      d.startSnapshot.scale[2],
    ];
    if (d.axis === 'x') s[0] *= factor;
    else if (d.axis === 'y') s[1] *= factor;
    else if (d.axis === 'z') s[2] *= factor;
    else { s[0] *= factor; s[1] *= factor; s[2] *= factor; }
    d.node.transform.setScale(s[0], s[1], s[2]);
    d.node.markWorldDirty();
  }
}

function snapshot(node: SceneNode): TransformSnapshot {
  return {
    position: [node.transform.position[0], node.transform.position[1], node.transform.position[2]],
    rotation: [node.transform.rotation[0], node.transform.rotation[1], node.transform.rotation[2], node.transform.rotation[3]],
    scale: [node.transform.scale[0], node.transform.scale[1], node.transform.scale[2]],
  };
}

function restore(node: SceneNode, s: TransformSnapshot): void {
  node.transform.setPosition(s.position[0], s.position[1], s.position[2]);
  node.transform.setRotationQuat(s.rotation[0], s.rotation[1], s.rotation[2], s.rotation[3]);
  node.transform.setScale(s.scale[0], s.scale[1], s.scale[2]);
  node.markWorldDirty();
}

function eq3(a: number[], b: number[]): boolean {
  return Math.abs(a[0] - b[0]) < 1e-7 && Math.abs(a[1] - b[1]) < 1e-7 && Math.abs(a[2] - b[2]) < 1e-7;
}

function eq4(a: number[], b: number[]): boolean {
  return Math.abs(a[0] - b[0]) < 1e-7 && Math.abs(a[1] - b[1]) < 1e-7 && Math.abs(a[2] - b[2]) < 1e-7 && Math.abs(a[3] - b[3]) < 1e-7;
}

function quatFromAxisAngle(axis: GizmoAxis, rad: number): [number, number, number, number] {
  const half = rad / 2;
  const s = Math.sin(half);
  const c = Math.cos(half);
  if (axis === 'x') return [s, 0, 0, c];
  if (axis === 'y') return [0, s, 0, c];
  if (axis === 'z') return [0, 0, s, c];
  // 'all' — rotate around (1,1,1) normalized.
  const inv = 1 / Math.sqrt(3);
  return [inv * s, inv * s, inv * s, c];
}

function quatMultiply(a: [number, number, number, number], b: [number, number, number, number]): [number, number, number, number] {
  return [
    a[0] * b[3] + a[3] * b[0] + a[1] * b[2] - a[2] * b[1],
    a[1] * b[3] + a[3] * b[1] + a[2] * b[0] - a[0] * b[2],
    a[2] * b[3] + a[3] * b[2] + a[0] * b[1] - a[1] * b[0],
    a[3] * b[3] - a[0] * b[0] - a[1] * b[1] - a[2] * b[2],
  ];
}
