// Mesh-snapshot wrapping for vertex-mode ops. We reuse the
// snapshot-the-whole-mesh strategy from ObjectCommands — coarse but
// simple, and topology validity is preserved on undo.

import type { Command } from '../Commands';
import { MeshObject } from '../../scene/MeshObject';
import { cloneMeshPreservingIds } from '../../mesh/MeshClone';
import {
  translateVerts, rotateVertsAroundAxis, scaleVerts,
  mergeVerts, weldVerts, deleteVertex, dissolveVertex,
  bevelVertex, smoothVerts, knifeCut,
} from '../../mesh/OperationsVertex';
import type { Id } from '../../core/Id';
import type { Vec3 as Vec3T } from '../../core/math/Vec3';

abstract class VertSnapshotCommand implements Command {
  protected node: MeshObject;
  private snap: ReturnType<typeof cloneMeshPreservingIds>;
  abstract readonly label: string;
  constructor(node: MeshObject) {
    this.node = node;
    if (!node.mesh) throw new Error('VertSnapshotCommand: missing mesh');
    this.snap = cloneMeshPreservingIds(node.mesh);
  }
  do(): void { if (this.node.mesh) this.apply(); }
  undo(): void { this.node.mesh = cloneMeshPreservingIds(this.snap); }
  protected abstract apply(): void;
}

export class TranslateVertsCommand extends VertSnapshotCommand {
  readonly label = 'Move Verts';
  constructor(node: MeshObject, private vertIds: Id[], private dx: number, private dy: number, private dz: number) { super(node); }
  protected apply(): void { translateVerts(this.node.mesh!, this.vertIds, this.dx, this.dy, this.dz); }
}

export class RotateVertsCommand extends VertSnapshotCommand {
  readonly label = 'Rotate Verts';
  constructor(node: MeshObject, private vertIds: Id[], private axis: 'x' | 'y' | 'z', private rad: number) { super(node); }
  protected apply(): void { rotateVertsAroundAxis(this.node.mesh!, this.vertIds, this.axis, this.rad); }
}

export class ScaleVertsCommand extends VertSnapshotCommand {
  readonly label = 'Scale Verts';
  constructor(node: MeshObject, private vertIds: Id[], private sx: number, private sy: number, private sz: number) { super(node); }
  protected apply(): void { scaleVerts(this.node.mesh!, this.vertIds, this.sx, this.sy, this.sz); }
}

export class MergeVertsCommand extends VertSnapshotCommand {
  readonly label = 'Merge Verts';
  constructor(node: MeshObject, private vertIds: Id[]) { super(node); }
  protected apply(): void { mergeVerts(this.node.mesh!, this.vertIds); }
}

export class WeldVertsCommand extends VertSnapshotCommand {
  readonly label = 'Weld Vert';
  constructor(node: MeshObject, private fromId: Id, private toId: Id) { super(node); }
  protected apply(): void { weldVerts(this.node.mesh!, this.fromId, this.toId); }
}

export class DeleteVertCommand extends VertSnapshotCommand {
  readonly label = 'Delete Vert';
  constructor(node: MeshObject, private vid: Id) { super(node); }
  protected apply(): void { deleteVertex(this.node.mesh!, this.vid); }
}

export class DissolveVertCommand extends VertSnapshotCommand {
  readonly label = 'Dissolve Vert';
  constructor(node: MeshObject, private vid: Id) { super(node); }
  protected apply(): void { dissolveVertex(this.node.mesh!, this.vid); }
}

export class BevelVertCommand extends VertSnapshotCommand {
  readonly label = 'Bevel Vert';
  constructor(node: MeshObject, private vid: Id, private offset = 0.1) { super(node); }
  protected apply(): void { bevelVertex(this.node.mesh!, this.vid, this.offset); }
}

export class SmoothVertsCommand extends VertSnapshotCommand {
  readonly label = 'Smooth Verts';
  constructor(node: MeshObject, private vertIds: Id[], private weight = 0.5) { super(node); }
  protected apply(): void { smoothVerts(this.node.mesh!, this.vertIds, this.weight); }
}

export class KnifeCommand extends VertSnapshotCommand {
  readonly label = 'Knife Cut';
  constructor(node: MeshObject, private p0: Vec3T, private p1: Vec3T) { super(node); }
  protected apply(): void { knifeCut(this.node.mesh!, this.p0, this.p1); }
}
