// UV-mode commands. Snapshots only the per-loop UVs of affected loops, so
// undo is fast (no full mesh clone).

import type { Command } from '../Commands';
import { MeshObject } from '../../scene/MeshObject';
import {
  translateUvLoops, scaleUvLoops, rotateUvLoops,
} from '../../mesh/OperationsUv';
import type { Id } from '../../core/Id';

interface UvSnapshot {
  loopId: Id;
  u: number;
  v: number;
}

function snapshotUvs(node: MeshObject, loopIds: Iterable<Id>): UvSnapshot[] {
  const out: UvSnapshot[] = [];
  if (!node.mesh) return out;
  for (const lid of loopIds) {
    const l = node.mesh.loops.get(lid);
    if (!l) continue;
    out.push({ loopId: lid, u: l.uv[0], v: l.uv[1] });
  }
  return out;
}

function restoreUvs(node: MeshObject, snap: UvSnapshot[]): void {
  if (!node.mesh) return;
  for (const s of snap) {
    const l = node.mesh.loops.get(s.loopId);
    if (!l) continue;
    l.uv[0] = s.u;
    l.uv[1] = s.v;
  }
}

export class TranslateUvLoopsCommand implements Command {
  readonly label = 'Move UVs';
  private snap: UvSnapshot[];
  constructor(private node: MeshObject, private loopIds: Id[], private du: number, private dv: number) {
    this.snap = snapshotUvs(node, loopIds);
  }
  do(): void {
    if (!this.node.mesh) return;
    translateUvLoops(this.node.mesh, this.loopIds, this.du, this.dv);
  }
  undo(): void { restoreUvs(this.node, this.snap); }
}

export class ScaleUvLoopsCommand implements Command {
  readonly label = 'Scale UVs';
  private snap: UvSnapshot[];
  constructor(private node: MeshObject, private loopIds: Id[], private sx: number, private sy: number, private pivotU = 0.5, private pivotV = 0.5) {
    this.snap = snapshotUvs(node, loopIds);
  }
  do(): void {
    if (!this.node.mesh) return;
    scaleUvLoops(this.node.mesh, this.loopIds, this.sx, this.sy, this.pivotU, this.pivotV);
  }
  undo(): void { restoreUvs(this.node, this.snap); }
}

export class RotateUvLoopsCommand implements Command {
  readonly label = 'Rotate UVs';
  private snap: UvSnapshot[];
  constructor(private node: MeshObject, private loopIds: Id[], private rad: number, private pivotU = 0.5, private pivotV = 0.5) {
    this.snap = snapshotUvs(node, loopIds);
  }
  do(): void {
    if (!this.node.mesh) return;
    rotateUvLoops(this.node.mesh, this.loopIds, this.rad, this.pivotU, this.pivotV);
  }
  undo(): void { restoreUvs(this.node, this.snap); }
}
