// Projection / unprojection helpers — viewport-to-NDC and back, plus the
// canonical "build a ray from a screen-space pixel" helper used by all
// CPU picking paths.

import * as Vec3 from './Vec3';
import * as Mat4 from './Mat4';
import type { Vec3 as Vec3T } from './Vec3';
import type { Ray } from './Ray';

/**
 * Map a screen-space pixel + NDC z (-1..1) back into world coordinates.
 * `vpRect` is the viewport in CSS pixels (origin = top-left, +Y down).
 * `viewProj` is the combined view-projection (view × projection).
 */
export function unproject(
  out: Vec3T,
  screenX: number,
  screenY: number,
  ndcZ: number,
  vpRect: { x: number; y: number; w: number; h: number },
  viewProj: Readonly<Float32Array>,
): Vec3T {
  const ndcX = ((screenX - vpRect.x) / vpRect.w) * 2 - 1;
  const ndcY = 1 - ((screenY - vpRect.y) / vpRect.h) * 2; // top-left origin → flip Y
  const inv = _scratch;
  if (!Mat4.invert(inv, viewProj)) {
    out[0] = 0; out[1] = 0; out[2] = 0;
    return out;
  }
  const x = ndcX, y = ndcY, z = ndcZ;
  const w = inv[3] * x + inv[7] * y + inv[11] * z + inv[15];
  out[0] = (inv[0] * x + inv[4] * y + inv[8] * z + inv[12]) / w;
  out[1] = (inv[1] * x + inv[5] * y + inv[9] * z + inv[13]) / w;
  out[2] = (inv[2] * x + inv[6] * y + inv[10] * z + inv[14]) / w;
  return out;
}

/**
 * Build a world-space ray for the given screen-space pixel.
 * The ray starts at the camera near-plane and points into the scene.
 */
export function screenPointToRay(
  outRay: Ray,
  screenX: number,
  screenY: number,
  vpRect: { x: number; y: number; w: number; h: number },
  viewProj: Readonly<Float32Array>,
): Ray {
  unproject(_p0, screenX, screenY, -1, vpRect, viewProj);
  unproject(_p1, screenX, screenY, 1, vpRect, viewProj);
  Vec3.copy(outRay.origin, _p0);
  Vec3.sub(outRay.direction, _p1, _p0);
  Vec3.normalize(outRay.direction, outRay.direction);
  return outRay;
}

/**
 * Project a world-space point into screen space. Returns true on success;
 * `outScreen[0,1]` get pixel coords (CSS pixels, top-left origin) and
 * `outScreen[2]` gets the NDC z (use for depth ordering).
 */
export function project(
  outScreen: Float32Array,
  world: Readonly<Vec3T>,
  vpRect: { x: number; y: number; w: number; h: number },
  viewProj: Readonly<Float32Array>,
): boolean {
  const x = world[0], y = world[1], z = world[2];
  const w = viewProj[3] * x + viewProj[7] * y + viewProj[11] * z + viewProj[15];
  if (Math.abs(w) < 1e-9) return false;
  const ndcX = (viewProj[0] * x + viewProj[4] * y + viewProj[8] * z + viewProj[12]) / w;
  const ndcY = (viewProj[1] * x + viewProj[5] * y + viewProj[9] * z + viewProj[13]) / w;
  const ndcZ = (viewProj[2] * x + viewProj[6] * y + viewProj[10] * z + viewProj[14]) / w;
  outScreen[0] = vpRect.x + (ndcX + 1) * 0.5 * vpRect.w;
  outScreen[1] = vpRect.y + (1 - ndcY) * 0.5 * vpRect.h;
  outScreen[2] = ndcZ;
  return true;
}

const _scratch = Mat4.create();
const _p0 = Vec3.create();
const _p1 = Vec3.create();
