// Vertex-mode operations.

import { EditableMesh } from './EditableMesh';
import * as Vec3 from '../core/math/Vec3';
import * as Quat from '../core/math/Quat';
import type { Id } from '../core/Id';

export function translateVerts(mesh: EditableMesh, vertIds: Iterable<Id>, dx: number, dy: number, dz: number): void {
  for (const id of vertIds) {
    const v = mesh.vertices.get(id);
    if (!v) continue;
    v.position[0] += dx;
    v.position[1] += dy;
    v.position[2] += dz;
  }
}

export function rotateVertsAroundAxis(
  mesh: EditableMesh,
  vertIds: Iterable<Id>,
  axis: 'x' | 'y' | 'z',
  rad: number,
  pivot: Readonly<Vec3.Vec3> = Vec3.fromValues(0, 0, 0),
): void {
  const axisVec = axis === 'x' ? Vec3.UNIT_X : axis === 'y' ? Vec3.UNIT_Y : Vec3.UNIT_Z;
  const q = Quat.setAxisAngle(Quat.create(), axisVec, rad);
  const tmp = Vec3.create();
  const rel = Vec3.create();
  for (const id of vertIds) {
    const v = mesh.vertices.get(id);
    if (!v) continue;
    Vec3.sub(rel, v.position, pivot);
    Quat.transformVec3(tmp, rel, q);
    v.position[0] = tmp[0] + pivot[0];
    v.position[1] = tmp[1] + pivot[1];
    v.position[2] = tmp[2] + pivot[2];
  }
}

export function scaleVerts(
  mesh: EditableMesh,
  vertIds: Iterable<Id>,
  sx: number,
  sy: number,
  sz: number,
  pivot: Readonly<Vec3.Vec3> = Vec3.fromValues(0, 0, 0),
): void {
  for (const id of vertIds) {
    const v = mesh.vertices.get(id);
    if (!v) continue;
    v.position[0] = pivot[0] + (v.position[0] - pivot[0]) * sx;
    v.position[1] = pivot[1] + (v.position[1] - pivot[1]) * sy;
    v.position[2] = pivot[2] + (v.position[2] - pivot[2]) * sz;
  }
}

/**
 * Merge a set of vertices into one at their centroid (or the supplied
 * target). All incident faces are rewired to use the new vertex; degenerate
 * faces (now < 3 unique verts) are deleted.
 */
export function mergeVerts(mesh: EditableMesh, vertIds: Iterable<Id>, targetPosition?: Readonly<Vec3.Vec3>): Id | null {
  const ids = Array.from(vertIds).filter((id) => mesh.vertices.has(id));
  if (ids.length < 2) return ids[0] ?? null;
  // Centroid position.
  let cx = 0, cy = 0, cz = 0;
  for (const id of ids) {
    const v = mesh.vertices.get(id)!;
    cx += v.position[0]; cy += v.position[1]; cz += v.position[2];
  }
  cx /= ids.length; cy /= ids.length; cz /= ids.length;
  if (targetPosition) {
    cx = targetPosition[0]; cy = targetPosition[1]; cz = targetPosition[2];
  }
  // Survivor = first vertex; move to centroid.
  const survivor = ids[0];
  const sv = mesh.vertices.get(survivor)!;
  sv.position[0] = cx; sv.position[1] = cy; sv.position[2] = cz;
  // Collect incident faces of all ids.
  const affectedFaces = new Set<Id>();
  for (const id of ids) {
    for (const fid of mesh.vertexFaces(id)) affectedFaces.add(fid);
  }
  // For each affected face, rewrite its vertex sequence using survivor.
  const idsSet = new Set(ids);
  const facesToReplace: Array<{ id: Id; verts: Id[]; materialId: Id | null }> = [];
  for (const fid of affectedFaces) {
    const face = mesh.faces.get(fid);
    if (!face) continue;
    const verts = face.loops.map((lid) => mesh.loops.get(lid)!.vertexId).map((v) => (idsSet.has(v) ? survivor : v));
    facesToReplace.push({ id: fid, verts, materialId: face.materialId });
  }
  for (const f of facesToReplace) mesh.removeFace(f.id);
  // Now delete the doomed verts (everyone but survivor).
  for (const id of ids) {
    if (id === survivor) continue;
    const v = mesh.vertices.get(id);
    if (!v) continue;
    // Remove residual edges referencing it.
    for (const eid of [...v.edges]) {
      const e = mesh.edges.get(eid);
      if (!e) continue;
      if (e.loops.length === 0) {
        mesh.edges.delete(eid);
        // Remove from the other endpoint's list too.
        const other = e.a === id ? e.b : e.a;
        const ov = mesh.vertices.get(other);
        if (ov) {
          const idx = ov.edges.indexOf(eid);
          if (idx >= 0) ov.edges.splice(idx, 1);
        }
      }
    }
    mesh.vertices.delete(id);
  }
  // Rebuild the affected faces, dropping degenerate ones (< 3 unique verts or duplicate adjacency).
  for (const f of facesToReplace) {
    const dedup: Id[] = [];
    for (let i = 0; i < f.verts.length; i++) {
      const cur = f.verts[i];
      const prev = dedup[dedup.length - 1];
      if (cur !== prev) dedup.push(cur);
    }
    if (dedup.length > 1 && dedup[0] === dedup[dedup.length - 1]) dedup.pop();
    if (dedup.length < 3) continue;
    mesh.addFace(dedup, f.materialId);
  }
  mesh.removeLooseGeometry();
  mesh.recomputeFaceNormals();
  return survivor;
}

/** Move `from` onto `to` and merge them. */
export function weldVerts(mesh: EditableMesh, fromId: Id, toId: Id): Id | null {
  const to = mesh.vertices.get(toId);
  if (!to) return null;
  return mergeVerts(mesh, [fromId, toId], to.position);
}

/** Remove a vertex along with every face that touches it. */
export function deleteVertex(mesh: EditableMesh, vid: Id): void {
  const v = mesh.vertices.get(vid);
  if (!v) return;
  const faces = Array.from(mesh.vertexFaces(vid));
  for (const fid of faces) mesh.removeFace(fid);
  mesh.removeLooseGeometry();
  mesh.vertices.delete(vid);
}

/**
 * Dissolve a vertex: remove it and rebuild the surrounding ring as a
 * single face. Only well-defined for manifold "umbrella" cases; we fall
 * back to delete behaviour when the ring isn't recoverable.
 */
export function dissolveVertex(mesh: EditableMesh, vid: Id): void {
  const v = mesh.vertices.get(vid);
  if (!v) return;
  const faces = Array.from(mesh.vertexFaces(vid));
  if (faces.length === 0) {
    mesh.vertices.delete(vid);
    return;
  }
  // Collect the ring of neighbours (vertices opposite to vid on each loop).
  const ring: Id[] = [];
  for (const fid of faces) {
    const face = mesh.faces.get(fid);
    if (!face) continue;
    const verts = face.loops.map((lid) => mesh.loops.get(lid)!.vertexId);
    const idx = verts.indexOf(vid);
    if (idx < 0) continue;
    const prev = verts[(idx - 1 + verts.length) % verts.length];
    const next = verts[(idx + 1) % verts.length];
    ring.push(prev);
    void next;
  }
  // Remove incident faces.
  for (const fid of faces) mesh.removeFace(fid);
  // Try to add a single n-gon from the ring (may fail if ring is too small).
  // Deduplicate consecutive matches.
  const dedup: Id[] = [];
  for (const r of ring) {
    if (dedup[dedup.length - 1] !== r) dedup.push(r);
  }
  if (dedup.length > 1 && dedup[0] === dedup[dedup.length - 1]) dedup.pop();
  if (dedup.length >= 3) {
    try {
      mesh.addFace(dedup);
    } catch {
      // Ring is malformed; leave as a hole.
    }
  }
  // Drop the now-isolated vertex + cleanup.
  mesh.vertices.delete(vid);
  mesh.removeLooseGeometry();
  mesh.recomputeFaceNormals();
}

/**
 * Replace a vertex with a triangle (or N-gon) by inserting new vertices
 * along each of its edges, offset toward the vertex's neighbours. This
 * is a coarse first-pass bevel; it works for any manifold corner.
 */
export function bevelVertex(mesh: EditableMesh, vid: Id, offset = 0.1): void {
  const v = mesh.vertices.get(vid);
  if (!v) return;
  const edges = [...v.edges].map((eid) => mesh.edges.get(eid)!).filter((e): e is import('./Topology').Edge => !!e);
  if (edges.length < 3) return;
  // For each edge, create a new vertex offset toward the other endpoint.
  const newVerts: Id[] = [];
  const newByEdge = new Map<Id, Id>();
  for (const e of edges) {
    const other = e.a === vid ? e.b : e.a;
    const ov = mesh.vertices.get(other);
    if (!ov) continue;
    const dir = Vec3.sub(Vec3.create(), ov.position, v.position);
    Vec3.normalize(dir, dir);
    const np = mesh.addVertex(v.position[0] + dir[0] * offset, v.position[1] + dir[1] * offset, v.position[2] + dir[2] * offset);
    newByEdge.set(e.id, np.id);
    newVerts.push(np.id);
  }
  // Collect the faces touching vid; rebuild each replacing vid with the appropriate new vertex.
  const faces = Array.from(mesh.vertexFaces(vid));
  const rebuilds: Array<{ verts: Id[]; mat: Id | null }> = [];
  for (const fid of faces) {
    const face = mesh.faces.get(fid);
    if (!face) continue;
    const seq = face.loops.map((lid) => mesh.loops.get(lid)!.vertexId);
    const idx = seq.indexOf(vid);
    if (idx < 0) continue;
    const prev = seq[(idx - 1 + seq.length) % seq.length];
    const next = seq[(idx + 1) % seq.length];
    // Find edges (vid-prev) and (vid-next), replace vid with the corresponding new verts.
    const edgePrev = mesh.edges.get(findEdgeId(mesh, vid, prev)!);
    const edgeNext = mesh.edges.get(findEdgeId(mesh, vid, next)!);
    if (!edgePrev || !edgeNext) continue;
    const newPrev = newByEdge.get(edgePrev.id);
    const newNext = newByEdge.get(edgeNext.id);
    const newSeq = [...seq];
    if (newPrev != null && newNext != null) {
      // Replace vid with two verts: at idx insert newPrev, idx+1 insert newNext.
      newSeq.splice(idx, 1, newPrev, newNext);
    }
    rebuilds.push({ verts: newSeq, mat: face.materialId });
  }
  for (const fid of faces) mesh.removeFace(fid);
  for (const r of rebuilds) {
    try {
      mesh.addFace(r.verts, r.mat);
    } catch {
      // Skip degenerate face.
    }
  }
  // Cap the vertex's neighbourhood with a small N-gon connecting the new verts.
  if (newVerts.length >= 3) {
    try {
      mesh.addFace(newVerts);
    } catch {
      // Ordering may not be planar; non-fatal.
    }
  }
  // Vertex is now isolated; delete it.
  mesh.vertices.delete(vid);
  mesh.removeLooseGeometry();
  mesh.recomputeFaceNormals();
}

/** Smooth selected vertices by averaging their neighbours' positions. */
export function smoothVerts(mesh: EditableMesh, vertIds: Iterable<Id>, weight = 0.5): void {
  // Collect neighbour positions first to avoid feedback during the pass.
  const newPositions = new Map<Id, [number, number, number]>();
  for (const id of vertIds) {
    const v = mesh.vertices.get(id);
    if (!v) continue;
    let nx = 0, ny = 0, nz = 0;
    let count = 0;
    for (const eid of v.edges) {
      const e = mesh.edges.get(eid);
      if (!e) continue;
      const other = e.a === id ? e.b : e.a;
      const ov = mesh.vertices.get(other);
      if (!ov) continue;
      nx += ov.position[0]; ny += ov.position[1]; nz += ov.position[2];
      count++;
    }
    if (count === 0) continue;
    newPositions.set(id, [
      v.position[0] + ((nx / count) - v.position[0]) * weight,
      v.position[1] + ((ny / count) - v.position[1]) * weight,
      v.position[2] + ((nz / count) - v.position[2]) * weight,
    ]);
  }
  for (const [id, p] of newPositions) {
    const v = mesh.vertices.get(id);
    if (!v) continue;
    v.position[0] = p[0]; v.position[1] = p[1]; v.position[2] = p[2];
  }
}

/**
 * Knife — insert a vertex at the midpoint of every edge that lies along
 * the world-XY line from `p0` to `p1`. A coarse first pass; intended to
 * unblock item 19's gate (vertex-producing knife op).
 */
export function knifeCut(mesh: EditableMesh, p0: Readonly<Vec3.Vec3>, p1: Readonly<Vec3.Vec3>): void {
  const _ = Vec3.distance(p0, p1);
  void _;
  const toInsert: Array<{ edgeId: Id; t: number }> = [];
  for (const e of mesh.edges.values()) {
    const va = mesh.vertices.get(e.a);
    const vb = mesh.vertices.get(e.b);
    if (!va || !vb) continue;
    const t = lineIntersectXY(va.position, vb.position, p0, p1);
    if (t == null) continue;
    if (t < 0.01 || t > 0.99) continue;
    toInsert.push({ edgeId: e.id, t });
  }
  // Insert new vertex per crossed edge; rebuild faces that touch the edge.
  for (const { edgeId, t } of toInsert) {
    const e = mesh.edges.get(edgeId);
    if (!e) continue;
    const va = mesh.vertices.get(e.a)!;
    const vb = mesh.vertices.get(e.b)!;
    const newVert = mesh.addVertex(
      va.position[0] + (vb.position[0] - va.position[0]) * t,
      va.position[1] + (vb.position[1] - va.position[1]) * t,
      va.position[2] + (vb.position[2] - va.position[2]) * t,
    );
    // For each face referencing this edge, insert newVert between a and b in the loop.
    const facesToRebuild: Array<{ id: Id; verts: Id[]; mat: Id | null }> = [];
    for (const lid of [...e.loops]) {
      const loop = mesh.loops.get(lid);
      if (!loop) continue;
      const face = mesh.faces.get(loop.faceId);
      if (!face) continue;
      const seq = face.loops.map((id) => mesh.loops.get(id)!.vertexId);
      // Find the edge in the sequence (consecutive vertices = e.a, e.b or e.b, e.a).
      for (let i = 0; i < seq.length; i++) {
        const cur = seq[i];
        const next = seq[(i + 1) % seq.length];
        if ((cur === e.a && next === e.b) || (cur === e.b && next === e.a)) {
          const newSeq = [...seq];
          newSeq.splice(i + 1, 0, newVert.id);
          facesToRebuild.push({ id: face.id, verts: newSeq, mat: face.materialId });
          break;
        }
      }
    }
    for (const fr of facesToRebuild) {
      mesh.removeFace(fr.id);
      try { mesh.addFace(fr.verts, fr.mat); } catch { /* ignore */ }
    }
  }
  mesh.recomputeFaceNormals();
}

function lineIntersectXY(a: Readonly<Vec3.Vec3>, b: Readonly<Vec3.Vec3>, p: Readonly<Vec3.Vec3>, q: Readonly<Vec3.Vec3>): number | null {
  const dx1 = b[0] - a[0], dy1 = b[1] - a[1];
  const dx2 = q[0] - p[0], dy2 = q[1] - p[1];
  const denom = dx1 * dy2 - dy1 * dx2;
  if (Math.abs(denom) < 1e-9) return null;
  const t = ((p[0] - a[0]) * dy2 - (p[1] - a[1]) * dx2) / denom;
  return t;
}

function findEdgeId(mesh: EditableMesh, a: Id, b: Id): Id | null {
  const va = mesh.vertices.get(a);
  if (!va) return null;
  for (const eid of va.edges) {
    const e = mesh.edges.get(eid);
    if (!e) continue;
    if ((e.a === a && e.b === b) || (e.a === b && e.b === a)) return eid;
  }
  return null;
}
