// CPU picking — ray-tests against generated triangles for object/face
// picks, screen-space distance for vertex/edge picks.

import * as Vec3 from '../core/math/Vec3';
import * as Mat4 from '../core/math/Mat4';
import * as RayMath from '../core/math/Ray';
import * as Project from '../core/math/Project';
import type { EditableMesh } from '../mesh/EditableMesh';
import type { Scene } from '../scene/Scene';
import type { MeshObject } from '../scene/MeshObject';
import type { Camera } from '../render/Camera';
import type { Id } from '../core/Id';

export interface ObjectPickHit {
  node: MeshObject;
  t: number;
  faceId: Id;
}

export function pickObjectInScene(
  scene: Scene,
  screenX: number,
  screenY: number,
  vpRect: { x: number; y: number; w: number; h: number },
  camera: Camera,
  aspect: number,
): ObjectPickHit | null {
  const worldRay = RayMath.create();
  const viewProj = camera.viewProj(aspect);
  Project.screenPointToRay(worldRay, screenX, screenY, vpRect, viewProj as Float32Array);

  let best: ObjectPickHit | null = null;
  scene.forEachNode((n) => {
    if (n.kind !== 'mesh') return;
    const mo = n as MeshObject;
    if (!mo.mesh) return;
    const local = transformRayToLocal(worldRay, mo.getWorldMatrix());
    const hit = rayTestMesh(mo.mesh, local);
    if (hit && (!best || hit.t < best.t)) {
      best = { node: mo, t: hit.t, faceId: hit.faceId };
    }
  });
  return best;
}

export function pickFace(
  mesh: EditableMesh,
  worldMatrix: Readonly<Mat4.Mat4>,
  screenX: number,
  screenY: number,
  vpRect: { x: number; y: number; w: number; h: number },
  camera: Camera,
  aspect: number,
): Id | null {
  const worldRay = RayMath.create();
  Project.screenPointToRay(worldRay, screenX, screenY, vpRect, camera.viewProj(aspect) as Float32Array);
  const local = transformRayToLocal(worldRay, worldMatrix);
  const hit = rayTestMesh(mesh, local);
  return hit?.faceId ?? null;
}

export function pickVertex(
  mesh: EditableMesh,
  worldMatrix: Readonly<Mat4.Mat4>,
  screenX: number,
  screenY: number,
  vpRect: { x: number; y: number; w: number; h: number },
  camera: Camera,
  aspect: number,
  thresholdPx = 8,
): Id | null {
  const viewProj = camera.viewProj(aspect) as Float32Array;
  const world = Vec3.create();
  const projOut = new Float32Array(3);
  let bestId: Id | null = null;
  let bestDist = thresholdPx * thresholdPx;
  for (const v of mesh.vertices.values()) {
    Mat4.transformPoint(world, v.position, worldMatrix);
    if (!Project.project(projOut, world, vpRect, viewProj)) continue;
    if (projOut[2] < -1 || projOut[2] > 1) continue;
    const dx = projOut[0] - screenX;
    const dy = projOut[1] - screenY;
    const d2 = dx * dx + dy * dy;
    if (d2 < bestDist) {
      bestDist = d2;
      bestId = v.id;
    }
  }
  return bestId;
}

export function pickEdge(
  mesh: EditableMesh,
  worldMatrix: Readonly<Mat4.Mat4>,
  screenX: number,
  screenY: number,
  vpRect: { x: number; y: number; w: number; h: number },
  camera: Camera,
  aspect: number,
  thresholdPx = 6,
): Id | null {
  const viewProj = camera.viewProj(aspect) as Float32Array;
  const aWorld = Vec3.create(), bWorld = Vec3.create();
  const aProj = new Float32Array(3), bProj = new Float32Array(3);
  let bestId: Id | null = null;
  let bestDist = thresholdPx * thresholdPx;
  for (const e of mesh.edges.values()) {
    const va = mesh.vertices.get(e.a);
    const vb = mesh.vertices.get(e.b);
    if (!va || !vb) continue;
    Mat4.transformPoint(aWorld, va.position, worldMatrix);
    Mat4.transformPoint(bWorld, vb.position, worldMatrix);
    if (!Project.project(aProj, aWorld, vpRect, viewProj)) continue;
    if (!Project.project(bProj, bWorld, vpRect, viewProj)) continue;
    if ((aProj[2] < -1 || aProj[2] > 1) && (bProj[2] < -1 || bProj[2] > 1)) continue;
    const d2 = pointSegmentDistanceSq(screenX, screenY, aProj[0], aProj[1], bProj[0], bProj[1]);
    if (d2 < bestDist) {
      bestDist = d2;
      bestId = e.id;
    }
  }
  return bestId;
}

function pointSegmentDistanceSq(px: number, py: number, ax: number, ay: number, bx: number, by: number): number {
  const dx = bx - ax, dy = by - ay;
  const lenSq = dx * dx + dy * dy;
  if (lenSq < 1e-9) {
    const ex = px - ax, ey = py - ay;
    return ex * ex + ey * ey;
  }
  let t = ((px - ax) * dx + (py - ay) * dy) / lenSq;
  t = Math.max(0, Math.min(1, t));
  const cx = ax + t * dx;
  const cy = ay + t * dy;
  const ex = px - cx, ey = py - cy;
  return ex * ex + ey * ey;
}

interface MeshPickHit {
  t: number;
  faceId: Id;
}

function rayTestMesh(mesh: EditableMesh, ray: RayMath.Ray): MeshPickHit | null {
  let best: MeshPickHit | null = null;
  for (const f of mesh.faces.values()) {
    const verts = mesh.faceVertices(f.id);
    // Fan triangulation about vertex 0 — same convention as buildBuffers'
    // simple-quad path; good enough for picking.
    for (let i = 1; i < verts.length - 1; i++) {
      const t = RayMath.intersectTriangle(ray, verts[0].position, verts[i].position, verts[i + 1].position, undefined, true);
      if (!Number.isNaN(t) && (!best || t < best.t)) {
        best = { t, faceId: f.id };
      }
    }
  }
  return best;
}

function transformRayToLocal(worldRay: RayMath.Ray, worldMatrix: Readonly<Mat4.Mat4>): RayMath.Ray {
  const inv = _scratch;
  const localRay: RayMath.Ray = { origin: Vec3.create(), direction: Vec3.create() };
  if (!Mat4.invert(inv, worldMatrix as Float32Array)) {
    Vec3.copy(localRay.origin, worldRay.origin);
    Vec3.copy(localRay.direction, worldRay.direction);
    return localRay;
  }
  Mat4.transformPoint(localRay.origin, worldRay.origin, inv);
  // Transform direction by the rotation part only (ignore translation).
  Mat4.transformDirection(localRay.direction, worldRay.direction, inv);
  Vec3.normalize(localRay.direction, localRay.direction);
  return localRay;
}

const _scratch = Mat4.create();
