// Ear-clipping triangulation for planar polygons.
//
// Project the 3D polygon to its dominant 2D plane (using the largest
// absolute component of the face normal as the projection axis), then
// ear-clip in 2D. Output is an index list into the original loop array:
// flat array of length 3*(n-2).

import * as Vec3 from '../core/math/Vec3';

export interface PlanarProjection {
  uAxis: 0 | 1 | 2;
  vAxis: 0 | 1 | 2;
  flip: boolean;
}

/**
 * Pick the projection plane that drops the smallest dimension of the
 * polygon. The `flip` flag inverts the V axis when needed so the 2D
 * polygon retains the original CCW winding.
 */
export function pickPlanarProjection(normal: Readonly<Vec3.Vec3>): PlanarProjection {
  const nx = Math.abs(normal[0]);
  const ny = Math.abs(normal[1]);
  const nz = Math.abs(normal[2]);
  if (nx >= ny && nx >= nz) return { uAxis: 1, vAxis: 2, flip: normal[0] < 0 };
  if (ny >= nx && ny >= nz) return { uAxis: 2, vAxis: 0, flip: normal[1] < 0 };
  return { uAxis: 0, vAxis: 1, flip: normal[2] < 0 };
}

/**
 * Triangulate a planar polygon defined by `positions` (Vec3-per-vertex).
 * Returns flat triangle indices into the input array.
 * If the polygon is degenerate the result may contain fewer than `(n-2)`
 * triangles; callers should accept that gracefully.
 */
export function earClip(positions: Array<Readonly<Vec3.Vec3>>, normal: Readonly<Vec3.Vec3>): number[] {
  const n = positions.length;
  if (n < 3) return [];
  if (n === 3) return [0, 1, 2];

  const proj = pickPlanarProjection(normal);
  const xs = new Float64Array(n);
  const ys = new Float64Array(n);
  for (let i = 0; i < n; i++) {
    xs[i] = positions[i][proj.uAxis];
    ys[i] = positions[i][proj.vAxis] * (proj.flip ? -1 : 1);
  }

  // Linked-list polygon. Each node carries the source index.
  const prev = new Int32Array(n);
  const next = new Int32Array(n);
  for (let i = 0; i < n; i++) {
    prev[i] = (i - 1 + n) % n;
    next[i] = (i + 1) % n;
  }

  const tris: number[] = [];
  let remaining = n;
  let i = 0;
  let attempts = 0;
  const maxAttempts = n * 4;
  while (remaining > 3 && attempts < maxAttempts) {
    const a = prev[i];
    const b = i;
    const c = next[i];
    if (isEar(a, b, c, prev, next, xs, ys)) {
      tris.push(a, b, c);
      next[a] = c;
      prev[c] = a;
      remaining--;
      // Step back in case the new ear was created next to us.
      i = a;
      attempts = 0;
    } else {
      i = next[i];
      attempts++;
    }
  }
  if (remaining === 3) {
    tris.push(prev[i], i, next[i]);
  }
  return tris;
}

function isEar(a: number, b: number, c: number, prev: Int32Array, next: Int32Array, xs: Float64Array, ys: Float64Array): boolean {
  const ax = xs[a], ay = ys[a];
  const bx = xs[b], by = ys[b];
  const cx = xs[c], cy = ys[c];
  // Triangle is degenerate.
  const area2 = (bx - ax) * (cy - ay) - (cx - ax) * (by - ay);
  if (Math.abs(area2) < 1e-12) return false;

  // Determine winding of the whole polygon by walking once.
  // (Cheap recompute for small n; ear clipping is O(n²) anyway.)
  let polyArea2 = 0;
  let p = b;
  do {
    const i1 = p;
    const i2 = next[p];
    polyArea2 += (xs[i1] * ys[i2]) - (xs[i2] * ys[i1]);
    p = i2;
  } while (p !== b);
  const ccw = polyArea2 > 0;
  if (ccw && area2 <= 0) return false;
  if (!ccw && area2 >= 0) return false;

  // No other vertex may lie inside this triangle.
  for (let p2 = next[c]; p2 !== a; p2 = next[p2]) {
    if (pointInTriangle(xs[p2], ys[p2], ax, ay, bx, by, cx, cy)) return false;
  }
  return true;
}

function pointInTriangle(px: number, py: number, ax: number, ay: number, bx: number, by: number, cx: number, cy: number): boolean {
  const v0x = cx - ax, v0y = cy - ay;
  const v1x = bx - ax, v1y = by - ay;
  const v2x = px - ax, v2y = py - ay;
  const dot00 = v0x * v0x + v0y * v0y;
  const dot01 = v0x * v1x + v0y * v1y;
  const dot02 = v0x * v2x + v0y * v2y;
  const dot11 = v1x * v1x + v1y * v1y;
  const dot12 = v1x * v2x + v1y * v2y;
  const denom = dot00 * dot11 - dot01 * dot01;
  if (Math.abs(denom) < 1e-18) return false;
  const inv = 1 / denom;
  const u = (dot11 * dot02 - dot01 * dot12) * inv;
  const v = (dot00 * dot12 - dot01 * dot02) * inv;
  return u > 1e-9 && v > 1e-9 && u + v < 1 - 1e-9;
}
