// 4x4 matrix, column-major (matches WebGL's uniformMatrix4fv with transpose=false).
//
// Indexing: m[col * 4 + row].
//   m[0]=m00 m[4]=m01 m[ 8]=m02 m[12]=m03
//   m[1]=m10 m[5]=m11 m[ 9]=m12 m[13]=m13
//   m[2]=m20 m[6]=m21 m[10]=m22 m[14]=m23
//   m[3]=m30 m[7]=m31 m[11]=m32 m[15]=m33

import type { Vec3 } from './Vec3';

export type Mat4 = Float32Array;

export function create(): Mat4 {
  const m = new Float32Array(16);
  m[0] = 1;
  m[5] = 1;
  m[10] = 1;
  m[15] = 1;
  return m;
}

export function identity(out: Mat4): Mat4 {
  out[0] = 1; out[1] = 0; out[2] = 0; out[3] = 0;
  out[4] = 0; out[5] = 1; out[6] = 0; out[7] = 0;
  out[8] = 0; out[9] = 0; out[10] = 1; out[11] = 0;
  out[12] = 0; out[13] = 0; out[14] = 0; out[15] = 1;
  return out;
}

export function copy(out: Mat4, a: Readonly<Mat4>): Mat4 {
  for (let i = 0; i < 16; i++) out[i] = a[i];
  return out;
}

export function fromTranslation(out: Mat4, t: Readonly<Vec3>): Mat4 {
  identity(out);
  out[12] = t[0];
  out[13] = t[1];
  out[14] = t[2];
  return out;
}

export function fromScale(out: Mat4, s: Readonly<Vec3>): Mat4 {
  identity(out);
  out[0] = s[0];
  out[5] = s[1];
  out[10] = s[2];
  return out;
}

export function fromRotationX(out: Mat4, rad: number): Mat4 {
  const c = Math.cos(rad), s = Math.sin(rad);
  identity(out);
  out[5] = c; out[6] = s;
  out[9] = -s; out[10] = c;
  return out;
}

export function fromRotationY(out: Mat4, rad: number): Mat4 {
  const c = Math.cos(rad), s = Math.sin(rad);
  identity(out);
  out[0] = c; out[2] = -s;
  out[8] = s; out[10] = c;
  return out;
}

export function fromRotationZ(out: Mat4, rad: number): Mat4 {
  const c = Math.cos(rad), s = Math.sin(rad);
  identity(out);
  out[0] = c; out[1] = s;
  out[4] = -s; out[5] = c;
  return out;
}

export function multiply(out: Mat4, a: Readonly<Mat4>, b: Readonly<Mat4>): Mat4 {
  const a00 = a[0], a01 = a[1], a02 = a[2], a03 = a[3];
  const a10 = a[4], a11 = a[5], a12 = a[6], a13 = a[7];
  const a20 = a[8], a21 = a[9], a22 = a[10], a23 = a[11];
  const a30 = a[12], a31 = a[13], a32 = a[14], a33 = a[15];

  let b0 = b[0], b1 = b[1], b2 = b[2], b3 = b[3];
  out[0] = a00 * b0 + a10 * b1 + a20 * b2 + a30 * b3;
  out[1] = a01 * b0 + a11 * b1 + a21 * b2 + a31 * b3;
  out[2] = a02 * b0 + a12 * b1 + a22 * b2 + a32 * b3;
  out[3] = a03 * b0 + a13 * b1 + a23 * b2 + a33 * b3;

  b0 = b[4]; b1 = b[5]; b2 = b[6]; b3 = b[7];
  out[4] = a00 * b0 + a10 * b1 + a20 * b2 + a30 * b3;
  out[5] = a01 * b0 + a11 * b1 + a21 * b2 + a31 * b3;
  out[6] = a02 * b0 + a12 * b1 + a22 * b2 + a32 * b3;
  out[7] = a03 * b0 + a13 * b1 + a23 * b2 + a33 * b3;

  b0 = b[8]; b1 = b[9]; b2 = b[10]; b3 = b[11];
  out[8] = a00 * b0 + a10 * b1 + a20 * b2 + a30 * b3;
  out[9] = a01 * b0 + a11 * b1 + a21 * b2 + a31 * b3;
  out[10] = a02 * b0 + a12 * b1 + a22 * b2 + a32 * b3;
  out[11] = a03 * b0 + a13 * b1 + a23 * b2 + a33 * b3;

  b0 = b[12]; b1 = b[13]; b2 = b[14]; b3 = b[15];
  out[12] = a00 * b0 + a10 * b1 + a20 * b2 + a30 * b3;
  out[13] = a01 * b0 + a11 * b1 + a21 * b2 + a31 * b3;
  out[14] = a02 * b0 + a12 * b1 + a22 * b2 + a32 * b3;
  out[15] = a03 * b0 + a13 * b1 + a23 * b2 + a33 * b3;

  return out;
}

export function transpose(out: Mat4, a: Readonly<Mat4>): Mat4 {
  if (out === a) {
    const a01 = a[1], a02 = a[2], a03 = a[3];
    const a12 = a[6], a13 = a[7];
    const a23 = a[11];
    out[1] = a[4]; out[2] = a[8]; out[3] = a[12];
    out[4] = a01; out[6] = a[9]; out[7] = a[13];
    out[8] = a02; out[9] = a12; out[11] = a[14];
    out[12] = a03; out[13] = a13; out[14] = a23;
  } else {
    out[0] = a[0]; out[1] = a[4]; out[2] = a[8]; out[3] = a[12];
    out[4] = a[1]; out[5] = a[5]; out[6] = a[9]; out[7] = a[13];
    out[8] = a[2]; out[9] = a[6]; out[10] = a[10]; out[11] = a[14];
    out[12] = a[3]; out[13] = a[7]; out[14] = a[11]; out[15] = a[15];
  }
  return out;
}

export function invert(out: Mat4, a: Readonly<Mat4>): Mat4 | null {
  const a00 = a[0], a01 = a[1], a02 = a[2], a03 = a[3];
  const a10 = a[4], a11 = a[5], a12 = a[6], a13 = a[7];
  const a20 = a[8], a21 = a[9], a22 = a[10], a23 = a[11];
  const a30 = a[12], a31 = a[13], a32 = a[14], a33 = a[15];

  const b00 = a00 * a11 - a01 * a10;
  const b01 = a00 * a12 - a02 * a10;
  const b02 = a00 * a13 - a03 * a10;
  const b03 = a01 * a12 - a02 * a11;
  const b04 = a01 * a13 - a03 * a11;
  const b05 = a02 * a13 - a03 * a12;
  const b06 = a20 * a31 - a21 * a30;
  const b07 = a20 * a32 - a22 * a30;
  const b08 = a20 * a33 - a23 * a30;
  const b09 = a21 * a32 - a22 * a31;
  const b10 = a21 * a33 - a23 * a31;
  const b11 = a22 * a33 - a23 * a32;

  let det = b00 * b11 - b01 * b10 + b02 * b09 + b03 * b08 - b04 * b07 + b05 * b06;
  if (!det) return null;
  det = 1.0 / det;

  out[0] = (a11 * b11 - a12 * b10 + a13 * b09) * det;
  out[1] = (a02 * b10 - a01 * b11 - a03 * b09) * det;
  out[2] = (a31 * b05 - a32 * b04 + a33 * b03) * det;
  out[3] = (a22 * b04 - a21 * b05 - a23 * b03) * det;
  out[4] = (a12 * b08 - a10 * b11 - a13 * b07) * det;
  out[5] = (a00 * b11 - a02 * b08 + a03 * b07) * det;
  out[6] = (a32 * b02 - a30 * b05 - a33 * b01) * det;
  out[7] = (a20 * b05 - a22 * b02 + a23 * b01) * det;
  out[8] = (a10 * b10 - a11 * b08 + a13 * b06) * det;
  out[9] = (a01 * b08 - a00 * b10 - a03 * b06) * det;
  out[10] = (a30 * b04 - a31 * b02 + a33 * b00) * det;
  out[11] = (a21 * b02 - a20 * b04 - a23 * b00) * det;
  out[12] = (a11 * b07 - a10 * b09 - a12 * b06) * det;
  out[13] = (a00 * b09 - a01 * b07 + a02 * b06) * det;
  out[14] = (a31 * b01 - a30 * b03 - a32 * b00) * det;
  out[15] = (a20 * b03 - a21 * b01 + a22 * b00) * det;

  return out;
}

export function perspective(out: Mat4, fovyRad: number, aspect: number, near: number, far: number): Mat4 {
  const f = 1.0 / Math.tan(fovyRad / 2);
  const nf = 1 / (near - far);
  out[0] = f / aspect; out[1] = 0; out[2] = 0; out[3] = 0;
  out[4] = 0; out[5] = f; out[6] = 0; out[7] = 0;
  out[8] = 0; out[9] = 0; out[10] = (far + near) * nf; out[11] = -1;
  out[12] = 0; out[13] = 0; out[14] = 2 * far * near * nf; out[15] = 0;
  return out;
}

export function ortho(out: Mat4, left: number, right: number, bottom: number, top: number, near: number, far: number): Mat4 {
  const lr = 1 / (left - right);
  const bt = 1 / (bottom - top);
  const nf = 1 / (near - far);
  out[0] = -2 * lr; out[1] = 0; out[2] = 0; out[3] = 0;
  out[4] = 0; out[5] = -2 * bt; out[6] = 0; out[7] = 0;
  out[8] = 0; out[9] = 0; out[10] = 2 * nf; out[11] = 0;
  out[12] = (left + right) * lr;
  out[13] = (top + bottom) * bt;
  out[14] = (far + near) * nf;
  out[15] = 1;
  return out;
}

export function lookAt(out: Mat4, eye: Readonly<Vec3>, target: Readonly<Vec3>, up: Readonly<Vec3>): Mat4 {
  const eyex = eye[0], eyey = eye[1], eyez = eye[2];
  const upx = up[0], upy = up[1], upz = up[2];
  const tx = target[0], ty = target[1], tz = target[2];

  if (Math.abs(eyex - tx) < 1e-6 && Math.abs(eyey - ty) < 1e-6 && Math.abs(eyez - tz) < 1e-6) {
    return identity(out);
  }

  let z0 = eyex - tx;
  let z1 = eyey - ty;
  let z2 = eyez - tz;
  let len = 1 / Math.hypot(z0, z1, z2);
  z0 *= len; z1 *= len; z2 *= len;

  let x0 = upy * z2 - upz * z1;
  let x1 = upz * z0 - upx * z2;
  let x2 = upx * z1 - upy * z0;
  len = Math.hypot(x0, x1, x2);
  if (!len) {
    x0 = 0; x1 = 0; x2 = 0;
  } else {
    len = 1 / len;
    x0 *= len; x1 *= len; x2 *= len;
  }

  let y0 = z1 * x2 - z2 * x1;
  let y1 = z2 * x0 - z0 * x2;
  let y2 = z0 * x1 - z1 * x0;
  len = Math.hypot(y0, y1, y2);
  if (!len) {
    y0 = 0; y1 = 0; y2 = 0;
  } else {
    len = 1 / len;
    y0 *= len; y1 *= len; y2 *= len;
  }

  out[0] = x0; out[1] = y0; out[2] = z0; out[3] = 0;
  out[4] = x1; out[5] = y1; out[6] = z1; out[7] = 0;
  out[8] = x2; out[9] = y2; out[10] = z2; out[11] = 0;
  out[12] = -(x0 * eyex + x1 * eyey + x2 * eyez);
  out[13] = -(y0 * eyex + y1 * eyey + y2 * eyez);
  out[14] = -(z0 * eyex + z1 * eyey + z2 * eyez);
  out[15] = 1;
  return out;
}

/** Transform a Vec3 as a point (w=1). */
export function transformPoint(out: Vec3, p: Readonly<Vec3>, m: Readonly<Mat4>): Vec3 {
  const x = p[0], y = p[1], z = p[2];
  const w = m[3] * x + m[7] * y + m[11] * z + m[15] || 1.0;
  out[0] = (m[0] * x + m[4] * y + m[8] * z + m[12]) / w;
  out[1] = (m[1] * x + m[5] * y + m[9] * z + m[13]) / w;
  out[2] = (m[2] * x + m[6] * y + m[10] * z + m[14]) / w;
  return out;
}

/** Transform a Vec3 as a direction (w=0, no translation, no perspective). */
export function transformDirection(out: Vec3, d: Readonly<Vec3>, m: Readonly<Mat4>): Vec3 {
  const x = d[0], y = d[1], z = d[2];
  out[0] = m[0] * x + m[4] * y + m[8] * z;
  out[1] = m[1] * x + m[5] * y + m[9] * z;
  out[2] = m[2] * x + m[6] * y + m[10] * z;
  return out;
}

export function equalsApprox(a: Readonly<Mat4>, b: Readonly<Mat4>, eps = 1e-5): boolean {
  for (let i = 0; i < 16; i++) {
    if (Math.abs(a[i] - b[i]) > eps) return false;
  }
  return true;
}

export function trs(out: Mat4, t: Readonly<Vec3>, qXYZW: Readonly<[number, number, number, number] | Float32Array>, s: Readonly<Vec3>): Mat4 {
  // Quaternion → rotation matrix, then bake translation and scale.
  const qx = qXYZW[0], qy = qXYZW[1], qz = qXYZW[2], qw = qXYZW[3];
  const x2 = qx + qx;
  const y2 = qy + qy;
  const z2 = qz + qz;
  const xx = qx * x2;
  const xy = qx * y2;
  const xz = qx * z2;
  const yy = qy * y2;
  const yz = qy * z2;
  const zz = qz * z2;
  const wx = qw * x2;
  const wy = qw * y2;
  const wz = qw * z2;
  const sx = s[0], sy = s[1], sz = s[2];

  out[0] = (1 - (yy + zz)) * sx;
  out[1] = (xy + wz) * sx;
  out[2] = (xz - wy) * sx;
  out[3] = 0;

  out[4] = (xy - wz) * sy;
  out[5] = (1 - (xx + zz)) * sy;
  out[6] = (yz + wx) * sy;
  out[7] = 0;

  out[8] = (xz + wy) * sz;
  out[9] = (yz - wx) * sz;
  out[10] = (1 - (xx + yy)) * sz;
  out[11] = 0;

  out[12] = t[0];
  out[13] = t[1];
  out[14] = t[2];
  out[15] = 1;
  return out;
}
