// Branded numeric id type + monotonic generator.

export type Id = number & { readonly __brand: 'Id' };

let _next = 1;

export function nextId(): Id {
  return _next++ as Id;
}

export function setIdCounter(value: number): void {
  _next = value;
}

export function INVALID_ID(): Id {
  return 0 as Id;
}
