// Axis-aligned bounding box.

import * as Vec3 from './Vec3';
import type { Vec3 as Vec3T } from './Vec3';
import type { Ray } from './Ray';

export interface Aabb {
  min: Vec3T;
  max: Vec3T;
}

export function create(): Aabb {
  return {
    min: Vec3.fromValues(Infinity, Infinity, Infinity),
    max: Vec3.fromValues(-Infinity, -Infinity, -Infinity),
  };
}

export function reset(out: Aabb): Aabb {
  out.min[0] = Infinity; out.min[1] = Infinity; out.min[2] = Infinity;
  out.max[0] = -Infinity; out.max[1] = -Infinity; out.max[2] = -Infinity;
  return out;
}

export function expandPoint(out: Aabb, p: Readonly<Vec3T>): Aabb {
  if (p[0] < out.min[0]) out.min[0] = p[0];
  if (p[1] < out.min[1]) out.min[1] = p[1];
  if (p[2] < out.min[2]) out.min[2] = p[2];
  if (p[0] > out.max[0]) out.max[0] = p[0];
  if (p[1] > out.max[1]) out.max[1] = p[1];
  if (p[2] > out.max[2]) out.max[2] = p[2];
  return out;
}

export function center(out: Vec3T, a: Aabb): Vec3T {
  out[0] = (a.min[0] + a.max[0]) * 0.5;
  out[1] = (a.min[1] + a.max[1]) * 0.5;
  out[2] = (a.min[2] + a.max[2]) * 0.5;
  return out;
}

export function size(out: Vec3T, a: Aabb): Vec3T {
  out[0] = a.max[0] - a.min[0];
  out[1] = a.max[1] - a.min[1];
  out[2] = a.max[2] - a.min[2];
  return out;
}

export function containsPoint(a: Aabb, p: Readonly<Vec3T>): boolean {
  return (
    p[0] >= a.min[0] && p[0] <= a.max[0] &&
    p[1] >= a.min[1] && p[1] <= a.max[1] &&
    p[2] >= a.min[2] && p[2] <= a.max[2]
  );
}

export function isValid(a: Aabb): boolean {
  return a.min[0] <= a.max[0] && a.min[1] <= a.max[1] && a.min[2] <= a.max[2];
}

/** Slab-based ray/AABB intersection. Returns the entry `t` or NaN. */
export function intersectRay(a: Aabb, ray: Ray): number {
  let tMin = -Infinity;
  let tMax = Infinity;
  for (let i = 0; i < 3; i++) {
    const d = ray.direction[i];
    const o = ray.origin[i];
    if (Math.abs(d) < 1e-9) {
      if (o < a.min[i] || o > a.max[i]) return NaN;
    } else {
      const inv = 1 / d;
      let t1 = (a.min[i] - o) * inv;
      let t2 = (a.max[i] - o) * inv;
      if (t1 > t2) [t1, t2] = [t2, t1];
      if (t1 > tMin) tMin = t1;
      if (t2 < tMax) tMax = t2;
      if (tMin > tMax) return NaN;
    }
  }
  return tMin >= 0 ? tMin : tMax >= 0 ? tMax : NaN;
}
