// Scale gizmo: three axis handles with end markers + center uniform handle.

import * as Vec3 from '../core/math/Vec3';
import { AXIS_VECTORS, getNodeOrigin, pointSegmentDistanceSq, projectToScreen, worldSizeForScreenPx, type Gizmo, type GizmoHit } from './Gizmo';
import type { Camera } from '../render/Camera';
import type { StripBatch } from '../render/StripRenderer';
import type { SceneNode } from '../scene/SceneNode';

const HANDLE_PX = 80;
const TIP_PX = 8;
const HIT_PX = 8;
const CENTER_PX = 14;

const AXIS_COLORS = {
  x: [0.95, 0.25, 0.25],
  y: [0.30, 0.85, 0.30],
  z: [0.30, 0.50, 0.95],
} as const;

export class ScaleGizmo implements Gizmo {
  render(strips: StripBatch, node: SceneNode, camera: Camera, _vpRect: { x: number; y: number; w: number; h: number }, aspect: number): void {
    const origin = Vec3.create();
    getNodeOrigin(origin, node);
    const distance = Vec3.distance(origin, camera.position());
    const size = worldSizeForScreenPx(HANDLE_PX, camera, distance, aspect, 2);
    const tip = worldSizeForScreenPx(TIP_PX, camera, distance, aspect, 2);
    for (const axis of ['x', 'y', 'z'] as const) {
      const dir = AXIS_VECTORS[axis];
      const col = AXIS_COLORS[axis];
      // Axis line.
      strips.add(
        origin[0], origin[1], origin[2],
        origin[0] + dir[0] * size, origin[1] + dir[1] * size, origin[2] + dir[2] * size,
        col[0], col[1], col[2],
      );
      // Tip cube as 3 short orthogonal segments at the end point.
      const ex = origin[0] + dir[0] * size, ey = origin[1] + dir[1] * size, ez = origin[2] + dir[2] * size;
      strips.add(ex - tip, ey, ez, ex + tip, ey, ez, col[0], col[1], col[2]);
      strips.add(ex, ey - tip, ez, ex, ey + tip, ez, col[0], col[1], col[2]);
      strips.add(ex, ey, ez - tip, ex, ey, ez + tip, col[0], col[1], col[2]);
    }
    // Center uniform handle: small octahedron-ish 3-axis cross.
    const c = worldSizeForScreenPx(CENTER_PX, camera, distance, aspect, 2) * 0.5;
    strips.add(origin[0] - c, origin[1], origin[2], origin[0] + c, origin[1], origin[2], 0.9, 0.9, 0.9);
    strips.add(origin[0], origin[1] - c, origin[2], origin[0], origin[1] + c, origin[2], 0.9, 0.9, 0.9);
    strips.add(origin[0], origin[1], origin[2] - c, origin[0], origin[1], origin[2] + c, 0.9, 0.9, 0.9);
  }

  hit(screenX: number, screenY: number, node: SceneNode, camera: Camera, vpRect: { x: number; y: number; w: number; h: number }, aspect: number): GizmoHit | null {
    const origin = Vec3.create();
    getNodeOrigin(origin, node);
    const distance = Vec3.distance(origin, camera.position());
    const size = worldSizeForScreenPx(HANDLE_PX, camera, distance, aspect, 2);
    const viewProj = camera.viewProj(aspect) as Float32Array;
    const o = projectToScreen(origin, viewProj, vpRect);
    if (!o) return null;
    let best: GizmoHit | null = null;
    let bestDist = HIT_PX * HIT_PX;
    // Center uniform handle: hit on a small disk around the origin.
    const dxC = screenX - o[0];
    const dyC = screenY - o[1];
    if (dxC * dxC + dyC * dyC < CENTER_PX * CENTER_PX) {
      best = { axis: 'all' };
      bestDist = dxC * dxC + dyC * dyC;
    }
    for (const axis of ['x', 'y', 'z'] as const) {
      const dir = AXIS_VECTORS[axis];
      const tip = Vec3.fromValues(origin[0] + dir[0] * size, origin[1] + dir[1] * size, origin[2] + dir[2] * size);
      const t = projectToScreen(tip, viewProj, vpRect);
      if (!t) continue;
      const d = pointSegmentDistanceSq(screenX, screenY, o[0], o[1], t[0], t[1]);
      if (d < bestDist) {
        bestDist = d;
        best = { axis };
      }
    }
    return best;
  }
}
