// Face-mode operations.

import { EditableMesh } from './EditableMesh';
import * as Vec3 from '../core/math/Vec3';
import * as Quat from '../core/math/Quat';
import type { Id } from '../core/Id';

function vertsOfFaces(mesh: EditableMesh, faceIds: Iterable<Id>): Set<Id> {
  const out = new Set<Id>();
  for (const fid of faceIds) {
    const f = mesh.faces.get(fid);
    if (!f) continue;
    for (const lid of f.loops) {
      const l = mesh.loops.get(lid);
      if (l) out.add(l.vertexId);
    }
  }
  return out;
}

function faceCentroid(mesh: EditableMesh, faceId: Id, out = Vec3.create()): Vec3.Vec3 {
  const f = mesh.faces.get(faceId);
  if (!f) {
    out[0] = 0; out[1] = 0; out[2] = 0;
    return out;
  }
  let cx = 0, cy = 0, cz = 0, n = 0;
  for (const lid of f.loops) {
    const l = mesh.loops.get(lid);
    if (!l) continue;
    const v = mesh.vertices.get(l.vertexId);
    if (!v) continue;
    cx += v.position[0]; cy += v.position[1]; cz += v.position[2];
    n++;
  }
  if (n > 0) { cx /= n; cy /= n; cz /= n; }
  out[0] = cx; out[1] = cy; out[2] = cz;
  return out;
}

export function translateFaces(mesh: EditableMesh, faceIds: Iterable<Id>, dx: number, dy: number, dz: number): void {
  for (const vid of vertsOfFaces(mesh, faceIds)) {
    const v = mesh.vertices.get(vid)!;
    v.position[0] += dx;
    v.position[1] += dy;
    v.position[2] += dz;
  }
}

export function rotateFaces(
  mesh: EditableMesh,
  faceIds: Iterable<Id>,
  axis: 'x' | 'y' | 'z',
  rad: number,
  pivot: Readonly<Vec3.Vec3> = Vec3.fromValues(0, 0, 0),
): void {
  const axisVec = axis === 'x' ? Vec3.UNIT_X : axis === 'y' ? Vec3.UNIT_Y : Vec3.UNIT_Z;
  const q = Quat.setAxisAngle(Quat.create(), axisVec, rad);
  const tmp = Vec3.create();
  const rel = Vec3.create();
  for (const vid of vertsOfFaces(mesh, faceIds)) {
    const v = mesh.vertices.get(vid)!;
    Vec3.sub(rel, v.position, pivot);
    Quat.transformVec3(tmp, rel, q);
    v.position[0] = tmp[0] + pivot[0];
    v.position[1] = tmp[1] + pivot[1];
    v.position[2] = tmp[2] + pivot[2];
  }
}

export function scaleFaces(
  mesh: EditableMesh,
  faceIds: Iterable<Id>,
  sx: number,
  sy: number,
  sz: number,
  pivot: Readonly<Vec3.Vec3> = Vec3.fromValues(0, 0, 0),
): void {
  for (const vid of vertsOfFaces(mesh, faceIds)) {
    const v = mesh.vertices.get(vid)!;
    v.position[0] = pivot[0] + (v.position[0] - pivot[0]) * sx;
    v.position[1] = pivot[1] + (v.position[1] - pivot[1]) * sy;
    v.position[2] = pivot[2] + (v.position[2] - pivot[2]) * sz;
  }
}

/**
 * Extrude faces: duplicate each face's verts and connect originals to
 * duplicates with bridge quads. Offset is applied to duplicates.
 * Returns the new face ids (the extruded "caps").
 */
export function extrudeFaces(
  mesh: EditableMesh,
  faceIds: Iterable<Id>,
  offset: Readonly<Vec3.Vec3> = Vec3.fromValues(0, 0.5, 0),
): Id[] {
  const ids = Array.from(faceIds).filter((id) => mesh.faces.has(id));
  if (ids.length === 0) return [];
  const newCaps: Id[] = [];
  // Snapshot each face's vert sequence + material before mutating.
  const plan: Array<{ seq: Id[]; mat: Id | null; faceId: Id }> = [];
  for (const fid of ids) {
    const f = mesh.faces.get(fid)!;
    const seq = f.loops.map((lid) => mesh.loops.get(lid)!.vertexId);
    plan.push({ seq, mat: f.materialId, faceId: fid });
  }
  // Duplicate verts (shared duplicates across selected faces).
  const dupMap = new Map<Id, Id>();
  const allVerts = new Set<Id>();
  for (const p of plan) for (const v of p.seq) allVerts.add(v);
  for (const vid of allVerts) {
    const v = mesh.vertices.get(vid)!;
    const nv = mesh.addVertex(
      v.position[0] + offset[0],
      v.position[1] + offset[1],
      v.position[2] + offset[2],
    );
    dupMap.set(vid, nv.id);
  }
  // Remove old faces (only the selected ones — non-selected neighbours stay).
  for (const p of plan) mesh.removeFace(p.faceId);
  // For each extruded face: build the new cap and side quads bridging old → new.
  for (const p of plan) {
    const n = p.seq.length;
    const newSeq = p.seq.map((v) => dupMap.get(v)!);
    try {
      const cap = mesh.addFace(newSeq, p.mat);
      newCaps.push(cap.id);
    } catch {
      // skip
    }
    // Side quads (only along edges that are NOT shared with another extruded
    // face — for shared edges, we'd just create internal faces).
    for (let i = 0; i < n; i++) {
      const a = p.seq[i];
      const b = p.seq[(i + 1) % n];
      // Check whether this edge appears in another plan face too.
      let shared = false;
      for (const p2 of plan) {
        if (p2 === p) continue;
        for (let j = 0; j < p2.seq.length; j++) {
          const c = p2.seq[j];
          const d = p2.seq[(j + 1) % p2.seq.length];
          if ((a === c && b === d) || (a === d && b === c)) {
            shared = true;
            break;
          }
        }
        if (shared) break;
      }
      if (shared) continue;
      try {
        mesh.addFace([a, b, dupMap.get(b)!, dupMap.get(a)!], p.mat);
      } catch {
        // Skip degenerate.
      }
    }
  }
  mesh.removeLooseGeometry();
  mesh.recomputeFaceNormals();
  return newCaps;
}

/**
 * Inset: shrink each face toward its centroid by `amount` and connect the
 * shrunk loop with quads to the original boundary. Returns the inner cap face ids.
 */
export function insetFaces(mesh: EditableMesh, faceIds: Iterable<Id>, amount = 0.1): Id[] {
  const ids = Array.from(faceIds).filter((id) => mesh.faces.has(id));
  const newCaps: Id[] = [];
  for (const fid of ids) {
    const f = mesh.faces.get(fid);
    if (!f) continue;
    const seq = f.loops.map((lid) => mesh.loops.get(lid)!.vertexId);
    const centroid = faceCentroid(mesh, fid);
    const innerVerts: Id[] = [];
    for (const vid of seq) {
      const v = mesh.vertices.get(vid)!;
      const dx = v.position[0] - centroid[0];
      const dy = v.position[1] - centroid[1];
      const dz = v.position[2] - centroid[2];
      const len = Math.hypot(dx, dy, dz);
      const t = len > 1e-6 ? amount / len : 0;
      const inner = mesh.addVertex(
        v.position[0] - dx * t,
        v.position[1] - dy * t,
        v.position[2] - dz * t,
      );
      innerVerts.push(inner.id);
    }
    const mat = f.materialId;
    mesh.removeFace(fid);
    // Inner cap.
    try {
      const cap = mesh.addFace(innerVerts, mat);
      newCaps.push(cap.id);
    } catch {
      // skip
    }
    // Side quads.
    const n = seq.length;
    for (let i = 0; i < n; i++) {
      const a = seq[i];
      const b = seq[(i + 1) % n];
      const bi = innerVerts[(i + 1) % n];
      const ai = innerVerts[i];
      try { mesh.addFace([a, b, bi, ai], mat); } catch { /* skip */ }
    }
  }
  mesh.recomputeFaceNormals();
  return newCaps;
}

/**
 * Poke: add a vertex at the face centroid and triangulate the face as a fan.
 * Returns the new center-vertex ids (one per face).
 */
export function pokeFaces(mesh: EditableMesh, faceIds: Iterable<Id>): Id[] {
  const ids = Array.from(faceIds).filter((id) => mesh.faces.has(id));
  const newVerts: Id[] = [];
  for (const fid of ids) {
    const f = mesh.faces.get(fid);
    if (!f) continue;
    const seq = f.loops.map((lid) => mesh.loops.get(lid)!.vertexId);
    const centroid = faceCentroid(mesh, fid);
    const center = mesh.addVertex(centroid[0], centroid[1], centroid[2]);
    newVerts.push(center.id);
    const mat = f.materialId;
    mesh.removeFace(fid);
    const n = seq.length;
    for (let i = 0; i < n; i++) {
      const a = seq[i];
      const b = seq[(i + 1) % n];
      try { mesh.addFace([a, b, center.id], mat); } catch { /* skip */ }
    }
  }
  mesh.recomputeFaceNormals();
  return newVerts;
}

/**
 * Triangulate: replace each n-gon face (n > 3) with a fan of triangles
 * around vertex 0. Returns the new triangle face ids.
 */
export function triangulateFaces(mesh: EditableMesh, faceIds: Iterable<Id>): Id[] {
  const ids = Array.from(faceIds).filter((id) => mesh.faces.has(id));
  const out: Id[] = [];
  for (const fid of ids) {
    const f = mesh.faces.get(fid);
    if (!f) continue;
    if (f.loops.length <= 3) {
      out.push(fid);
      continue;
    }
    const seq = f.loops.map((lid) => mesh.loops.get(lid)!.vertexId);
    const mat = f.materialId;
    mesh.removeFace(fid);
    for (let i = 1; i < seq.length - 1; i++) {
      try {
        const tri = mesh.addFace([seq[0], seq[i], seq[i + 1]], mat);
        out.push(tri.id);
      } catch {
        // skip
      }
    }
  }
  mesh.recomputeFaceNormals();
  return out;
}

/** Delete the listed faces. Loose verts are not pruned (kept as floating). */
export function deleteFaces(mesh: EditableMesh, faceIds: Iterable<Id>): void {
  for (const fid of faceIds) {
    mesh.removeFace(fid);
  }
  mesh.removeLooseGeometry();
}

/**
 * Separate: remove the listed faces from `source` and rebuild them as a
 * fresh, standalone `EditableMesh`. Returns the new mesh.
 */
export function separateFaces(source: EditableMesh, faceIds: Iterable<Id>): EditableMesh {
  const out = new EditableMesh();
  const ids = Array.from(faceIds).filter((id) => source.faces.has(id));
  const vertMap = new Map<Id, Id>();
  for (const fid of ids) {
    const face = source.faces.get(fid)!;
    const seq = face.loops.map((lid) => source.loops.get(lid)!.vertexId);
    const newSeq: Id[] = [];
    for (const vid of seq) {
      let nid = vertMap.get(vid);
      if (nid == null) {
        const v = source.vertices.get(vid)!;
        const nv = out.addVertex(v.position[0], v.position[1], v.position[2]);
        nid = nv.id;
        vertMap.set(vid, nid);
      }
      newSeq.push(nid);
    }
    try { out.addFace(newSeq, face.materialId); } catch { /* skip */ }
  }
  // Remove separated faces from source.
  for (const fid of ids) source.removeFace(fid);
  source.removeLooseGeometry();
  source.recomputeFaceNormals();
  out.recomputeFaceNormals();
  return out;
}
