// glTF 2.0 export.
//
// Produces a single-buffer glTF JSON document with embedded base64 buffer
// (data: URI) and an optional GLB binary container. Exports every
// MeshObject as a separate glTF mesh with one primitive per material id
// (we currently always group as one primitive — single material per mesh).
//
// We export triangulated geometry (the renderer's RenderMesh would be ideal
// but doing fan-triangulation here is simpler and avoids needing a GL context).
//
// Texture export embeds the RGBA pixel data as a PNG inside the binary
// buffer. PNG encoding is implemented from scratch to avoid a dependency.

import { Scene, MeshObject } from '../scene/Scene';
import type { Material } from '../scene/Material';
import type { Id } from '../core/Id';

interface GltfBufferView {
  buffer: 0;
  byteOffset: number;
  byteLength: number;
  target?: 34962 | 34963;
}

interface GltfAccessor {
  bufferView: number;
  componentType: number;
  count: number;
  type: 'SCALAR' | 'VEC2' | 'VEC3' | 'VEC4';
  min?: number[];
  max?: number[];
}

interface GltfImage {
  bufferView: number;
  mimeType: 'image/png';
}

interface GltfMaterial {
  name: string;
  pbrMetallicRoughness: {
    baseColorFactor: [number, number, number, number];
    baseColorTexture?: { index: number };
    metallicFactor: number;
    roughnessFactor: number;
  };
  alphaMode?: 'OPAQUE' | 'MASK' | 'BLEND';
}

interface GltfPrimitive {
  attributes: { POSITION: number; NORMAL?: number; TEXCOORD_0?: number };
  indices: number;
  material?: number;
  mode: 4; // triangles
}

interface GltfMesh { name: string; primitives: GltfPrimitive[] }
interface GltfNode { name: string; mesh?: number; translation?: [number, number, number]; rotation?: [number, number, number, number]; scale?: [number, number, number]; children?: number[] }
interface GltfScene { nodes: number[] }
interface GltfDocument {
  asset: { version: '2.0'; generator: 'BrutalMesh' };
  scene: 0;
  scenes: GltfScene[];
  nodes: GltfNode[];
  meshes: GltfMesh[];
  materials?: GltfMaterial[];
  textures?: Array<{ source: number }>;
  images?: GltfImage[];
  buffers: Array<{ uri?: string; byteLength: number }>;
  bufferViews: GltfBufferView[];
  accessors: GltfAccessor[];
}

export interface GltfExportResult {
  json: string;
  glb: ArrayBuffer;
  /** Best-effort document for tests. */
  document: GltfDocument;
}

/** Triangulate a face (fan around vertex 0). Returns triangle index triples. */
function triangulateFaceIdx(loopVerts: number[]): number[] {
  const tris: number[] = [];
  for (let i = 1; i < loopVerts.length - 1; i++) {
    tris.push(loopVerts[0], loopVerts[i], loopVerts[i + 1]);
  }
  return tris;
}

function alignUp(n: number, align: number): number {
  return n + ((align - (n % align)) % align);
}

/** Trivial uncompressed PNG encoder (8-bit RGBA). */
function encodePngRgba(width: number, height: number, data: Uint8Array): Uint8Array {
  // Build IDAT data: per-row filter byte = 0, followed by RGBA bytes.
  const rowBytes = width * 4;
  const rawSize = (rowBytes + 1) * height;
  const raw = new Uint8Array(rawSize);
  for (let y = 0; y < height; y++) {
    raw[y * (rowBytes + 1)] = 0;
    raw.set(data.subarray(y * rowBytes, (y + 1) * rowBytes), y * (rowBytes + 1) + 1);
  }
  // zlib-wrap with stored (no compression) blocks.
  const zlib = zlibStore(raw);
  const ihdr = new Uint8Array(13);
  const dv = new DataView(ihdr.buffer);
  dv.setUint32(0, width, false);
  dv.setUint32(4, height, false);
  ihdr[8] = 8;       // bit depth
  ihdr[9] = 6;       // colour type = RGBA
  ihdr[10] = 0;      // compression
  ihdr[11] = 0;      // filter
  ihdr[12] = 0;      // interlace
  const chunks = [
    pngChunk('IHDR', ihdr),
    pngChunk('IDAT', zlib),
    pngChunk('IEND', new Uint8Array(0)),
  ];
  const sig = new Uint8Array([137, 80, 78, 71, 13, 10, 26, 10]);
  let total = sig.length;
  for (const c of chunks) total += c.length;
  const out = new Uint8Array(total);
  let off = 0;
  out.set(sig, off); off += sig.length;
  for (const c of chunks) { out.set(c, off); off += c.length; }
  return out;
}

function pngChunk(type: string, data: Uint8Array): Uint8Array {
  const out = new Uint8Array(12 + data.length);
  const dv = new DataView(out.buffer);
  dv.setUint32(0, data.length, false);
  out[4] = type.charCodeAt(0);
  out[5] = type.charCodeAt(1);
  out[6] = type.charCodeAt(2);
  out[7] = type.charCodeAt(3);
  out.set(data, 8);
  // CRC over (type + data).
  const crcSrc = new Uint8Array(4 + data.length);
  crcSrc.set(out.subarray(4, 8), 0);
  crcSrc.set(data, 4);
  const crc = crc32(crcSrc);
  dv.setUint32(8 + data.length, crc, false);
  return out;
}

function zlibStore(data: Uint8Array): Uint8Array {
  // Header: CMF=0x78, FLG=0x01 (no preset dict, fastest, valid checksum).
  const blocks: number[][] = [];
  let pos = 0;
  while (pos < data.length) {
    const len = Math.min(0xffff, data.length - pos);
    const last = pos + len >= data.length ? 1 : 0;
    blocks.push([last, len & 0xff, (len >> 8) & 0xff, (~len) & 0xff, ((~len) >> 8) & 0xff]);
    pos += len;
  }
  let bodyLen = 0;
  for (const b of blocks) bodyLen += b.length;
  bodyLen += data.length;
  const out = new Uint8Array(2 + bodyLen + 4);
  out[0] = 0x78; out[1] = 0x01;
  let off = 2;
  pos = 0;
  for (const b of blocks) {
    out.set(b, off); off += b.length;
    const len = b[1] | (b[2] << 8);
    out.set(data.subarray(pos, pos + len), off);
    off += len;
    pos += len;
  }
  // Adler-32.
  let a = 1, b2 = 0;
  for (let i = 0; i < data.length; i++) {
    a = (a + data[i]) % 65521;
    b2 = (b2 + a) % 65521;
  }
  const adler = (b2 << 16) | a;
  const dv = new DataView(out.buffer);
  dv.setUint32(out.length - 4, adler >>> 0, false);
  return out;
}

let CRC_TABLE: Uint32Array | null = null;
function crc32(data: Uint8Array): number {
  if (!CRC_TABLE) {
    CRC_TABLE = new Uint32Array(256);
    for (let i = 0; i < 256; i++) {
      let c = i;
      for (let j = 0; j < 8; j++) c = (c & 1) ? (0xedb88320 ^ (c >>> 1)) : (c >>> 1);
      CRC_TABLE[i] = c >>> 0;
    }
  }
  let crc = 0xffffffff;
  for (let i = 0; i < data.length; i++) crc = CRC_TABLE[(crc ^ data[i]) & 0xff] ^ (crc >>> 8);
  return (crc ^ 0xffffffff) >>> 0;
}

/** Encode binary data as base64 (browser-safe). */
function base64Encode(data: Uint8Array): string {
  let s = '';
  for (let i = 0; i < data.length; i++) s += String.fromCharCode(data[i]);
  if (typeof btoa === 'function') return btoa(s);
  // Fallback for Node.
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const B: any = (globalThis as any).Buffer;
  if (B) return B.from(data).toString('base64');
  throw new Error('No base64 encoder available');
}

export function exportGltf(scene: Scene): GltfExportResult {
  const doc: GltfDocument = {
    asset: { version: '2.0', generator: 'BrutalMesh' },
    scene: 0,
    scenes: [{ nodes: [] }],
    nodes: [],
    meshes: [],
    buffers: [{ byteLength: 0 }],
    bufferViews: [],
    accessors: [],
  };
  const matBytes = new Map<Id, number>(); // material id → glTF index
  const textureBytes = new Map<Id, number>(); // material id → texture index
  doc.materials = [];
  doc.textures = [];
  doc.images = [];

  const buffers: Uint8Array[] = [];
  let cursor = 0;

  const pushBufferView = (data: Uint8Array, target?: 34962 | 34963): number => {
    // Align to 4 bytes.
    while (cursor % 4 !== 0) { buffers.push(new Uint8Array([0])); cursor++; }
    const bv: GltfBufferView = { buffer: 0, byteOffset: cursor, byteLength: data.byteLength };
    if (target) bv.target = target;
    doc.bufferViews.push(bv);
    buffers.push(data);
    cursor += data.byteLength;
    return doc.bufferViews.length - 1;
  };

  const pushAccessor = (a: Omit<GltfAccessor, 'bufferView'> & { bufferView: number }): number => {
    doc.accessors.push(a);
    return doc.accessors.length - 1;
  };

  // Materials.
  const mats = scene.materials() as Material[];
  for (const mat of mats) {
    const m: GltfMaterial = {
      name: mat.name,
      pbrMetallicRoughness: {
        baseColorFactor: [mat.baseColor.r, mat.baseColor.g, mat.baseColor.b, mat.opacity],
        metallicFactor: 0,
        roughnessFactor: 0.6,
      },
      alphaMode: mat.opacity < 1.0 ? 'BLEND' : 'OPAQUE',
    };
    if (mat.texture && mat.texture.data) {
      const png = encodePngRgba(mat.texture.width, mat.texture.height, mat.texture.data);
      const imgBv = pushBufferView(png);
      doc.images!.push({ bufferView: imgBv, mimeType: 'image/png' });
      const imageIdx = doc.images!.length - 1;
      doc.textures!.push({ source: imageIdx });
      const texIdx = doc.textures!.length - 1;
      m.pbrMetallicRoughness.baseColorTexture = { index: texIdx };
      textureBytes.set(mat.id, texIdx);
    }
    doc.materials!.push(m);
    matBytes.set(mat.id, doc.materials!.length - 1);
  }
  if (doc.materials!.length === 0) delete doc.materials;
  if (doc.textures!.length === 0) delete doc.textures;
  if (doc.images!.length === 0) delete doc.images;

  // Walk the scene and emit nodes / meshes.
  scene.forEachNode((n) => {
    if (n.kind !== 'mesh') return;
    const node = n as MeshObject;
    if (!node.mesh) return;
    const mesh = node.mesh;
    // Build interleaved-less buffers: pos (vec3), normal (vec3), uv (vec2), idx (uint32).
    const positions: number[] = [];
    const normals: number[] = [];
    const uvs: number[] = [];
    const indices: number[] = [];
    // For each face, fan triangulate. Each vertex in a face triangle has its own loop's
    // normal/UV, so we need to emit a unique vertex per loop (not per shared mesh vertex).
    let nextVid = 0;
    for (const face of mesh.faces.values()) {
      const loopVerts: number[] = [];
      for (const lid of face.loops) {
        const loop = mesh.loops.get(lid);
        if (!loop) continue;
        const v = mesh.vertices.get(loop.vertexId);
        if (!v) continue;
        positions.push(v.position[0], v.position[1], v.position[2]);
        const norm = (loop.normal[0] !== 0 || loop.normal[1] !== 0 || loop.normal[2] !== 0) ? loop.normal : face.normal;
        normals.push(norm[0], norm[1], norm[2]);
        uvs.push(loop.uv[0], loop.uv[1]);
        loopVerts.push(nextVid++);
      }
      const tris = triangulateFaceIdx(loopVerts);
      for (const t of tris) indices.push(t);
    }
    // Convert to typed arrays.
    const positionArr = new Float32Array(positions);
    const normalArr = new Float32Array(normals);
    const uvArr = new Float32Array(uvs);
    const indexArr = new Uint32Array(indices);
    // Compute min/max for POSITION accessor.
    let minX = Infinity, minY = Infinity, minZ = Infinity;
    let maxX = -Infinity, maxY = -Infinity, maxZ = -Infinity;
    for (let i = 0; i < positionArr.length; i += 3) {
      const x = positionArr[i], y = positionArr[i + 1], z = positionArr[i + 2];
      if (x < minX) minX = x; if (y < minY) minY = y; if (z < minZ) minZ = z;
      if (x > maxX) maxX = x; if (y > maxY) maxY = y; if (z > maxZ) maxZ = z;
    }
    const posBv = pushBufferView(new Uint8Array(positionArr.buffer, positionArr.byteOffset, positionArr.byteLength), 34962);
    const normalBv = pushBufferView(new Uint8Array(normalArr.buffer, normalArr.byteOffset, normalArr.byteLength), 34962);
    const uvBv = pushBufferView(new Uint8Array(uvArr.buffer, uvArr.byteOffset, uvArr.byteLength), 34962);
    const idxBv = pushBufferView(new Uint8Array(indexArr.buffer, indexArr.byteOffset, indexArr.byteLength), 34963);
    const vertexCount = positionArr.length / 3;
    const posAcc = pushAccessor({ bufferView: posBv, componentType: 5126, count: vertexCount, type: 'VEC3', min: [minX, minY, minZ], max: [maxX, maxY, maxZ] });
    const normalAcc = pushAccessor({ bufferView: normalBv, componentType: 5126, count: vertexCount, type: 'VEC3' });
    const uvAcc = pushAccessor({ bufferView: uvBv, componentType: 5126, count: vertexCount, type: 'VEC2' });
    const idxAcc = pushAccessor({ bufferView: idxBv, componentType: 5125, count: indexArr.length, type: 'SCALAR' });
    const matIdx = node.materialId != null ? matBytes.get(node.materialId) : undefined;
    const prim: GltfPrimitive = {
      attributes: { POSITION: posAcc, NORMAL: normalAcc, TEXCOORD_0: uvAcc },
      indices: idxAcc,
      mode: 4,
    };
    if (matIdx != null) prim.material = matIdx;
    doc.meshes.push({ name: node.name, primitives: [prim] });
    const gltfNode: GltfNode = {
      name: node.name,
      mesh: doc.meshes.length - 1,
      translation: [node.transform.position[0], node.transform.position[1], node.transform.position[2]],
      rotation: [node.transform.rotation[0], node.transform.rotation[1], node.transform.rotation[2], node.transform.rotation[3]],
      scale: [node.transform.scale[0], node.transform.scale[1], node.transform.scale[2]],
    };
    doc.nodes.push(gltfNode);
    doc.scenes[0].nodes.push(doc.nodes.length - 1);
  });

  // Build combined buffer.
  const totalLen = cursor;
  const combined = new Uint8Array(totalLen);
  let off = 0;
  for (const b of buffers) {
    combined.set(b, off);
    off += b.length;
  }
  doc.buffers[0].byteLength = totalLen;
  doc.buffers[0].uri = 'data:application/octet-stream;base64,' + base64Encode(combined);

  // Build GLB binary: header + JSON chunk + BIN chunk.
  // JSON chunk needs to be padded with spaces; BIN chunk padded with 0.
  // JSON references buffer 0 via embedded uri above — for GLB we drop that and let the BIN chunk be buffer 0.
  const glbDoc: GltfDocument = JSON.parse(JSON.stringify(doc));
  delete glbDoc.buffers[0].uri;
  const jsonStr = JSON.stringify(glbDoc);
  const jsonBytes = new TextEncoder().encode(jsonStr);
  const jsonLen = alignUp(jsonBytes.length, 4);
  const binLen = alignUp(totalLen, 4);
  const glb = new ArrayBuffer(12 + 8 + jsonLen + 8 + binLen);
  const dv = new DataView(glb);
  dv.setUint32(0, 0x46546c67, true); // "glTF"
  dv.setUint32(4, 2, true); // version
  dv.setUint32(8, glb.byteLength, true); // total length
  dv.setUint32(12, jsonLen, true);
  dv.setUint32(16, 0x4e4f534a, true); // "JSON"
  new Uint8Array(glb, 20, jsonBytes.length).set(jsonBytes);
  // pad with spaces
  for (let i = jsonBytes.length; i < jsonLen; i++) new Uint8Array(glb, 20 + i, 1)[0] = 0x20;
  dv.setUint32(20 + jsonLen, binLen, true);
  dv.setUint32(20 + jsonLen + 4, 0x004e4942, true); // "BIN\0"
  new Uint8Array(glb, 20 + jsonLen + 8, totalLen).set(combined);
  return {
    json: JSON.stringify(doc, null, 2),
    glb,
    document: doc,
  };
}
