// Edge-mode operations.

import { EditableMesh } from './EditableMesh';
import * as Vec3 from '../core/math/Vec3';
import * as Quat from '../core/math/Quat';
import type { Id } from '../core/Id';

function vertsOfEdges(mesh: EditableMesh, edgeIds: Iterable<Id>): Set<Id> {
  const out = new Set<Id>();
  for (const eid of edgeIds) {
    const e = mesh.edges.get(eid);
    if (!e) continue;
    out.add(e.a);
    out.add(e.b);
  }
  return out;
}

export function translateEdges(mesh: EditableMesh, edgeIds: Iterable<Id>, dx: number, dy: number, dz: number): void {
  for (const vid of vertsOfEdges(mesh, edgeIds)) {
    const v = mesh.vertices.get(vid)!;
    v.position[0] += dx;
    v.position[1] += dy;
    v.position[2] += dz;
  }
}

export function rotateEdges(
  mesh: EditableMesh,
  edgeIds: Iterable<Id>,
  axis: 'x' | 'y' | 'z',
  rad: number,
  pivot: Readonly<Vec3.Vec3> = Vec3.fromValues(0, 0, 0),
): void {
  const axisVec = axis === 'x' ? Vec3.UNIT_X : axis === 'y' ? Vec3.UNIT_Y : Vec3.UNIT_Z;
  const q = Quat.setAxisAngle(Quat.create(), axisVec, rad);
  const tmp = Vec3.create();
  const rel = Vec3.create();
  for (const vid of vertsOfEdges(mesh, edgeIds)) {
    const v = mesh.vertices.get(vid)!;
    Vec3.sub(rel, v.position, pivot);
    Quat.transformVec3(tmp, rel, q);
    v.position[0] = tmp[0] + pivot[0];
    v.position[1] = tmp[1] + pivot[1];
    v.position[2] = tmp[2] + pivot[2];
  }
}

export function scaleEdges(
  mesh: EditableMesh,
  edgeIds: Iterable<Id>,
  sx: number,
  sy: number,
  sz: number,
  pivot: Readonly<Vec3.Vec3> = Vec3.fromValues(0, 0, 0),
): void {
  for (const vid of vertsOfEdges(mesh, edgeIds)) {
    const v = mesh.vertices.get(vid)!;
    v.position[0] = pivot[0] + (v.position[0] - pivot[0]) * sx;
    v.position[1] = pivot[1] + (v.position[1] - pivot[1]) * sy;
    v.position[2] = pivot[2] + (v.position[2] - pivot[2]) * sz;
  }
}

/**
 * Extrude edges: duplicate the endpoint verts and bridge the originals
 * to the duplicates with a strip of quads. Optionally offset the new
 * verts along the average face normal of the incident faces.
 */
export function extrudeEdges(
  mesh: EditableMesh,
  edgeIds: Iterable<Id>,
  offset: Readonly<Vec3.Vec3> = Vec3.fromValues(0, 0, 0.5),
): Id[] {
  const ids = Array.from(edgeIds).filter((id) => mesh.edges.has(id));
  if (ids.length === 0) return [];
  // Duplicate endpoint verts.
  const seen = new Set<Id>();
  const dupMap = new Map<Id, Id>();
  for (const eid of ids) {
    const e = mesh.edges.get(eid);
    if (!e) continue;
    for (const vid of [e.a, e.b]) {
      if (seen.has(vid)) continue;
      seen.add(vid);
      const v = mesh.vertices.get(vid)!;
      const nv = mesh.addVertex(
        v.position[0] + offset[0],
        v.position[1] + offset[1],
        v.position[2] + offset[2],
      );
      dupMap.set(vid, nv.id);
    }
  }
  // Build bridge quad per original edge.
  const newEdges: Id[] = [];
  for (const eid of ids) {
    const e = mesh.edges.get(eid);
    if (!e) continue;
    const aNew = dupMap.get(e.a)!;
    const bNew = dupMap.get(e.b)!;
    try {
      mesh.addFace([e.a, e.b, bNew, aNew]);
      const newEdge = mesh.findOrCreateEdge(aNew, bNew);
      newEdges.push(newEdge.id);
    } catch {
      // Skip degenerate.
    }
  }
  mesh.recomputeFaceNormals();
  return newEdges;
}

/**
 * Bevel an edge by inserting two parallel edges offset along the
 * adjacent face normals. Coarse first-pass: per edge, push the endpoints
 * slightly out along the average face normal and split the incident faces.
 */
export function bevelEdge(mesh: EditableMesh, edgeId: Id, offset = 0.1): void {
  const e = mesh.edges.get(edgeId);
  if (!e) return;
  const va = mesh.vertices.get(e.a);
  const vb = mesh.vertices.get(e.b);
  if (!va || !vb) return;
  // Compute average face normal at edge.
  const navg = Vec3.create();
  let count = 0;
  for (const lid of e.loops) {
    const loop = mesh.loops.get(lid);
    if (!loop) continue;
    const f = mesh.faces.get(loop.faceId);
    if (!f) continue;
    Vec3.add(navg, navg, f.normal);
    count++;
  }
  if (count > 0) Vec3.scale(navg, navg, 1 / count);
  Vec3.normalize(navg, navg);
  // Edge direction.
  const dir = Vec3.sub(Vec3.create(), vb.position, va.position);
  Vec3.normalize(dir, dir);
  // Perpendicular = navg × dir.
  const perp = Vec3.cross(Vec3.create(), navg, dir);
  Vec3.normalize(perp, perp);
  // Two new pairs of verts on either side of the edge along perp.
  const a1 = mesh.addVertex(va.position[0] + perp[0] * offset, va.position[1] + perp[1] * offset, va.position[2] + perp[2] * offset);
  const a2 = mesh.addVertex(va.position[0] - perp[0] * offset, va.position[1] - perp[1] * offset, va.position[2] - perp[2] * offset);
  const b1 = mesh.addVertex(vb.position[0] + perp[0] * offset, vb.position[1] + perp[1] * offset, vb.position[2] + perp[2] * offset);
  const b2 = mesh.addVertex(vb.position[0] - perp[0] * offset, vb.position[1] - perp[1] * offset, vb.position[2] - perp[2] * offset);
  // Adjacent faces — rebuild each by replacing e.a / e.b with the appropriate side.
  const faces = [...e.loops].map((lid) => mesh.loops.get(lid)?.faceId).filter((id): id is Id => id != null);
  const rebuilds: Array<{ verts: Id[]; mat: Id | null }> = [];
  let sideIdx = 0;
  for (const fid of faces) {
    const face = mesh.faces.get(fid);
    if (!face) continue;
    const seq = face.loops.map((lid) => mesh.loops.get(lid)!.vertexId);
    const newSeq: Id[] = [];
    for (let i = 0; i < seq.length; i++) {
      const cur = seq[i];
      if (cur === e.a) newSeq.push(sideIdx === 0 ? a1.id : a2.id);
      else if (cur === e.b) newSeq.push(sideIdx === 0 ? b1.id : b2.id);
      else newSeq.push(cur);
    }
    rebuilds.push({ verts: newSeq, mat: face.materialId });
    sideIdx++;
  }
  // Connecting bevel quad between the two split sides.
  for (const fid of faces) mesh.removeFace(fid);
  // Old verts e.a, e.b now unused; delete them.
  // (Edges and verts will be cleaned by removeLooseGeometry after face rebuild.)
  for (const r of rebuilds) {
    try { mesh.addFace(r.verts, r.mat); } catch { /* skip */ }
  }
  // Bevel quad connecting a1↔a2↔b2↔b1 (only if both sides existed).
  try { mesh.addFace([a1.id, a2.id, b2.id, b1.id]); } catch { /* skip */ }
  // Drop the original endpoint verts if they're now loose.
  mesh.removeLooseGeometry();
  mesh.recomputeFaceNormals();
}

/**
 * Loop cut: walk a quad strip from `edgeId` and insert a vertex at the
 * midpoint of every parallel edge in the strip, joining them with new
 * edges so the loop becomes a cut through every face it crosses.
 */
export function loopCut(mesh: EditableMesh, edgeId: Id): Id[] {
  const seedEdge = mesh.edges.get(edgeId);
  if (!seedEdge) return [];

  const visitedEdges = new Set<Id>([seedEdge.id]);
  const stripEdges: Id[] = [seedEdge.id];

  // Walk in both directions across quad neighbours.
  const walk = (startEdge: Id, startFace: Id | null) => {
    let curEdge = startEdge;
    let curFace = startFace;
    while (true) {
      const e = mesh.edges.get(curEdge);
      if (!e) break;
      // Find the loop on curFace that traverses curEdge.
      let nextEdge: Id | null = null;
      let nextFace: Id | null = null;
      for (const lid of e.loops) {
        const loop = mesh.loops.get(lid);
        if (!loop) continue;
        if (curFace != null && loop.faceId !== curFace) continue;
        // Opposite edge in a quad: skip one loop on each side.
        const face = mesh.faces.get(loop.faceId);
        if (!face || face.loops.length !== 4) continue;
        const idx = face.loops.indexOf(lid);
        const oppLoopId = face.loops[(idx + 2) % 4];
        const oppLoop = mesh.loops.get(oppLoopId);
        if (!oppLoop) continue;
        nextEdge = oppLoop.edgeId;
        // Find the other face on nextEdge (continue walking through it).
        const ne = mesh.edges.get(nextEdge);
        if (ne) {
          for (const olid of ne.loops) {
            const ol = mesh.loops.get(olid);
            if (ol && ol.faceId !== loop.faceId) {
              nextFace = ol.faceId;
              break;
            }
          }
        }
        break;
      }
      if (nextEdge == null || visitedEdges.has(nextEdge)) break;
      visitedEdges.add(nextEdge);
      stripEdges.push(nextEdge);
      if (nextFace == null) break;
      curEdge = nextEdge;
      curFace = nextFace;
    }
  };

  // Walk both faces touching the seed edge (so we get the full loop).
  const seedFaces: Id[] = [];
  for (const lid of seedEdge.loops) {
    const loop = mesh.loops.get(lid);
    if (loop) seedFaces.push(loop.faceId);
  }
  for (const fid of seedFaces) walk(seedEdge.id, fid);

  // Now: for each edge in stripEdges, insert a midpoint vertex.
  const midByEdge = new Map<Id, Id>();
  for (const eid of stripEdges) {
    const e = mesh.edges.get(eid);
    if (!e) continue;
    const va = mesh.vertices.get(e.a)!;
    const vb = mesh.vertices.get(e.b)!;
    const mid = mesh.addVertex(
      (va.position[0] + vb.position[0]) * 0.5,
      (va.position[1] + vb.position[1]) * 0.5,
      (va.position[2] + vb.position[2]) * 0.5,
    );
    midByEdge.set(eid, mid.id);
  }
  // Rebuild each face touching strip edges, splitting it across the cut.
  const facesToRebuild = new Set<Id>();
  for (const eid of stripEdges) {
    const e = mesh.edges.get(eid);
    if (!e) continue;
    for (const lid of e.loops) {
      const loop = mesh.loops.get(lid);
      if (loop) facesToRebuild.add(loop.faceId);
    }
  }
  const rebuildPlans: Array<{ a: Id[]; b: Id[]; mat: Id | null }> = [];
  for (const fid of facesToRebuild) {
    const face = mesh.faces.get(fid);
    if (!face) continue;
    if (face.loops.length !== 4) continue; // Only handle quads.
    const seq = face.loops.map((lid) => mesh.loops.get(lid)!.vertexId);
    const edgeIds = face.loops.map((lid) => mesh.loops.get(lid)!.edgeId);
    // Find the two strip edges in this face.
    const stripIdx: number[] = [];
    for (let i = 0; i < 4; i++) {
      if (stripEdges.includes(edgeIds[i])) stripIdx.push(i);
    }
    if (stripIdx.length !== 2) continue;
    const [i0, i1] = stripIdx;
    const m0 = midByEdge.get(edgeIds[i0])!;
    const m1 = midByEdge.get(edgeIds[i1])!;
    // Two new faces: (seq[i0] → m0 → m1 → seq[i1]+1 in sequence …) — careful with winding.
    // Split into [seq[i0], m0, m1, seq[(i1+1)%4]] and [m0, seq[(i0+1)%4], seq[i1], m1]
    // depending on how the strip indices wrap. Pattern is easier for non-adjacent indices (0 & 2).
    if ((i1 - i0 + 4) % 4 !== 2) continue; // Should be opposite sides for a strip-cut quad.
    rebuildPlans.push({
      a: [seq[i0], m0, m1, seq[(i1 + 1) % 4]],
      b: [m0, seq[(i0 + 1) % 4], seq[i1], m1],
      mat: face.materialId,
    });
  }
  for (const fid of facesToRebuild) mesh.removeFace(fid);
  for (const r of rebuildPlans) {
    try { mesh.addFace(r.a, r.mat); } catch { /* skip */ }
    try { mesh.addFace(r.b, r.mat); } catch { /* skip */ }
  }
  mesh.recomputeFaceNormals();
  return Array.from(midByEdge.values());
}

/** Merge a pair of edges by collapsing both endpoints. */
export function mergeEdges(mesh: EditableMesh, edgeIds: Iterable<Id>): void {
  const verts = Array.from(vertsOfEdges(mesh, edgeIds));
  if (verts.length < 2) return;
  // Use mergeVerts logic in place: pick survivor, move others onto it.
  // Move all verts to centroid.
  let cx = 0, cy = 0, cz = 0;
  for (const vid of verts) {
    const v = mesh.vertices.get(vid)!;
    cx += v.position[0]; cy += v.position[1]; cz += v.position[2];
  }
  cx /= verts.length; cy /= verts.length; cz /= verts.length;
  const survivor = verts[0];
  const sv = mesh.vertices.get(survivor)!;
  sv.position[0] = cx; sv.position[1] = cy; sv.position[2] = cz;
  // Rewire faces.
  const vertSet = new Set(verts);
  const affectedFaces = new Set<Id>();
  for (const vid of verts) {
    for (const fid of mesh.vertexFaces(vid)) affectedFaces.add(fid);
  }
  const replans: Array<{ id: Id; verts: Id[]; mat: Id | null }> = [];
  for (const fid of affectedFaces) {
    const face = mesh.faces.get(fid);
    if (!face) continue;
    const seq = face.loops.map((lid) => mesh.loops.get(lid)!.vertexId).map((v) => (vertSet.has(v) ? survivor : v));
    replans.push({ id: fid, verts: seq, mat: face.materialId });
  }
  for (const r of replans) mesh.removeFace(r.id);
  for (const vid of verts) {
    if (vid === survivor) continue;
    const v = mesh.vertices.get(vid);
    if (!v) continue;
    for (const eid of [...v.edges]) {
      const e = mesh.edges.get(eid);
      if (e && e.loops.length === 0) {
        mesh.edges.delete(eid);
        const other = e.a === vid ? e.b : e.a;
        const ov = mesh.vertices.get(other);
        if (ov) {
          const i = ov.edges.indexOf(eid);
          if (i >= 0) ov.edges.splice(i, 1);
        }
      }
    }
    mesh.vertices.delete(vid);
  }
  for (const r of replans) {
    const dedup: Id[] = [];
    for (let i = 0; i < r.verts.length; i++) {
      if (r.verts[i] !== dedup[dedup.length - 1]) dedup.push(r.verts[i]);
    }
    if (dedup.length > 1 && dedup[0] === dedup[dedup.length - 1]) dedup.pop();
    if (dedup.length < 3) continue;
    try { mesh.addFace(dedup, r.mat); } catch { /* skip */ }
  }
  mesh.removeLooseGeometry();
  mesh.recomputeFaceNormals();
}

/** Weld edge `from` onto `to` (collapse the two as edges). */
export function weldEdges(mesh: EditableMesh, fromId: Id, toId: Id): void {
  mergeEdges(mesh, [fromId, toId]);
}

/**
 * Bridge two open edges by adding a quad spanning their endpoints.
 * Returns the new face's id, or null if it couldn't be built.
 */
export function bridgeEdges(mesh: EditableMesh, e1Id: Id, e2Id: Id): Id | null {
  const e1 = mesh.edges.get(e1Id);
  const e2 = mesh.edges.get(e2Id);
  if (!e1 || !e2) return null;
  // Order endpoints for a non-crossing quad.
  const va = mesh.vertices.get(e1.a)!;
  const vb = mesh.vertices.get(e1.b)!;
  const vc = mesh.vertices.get(e2.a)!;
  const vd = mesh.vertices.get(e2.b)!;
  // Pick the closer pairing: (a→c, b→d) or (a→d, b→c).
  const d1 = Vec3.distance(va.position, vc.position) + Vec3.distance(vb.position, vd.position);
  const d2 = Vec3.distance(va.position, vd.position) + Vec3.distance(vb.position, vc.position);
  let order: Id[];
  if (d1 <= d2) order = [e1.a, e1.b, e2.b, e2.a];
  else order = [e1.a, e1.b, e2.a, e2.b];
  try {
    const f = mesh.addFace(order);
    mesh.recomputeFaceNormals();
    return f.id;
  } catch {
    return null;
  }
}

/**
 * Fill — close an open boundary edge by adding a face from its endpoints
 * plus a shared boundary neighbour. A "boundary" edge is one with exactly
 * one incident loop (a hole edge); fully-loose edges (0 loops) are also
 * accepted.
 */
export function fillEdge(mesh: EditableMesh, edgeId: Id): Id | null {
  const e = mesh.edges.get(edgeId);
  if (!e) return null;
  if (e.loops.length > 1) return null;
  const a = mesh.vertices.get(e.a);
  const b = mesh.vertices.get(e.b);
  if (!a || !b) return null;
  const isOpen = (oe: import('./Topology').Edge): boolean => oe.loops.length < 2;
  const aOpenNeighbours: Id[] = [];
  for (const eid of a.edges) {
    if (eid === edgeId) continue;
    const oe = mesh.edges.get(eid);
    if (!oe || !isOpen(oe)) continue;
    aOpenNeighbours.push(oe.a === e.a ? oe.b : oe.a);
  }
  const bOpenNeighbours: Id[] = [];
  for (const eid of b.edges) {
    if (eid === edgeId) continue;
    const oe = mesh.edges.get(eid);
    if (!oe || !isOpen(oe)) continue;
    bOpenNeighbours.push(oe.a === e.b ? oe.b : oe.a);
  }
  // Triangle: a–b–c with c shared by both sides.
  for (const an of aOpenNeighbours) {
    if (bOpenNeighbours.includes(an)) {
      try {
        const f = mesh.addFace([e.a, e.b, an]);
        mesh.recomputeFaceNormals();
        return f.id;
      } catch {
        return null;
      }
    }
  }
  // Quad: a–b–bn–an with an and bn connected by an open edge.
  for (const an of aOpenNeighbours) {
    for (const bn of bOpenNeighbours) {
      if (an === bn) continue;
      const an_v = mesh.vertices.get(an);
      if (!an_v) continue;
      const linked = an_v.edges.some((eid) => {
        const oe = mesh.edges.get(eid);
        return oe && isOpen(oe) && (oe.a === bn || oe.b === bn);
      });
      if (linked) {
        try {
          const f = mesh.addFace([e.a, e.b, bn, an]);
          mesh.recomputeFaceNormals();
          return f.id;
        } catch {
          continue;
        }
      }
    }
  }
  return null;
}

/** Remove an edge and its incident faces. */
export function deleteEdge(mesh: EditableMesh, edgeId: Id): void {
  const e = mesh.edges.get(edgeId);
  if (!e) return;
  const facesToRemove: Id[] = [];
  for (const lid of e.loops) {
    const loop = mesh.loops.get(lid);
    if (loop) facesToRemove.push(loop.faceId);
  }
  for (const fid of facesToRemove) mesh.removeFace(fid);
  mesh.removeLooseGeometry();
}

/**
 * Dissolve an edge: remove it and merge the two faces it separates into a
 * single n-gon. If the edge has fewer than two incident faces, falls back
 * to delete.
 */
export function dissolveEdge(mesh: EditableMesh, edgeId: Id): void {
  const e = mesh.edges.get(edgeId);
  if (!e) return;
  if (e.loops.length !== 2) {
    deleteEdge(mesh, edgeId);
    return;
  }
  const loopA = mesh.loops.get(e.loops[0])!;
  const loopB = mesh.loops.get(e.loops[1])!;
  const faceA = mesh.faces.get(loopA.faceId)!;
  const faceB = mesh.faces.get(loopB.faceId)!;
  // Build merged vert sequence by removing the shared edge.
  const seqA = faceA.loops.map((lid) => mesh.loops.get(lid)!.vertexId);
  const seqB = faceB.loops.map((lid) => mesh.loops.get(lid)!.vertexId);
  // Find the edge endpoints in both sequences.
  const idxA = seqA.findIndex((v, i) => {
    const next = seqA[(i + 1) % seqA.length];
    return (v === e.a && next === e.b) || (v === e.b && next === e.a);
  });
  const idxB = seqB.findIndex((v, i) => {
    const next = seqB[(i + 1) % seqB.length];
    return (v === e.a && next === e.b) || (v === e.b && next === e.a);
  });
  if (idxA < 0 || idxB < 0) {
    deleteEdge(mesh, edgeId);
    return;
  }
  // Build merged loop: walk face A from idxA+1, then face B from idxB+1.
  const merged: Id[] = [];
  for (let i = 0; i < seqA.length - 1; i++) merged.push(seqA[(idxA + 1 + i) % seqA.length]);
  for (let i = 0; i < seqB.length - 1; i++) merged.push(seqB[(idxB + 1 + i) % seqB.length]);
  // Deduplicate consecutive matches.
  const dedup: Id[] = [];
  for (const v of merged) {
    if (dedup[dedup.length - 1] !== v) dedup.push(v);
  }
  if (dedup.length > 1 && dedup[0] === dedup[dedup.length - 1]) dedup.pop();
  mesh.removeFace(faceA.id);
  mesh.removeFace(faceB.id);
  try {
    mesh.addFace(dedup, faceA.materialId);
  } catch {
    // Fallback: leave a hole.
  }
  mesh.removeLooseGeometry();
  mesh.recomputeFaceNormals();
}

export function hardenEdges(mesh: EditableMesh, edgeIds: Iterable<Id>): void {
  for (const id of edgeIds) {
    const e = mesh.edges.get(id);
    if (e) e.hard = true;
  }
}

export function softenEdges(mesh: EditableMesh, edgeIds: Iterable<Id>): void {
  for (const id of edgeIds) {
    const e = mesh.edges.get(id);
    if (e) e.hard = false;
  }
}

export function markSeamEdges(mesh: EditableMesh, edgeIds: Iterable<Id>): void {
  for (const id of edgeIds) {
    const e = mesh.edges.get(id);
    if (e) e.seam = true;
  }
}

export function clearSeamEdges(mesh: EditableMesh, edgeIds: Iterable<Id>): void {
  for (const id of edgeIds) {
    const e = mesh.edges.get(id);
    if (e) e.seam = false;
  }
}
