// Routes viewport pointer events to the active sub-viewport's camera. Per
// idea.md:
//   * Middle drag → pan.
//   * Right drag  → orbit.
//   * Wheel       → dolly.
// Left-drag is reserved for selection / tools (items 14, 16). Touch
// behaviour is laid out at item 32 and overrides this controller's
// `pointerDown(2,…)` interpretation for two-finger gestures.

import type { ViewportInputDelegate } from '../ui/ViewportHost';
import type { ViewportLayout } from '../render/ViewportLayout';
import type { Camera } from '../render/Camera';

export class CameraController implements ViewportInputDelegate {
  private dragButton: number | null = null;
  private hoverCam: Camera | null = null;

  constructor(private layout: ViewportLayout) {}

  pointerDown(button: number, x: number, y: number): void {
    this.dragButton = button;
    const sub = this.layout.subviewportAt(x, y);
    this.hoverCam = sub?.camera ?? null;
  }

  pointerMove(x: number, y: number, dx: number, dy: number): void {
    if (this.dragButton == null) {
      // Hover: track the camera under the cursor so wheel-dolly uses it.
      const sub = this.layout.subviewportAt(x, y);
      this.hoverCam = sub?.camera ?? null;
      return;
    }
    if (!this.hoverCam) return;
    if (this.dragButton === 1) {
      // Middle drag → pan.
      this.hoverCam.pan(dx, dy);
    } else if (this.dragButton === 2) {
      // Right drag → orbit.
      this.hoverCam.orbit(dx * 0.005, dy * 0.005);
    }
  }

  pointerUp(_button: number, _x: number, _y: number): void {
    this.dragButton = null;
  }

  wheel(delta: number, x: number, y: number): boolean {
    const sub = this.layout.subviewportAt(x, y);
    const cam = sub?.camera ?? this.hoverCam;
    if (!cam) return false;
    cam.dolly(delta);
    return true;
  }
}
