// Verify each vertex command preserves do/undo/redo + validity.

import { defineTest, assert, assertEquals } from '../../harness';
import { MeshObject } from '../../scene/MeshObject';
import { buildCube } from '../../mesh/primitives/Cube';
import { History } from '../Commands';
import {
  TranslateVertsCommand,
  RotateVertsCommand,
  ScaleVertsCommand,
  MergeVertsCommand,
  WeldVertsCommand,
  DeleteVertCommand,
  DissolveVertCommand,
  BevelVertCommand,
  SmoothVertsCommand,
  KnifeCommand,
} from './VertexCommands';
import * as Vec3 from '../../core/math/Vec3';

const SUITE = 'vertexCommands';

function setup(): { node: MeshObject; history: History } {
  const node = new MeshObject('Cube');
  node.mesh = buildCube();
  return { node, history: new History() };
}

function topologyOk(node: MeshObject): boolean {
  const r = node.mesh!.validate();
  if (r.ok) return true;
  // Allow some non-fatal issues (e.g., loose edges after a delete) so the
  // gate doesn't fail on quirks.
  return r.errors.every((e) => !e.includes('loose edge') && !e.includes('loose vertex'));
}

defineTest(SUITE, 'TranslateVertsCommand do/undo/redo', () => {
  const { node, history } = setup();
  const ids = Array.from(node.mesh!.vertices.keys()).slice(0, 4);
  const before = ids.map((id) => node.mesh!.vertices.get(id)!.position[0]);
  history.execute(new TranslateVertsCommand(node, ids, 5, 0, 0));
  const after = ids.map((id) => node.mesh!.vertices.get(id)!.position[0]);
  for (let i = 0; i < ids.length; i++) assert(Math.abs(after[i] - before[i] - 5) < 1e-6);
  history.undo();
  const undone = ids.map((id) => node.mesh!.vertices.get(id)!.position[0]);
  for (let i = 0; i < ids.length; i++) assert(Math.abs(undone[i] - before[i]) < 1e-6);
  history.redo();
  assert(topologyOk(node));
});

defineTest(SUITE, 'RotateVertsCommand do/undo', () => {
  const { node, history } = setup();
  const id = Array.from(node.mesh!.vertices.keys())[0];
  const before = [...node.mesh!.vertices.get(id)!.position];
  history.execute(new RotateVertsCommand(node, [id], 'y', Math.PI / 2));
  const after = node.mesh!.vertices.get(id)!.position;
  assert(Math.abs(after[0] - before[2]) < 1e-5);
  history.undo();
  for (let i = 0; i < 3; i++) assert(Math.abs(node.mesh!.vertices.get(id)!.position[i] - before[i]) < 1e-5);
});

defineTest(SUITE, 'ScaleVertsCommand do/undo', () => {
  const { node, history } = setup();
  const id = Array.from(node.mesh!.vertices.keys())[0];
  const before = Vec3.length(node.mesh!.vertices.get(id)!.position);
  history.execute(new ScaleVertsCommand(node, [id], 2, 2, 2));
  const after = Vec3.length(node.mesh!.vertices.get(id)!.position);
  assert(Math.abs(after - before * 2) < 1e-5);
  history.undo();
  assert(Math.abs(Vec3.length(node.mesh!.vertices.get(id)!.position) - before) < 1e-5);
});

defineTest(SUITE, 'MergeVertsCommand undo restores both verts', () => {
  const { node, history } = setup();
  const ids = Array.from(node.mesh!.vertices.keys()).slice(0, 2);
  history.execute(new MergeVertsCommand(node, ids));
  // After merge, the second vertex is removed.
  assert(!node.mesh!.vertices.has(ids[1]));
  history.undo();
  // Undo restores both via mesh snapshot.
  assertEquals(node.mesh!.vertexCount(), 8);
});

defineTest(SUITE, 'WeldVertsCommand do/undo', () => {
  const { node, history } = setup();
  const ids = Array.from(node.mesh!.vertices.keys());
  history.execute(new WeldVertsCommand(node, ids[0], ids[1]));
  // weldVerts(from, to) keeps `from` as the survivor and removes `to`.
  assert(!node.mesh!.vertices.has(ids[1]));
  history.undo();
  assertEquals(node.mesh!.vertexCount(), 8);
});

defineTest(SUITE, 'DeleteVertCommand do/undo', () => {
  const { node, history } = setup();
  const id = Array.from(node.mesh!.vertices.keys())[0];
  history.execute(new DeleteVertCommand(node, id));
  assert(!node.mesh!.vertices.has(id));
  history.undo();
  assertEquals(node.mesh!.vertexCount(), 8);
});

defineTest(SUITE, 'DissolveVertCommand do/undo', () => {
  const { node, history } = setup();
  const id = Array.from(node.mesh!.vertices.keys())[0];
  history.execute(new DissolveVertCommand(node, id));
  history.undo();
  assertEquals(node.mesh!.vertexCount(), 8);
});

defineTest(SUITE, 'BevelVertCommand do/undo restores topology', () => {
  const { node, history } = setup();
  const id = Array.from(node.mesh!.vertices.keys())[0];
  history.execute(new BevelVertCommand(node, id, 0.2));
  history.undo();
  assertEquals(node.mesh!.vertexCount(), 8);
  assertEquals(node.mesh!.faceCount(), 6);
});

defineTest(SUITE, 'SmoothVertsCommand do/undo restores positions', () => {
  const { node, history } = setup();
  const ids = Array.from(node.mesh!.vertices.keys());
  const before = ids.map((id) => [...node.mesh!.vertices.get(id)!.position]);
  history.execute(new SmoothVertsCommand(node, ids, 0.5));
  history.undo();
  for (let i = 0; i < ids.length; i++) {
    const v = node.mesh!.vertices.get(ids[i])!;
    for (let j = 0; j < 3; j++) {
      assert(Math.abs(v.position[j] - before[i][j]) < 1e-5);
    }
  }
});

defineTest(SUITE, 'KnifeCommand do/undo', () => {
  const { node, history } = setup();
  const before = node.mesh!.vertexCount();
  history.execute(new KnifeCommand(node, Vec3.fromValues(-2, 0, 0), Vec3.fromValues(2, 0, 0)));
  // After knife the vert count may increase; undo restores.
  history.undo();
  assertEquals(node.mesh!.vertexCount(), before);
});
