// Bottom status bar — FPS, mesh stats, ready text. Item 4 stubs the data;
// the App updates the text each frame.

export interface FooterRefs {
  bar: Gwen.StatusBar;
  setStats(stats: FooterStats): void;
}

export interface FooterStats {
  fps: number;
  frameMs: number;
  objects: number;
  vertices: number;
  edges: number;
  faces: number;
  triangles: number;
  status: string;
}

export function buildFooter(parent: Gwen.Base): FooterRefs {
  const bar = new Gwen.StatusBar(parent);
  bar.setText('FPS 0 — Ready');

  return {
    bar,
    setStats(s: FooterStats): void {
      const parts = [
        `FPS ${s.fps.toFixed(0)}`,
        `Frame ${s.frameMs.toFixed(1)}ms`,
        `Objects ${s.objects}`,
        `Verts ${s.vertices}`,
        `Edges ${s.edges}`,
        `Faces ${s.faces}`,
        `Tris ${s.triangles}`,
        s.status,
      ];
      bar.setText(parts.join('   '));
    },
  };
}
