// Unit tests for object-mode operations.

import { defineTest, assert, assertEquals } from '../harness';
import { EditableMesh } from './EditableMesh';
import { shadeFlat, shadeSmooth, subdivide, mirror, append } from './OperationsObject';
import { cloneMesh } from './MeshClone';
import { buildCube } from './primitives/Cube';
import { buildPlane } from './primitives/Plane';

const SUITE = 'objectOps';

defineTest(SUITE, 'shadeFlat sets every edge hard; shadeSmooth clears it', () => {
  const m = buildCube();
  shadeFlat(m);
  for (const e of m.edges.values()) assertEquals(e.hard, true);
  shadeSmooth(m);
  for (const e of m.edges.values()) assertEquals(e.hard, false);
});

defineTest(SUITE, 'subdivide quad mesh quadruples face count', () => {
  const m = buildPlane({ segmentsX: 1, segmentsZ: 1 });
  const before = m.faceCount();
  subdivide(m);
  assertEquals(m.faceCount(), before * 4);
});

defineTest(SUITE, 'subdivide preserves validity', () => {
  const m = buildCube();
  subdivide(m);
  const r = m.validate();
  assert(r.ok, r.errors.join('; '));
});

defineTest(SUITE, 'mirror across X doubles vertex count (without merge)', () => {
  const m = buildPlane({ segmentsX: 1, segmentsZ: 1 });
  // Move plane off the X=0 axis so mirror produces a separate copy.
  for (const v of m.vertices.values()) v.position[0] += 1;
  const before = m.vertexCount();
  mirror(m, 'x', false);
  assertEquals(m.vertexCount(), before * 2);
});

defineTest(SUITE, 'mirror with merge collapses vertices ON the mirror plane', () => {
  // Build a quad with two verts on the X=0 plane and two off it.
  const m = new EditableMesh();
  const a = m.addVertex(0, 0, -1).id;
  const b = m.addVertex(1, 0, -1).id;
  const c = m.addVertex(1, 0, 1).id;
  const d = m.addVertex(0, 0, 1).id;
  m.addFace([a, b, c, d]);
  const before = m.vertexCount(); // 4
  mirror(m, 'x', true);
  // a and d sit on X=0 → not duplicated. b and c (at X=1) mirror to two new verts.
  assertEquals(m.vertexCount(), before + 2);
});

defineTest(SUITE, 'append combines two meshes by additive geometry', () => {
  const a = buildPlane({ segmentsX: 1, segmentsZ: 1 });
  const b = buildPlane({ segmentsX: 1, segmentsZ: 1 });
  const vBefore = a.vertexCount();
  const fBefore = a.faceCount();
  append(a, b);
  assertEquals(a.vertexCount(), vBefore + b.vertexCount());
  assertEquals(a.faceCount(), fBefore + b.faceCount());
});

defineTest(SUITE, 'cloneMesh round-trip preserves counts', () => {
  const m = buildCube();
  const c = cloneMesh(m);
  assertEquals(c.vertexCount(), m.vertexCount());
  assertEquals(c.edgeCount(), m.edgeCount());
  assertEquals(c.faceCount(), m.faceCount());
});
