// BrutalMesh entrypoint.

import { runTests, listSuites, defineTest, assert, assertEquals, assertClose, assertThrows } from './harness';
import { App } from './app/App';
import * as EdgeCommandsModule from './app/commands/EdgeCommands';
import * as FaceCommandsModule from './app/commands/FaceCommands';
import * as PrimitiveCommandsModule from './app/commands/CreatePrimitiveCommand';
import * as MaterialCommandsModule from './app/commands/MaterialCommands';
import * as UvCommandsModule from './app/commands/UvCommands';
import * as UnwrapModule from './mesh/Unwrap';
import * as ObjFormat from './io/ObjFormat';
import * as GltfFormat from './io/GltfFormat';
import * as BmshFormat from './io/BmshFormat';
import { Material } from './scene/Material';
import { ReferenceImage } from './scene/ReferenceImage';

// Register browser-side unit tests so the harness can run them via Playwright.
import './core/math/mathTests';
import './scene/sceneTests';
import './mesh/topologyTests';
import './mesh/primitives/primitiveTests';
import './mesh/renderMeshTests';
import './render/stripTests';
import './app/pickingTests';
import './app/commandsTests';
import './mesh/operationsObjectTests';
import './app/commands/objectCommandsTests';
import './mesh/operationsVertexTests';
import './app/commands/vertexCommandsTests';
import './mesh/operationsEdgeTests';
import './app/commands/edgeCommandsTests';
import './mesh/operationsFaceTests';
import './app/commands/faceCommandsTests';
import './app/commands/materialCommandsTests';
import './app/commands/uvCommandsTests';
import './mesh/unwrapTests';
import './io/objFormatTests';
import './io/gltfFormatTests';
import './io/bmshFormatTests';
import './scene/referenceImageTests';

interface HarnessGlobal {
  runTests: typeof runTests;
  listSuites: typeof listSuites;
  defineTest: typeof defineTest;
  assert: typeof assert;
  assertEquals: typeof assertEquals;
  assertClose: typeof assertClose;
  assertThrows: typeof assertThrows;
}

let appInstance: App | null = null;

function boot(): void {
  const canvas = document.getElementById('app');
  if (!(canvas instanceof HTMLCanvasElement)) {
    throw new Error('BrutalMesh: #app canvas element missing');
  }
  // Make sure CSS has assigned size before we sample clientWidth/clientHeight.
  // The HTML sets width:100vw and height:100vh on #app via the stylesheet.
  appInstance = new App({ canvas });
  appInstance.start();

  const w = window as unknown as {
    BrutalMeshHarness: HarnessGlobal;
    BrutalMeshApp: App;
    BrutalMeshEdgeCommands: typeof EdgeCommandsModule;
    BrutalMeshFaceCommands: typeof FaceCommandsModule;
    BrutalMeshPrimitiveCommands: typeof PrimitiveCommandsModule;
    BrutalMeshMaterialCommands: typeof MaterialCommandsModule;
    BrutalMeshUvCommands: typeof UvCommandsModule;
    BrutalMeshUnwrap: typeof UnwrapModule;
    BrutalMeshObj: typeof ObjFormat;
    BrutalMeshGltf: typeof GltfFormat;
    BrutalMeshBmsh: typeof BmshFormat;
    BrutalMeshMaterial: typeof Material;
    BrutalMeshReferenceImage: typeof ReferenceImage;
    __brutalMeshReady: boolean;
  };
  w.BrutalMeshHarness = {
    runTests,
    listSuites,
    defineTest,
    assert,
    assertEquals,
    assertClose,
    assertThrows,
  };
  w.BrutalMeshApp = appInstance;
  w.BrutalMeshEdgeCommands = EdgeCommandsModule;
  w.BrutalMeshFaceCommands = FaceCommandsModule;
  w.BrutalMeshPrimitiveCommands = PrimitiveCommandsModule;
  w.BrutalMeshMaterialCommands = MaterialCommandsModule;
  w.BrutalMeshUvCommands = UvCommandsModule;
  w.BrutalMeshUnwrap = UnwrapModule;
  w.BrutalMeshObj = ObjFormat;
  w.BrutalMeshGltf = GltfFormat;
  w.BrutalMeshBmsh = BmshFormat;
  w.BrutalMeshMaterial = Material;
  w.BrutalMeshReferenceImage = ReferenceImage;
  w.__brutalMeshReady = true;
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', boot);
} else {
  boot();
}
