// UV-space transforms — operate on per-loop UV coordinates.

import { EditableMesh } from './EditableMesh';
import type { Id } from '../core/Id';

export function translateUvLoops(mesh: EditableMesh, loopIds: Iterable<Id>, du: number, dv: number): void {
  for (const lid of loopIds) {
    const l = mesh.loops.get(lid);
    if (!l) continue;
    l.uv[0] += du;
    l.uv[1] += dv;
  }
}

export function scaleUvLoops(
  mesh: EditableMesh,
  loopIds: Iterable<Id>,
  sx: number,
  sy: number,
  pivotU = 0.5,
  pivotV = 0.5,
): void {
  for (const lid of loopIds) {
    const l = mesh.loops.get(lid);
    if (!l) continue;
    l.uv[0] = pivotU + (l.uv[0] - pivotU) * sx;
    l.uv[1] = pivotV + (l.uv[1] - pivotV) * sy;
  }
}

export function rotateUvLoops(
  mesh: EditableMesh,
  loopIds: Iterable<Id>,
  rad: number,
  pivotU = 0.5,
  pivotV = 0.5,
): void {
  const c = Math.cos(rad);
  const s = Math.sin(rad);
  for (const lid of loopIds) {
    const l = mesh.loops.get(lid);
    if (!l) continue;
    const du = l.uv[0] - pivotU;
    const dv = l.uv[1] - pivotV;
    l.uv[0] = pivotU + du * c - dv * s;
    l.uv[1] = pivotV + du * s + dv * c;
  }
}
