// Upper-corner view widget — small ActionBar with buttons that snap the
// active perspective camera to a canonical orthographic orientation.

export interface ViewWidgetRefs {
  bar: Gwen.ActionBar;
  buttons: Record<string, Gwen.ActionBarButton>;
}

export function buildViewWidget(parent: Gwen.Base): ViewWidgetRefs {
  const bar = new Gwen.ActionBar(parent);
  bar.setVertical(false);
  bar.setItemSize(20);
  const labels: Array<{ id: string; text: string; tooltip: string }> = [
    { id: 'top',    text: 'T', tooltip: 'Top view' },
    { id: 'front',  text: 'F', tooltip: 'Front view' },
    { id: 'right',  text: 'R', tooltip: 'Right view' },
    { id: 'back',   text: 'B', tooltip: 'Back view' },
    { id: 'left',   text: 'L', tooltip: 'Left view' },
    { id: 'bottom', text: 'D', tooltip: 'Bottom view' },
    { id: 'perspective', text: 'P', tooltip: 'Reset to perspective' },
  ];
  const buttons: Record<string, Gwen.ActionBarButton> = {};
  for (const l of labels) {
    const b = bar.addButton(l.text);
    b.setToolTip(l.tooltip);
    buttons[l.id] = b;
  }
  return { bar, buttons };
}
