// 2D vector — used for UVs and screen-space gizmo math.

export type Vec2 = Float32Array;

export function create(): Vec2 {
  return new Float32Array(2);
}

export function fromValues(x: number, y: number): Vec2 {
  const v = new Float32Array(2);
  v[0] = x;
  v[1] = y;
  return v;
}

export function set(out: Vec2, x: number, y: number): Vec2 {
  out[0] = x;
  out[1] = y;
  return out;
}

export function copy(out: Vec2, a: Readonly<Vec2>): Vec2 {
  out[0] = a[0];
  out[1] = a[1];
  return out;
}

export function add(out: Vec2, a: Readonly<Vec2>, b: Readonly<Vec2>): Vec2 {
  out[0] = a[0] + b[0];
  out[1] = a[1] + b[1];
  return out;
}

export function sub(out: Vec2, a: Readonly<Vec2>, b: Readonly<Vec2>): Vec2 {
  out[0] = a[0] - b[0];
  out[1] = a[1] - b[1];
  return out;
}

export function scale(out: Vec2, a: Readonly<Vec2>, k: number): Vec2 {
  out[0] = a[0] * k;
  out[1] = a[1] * k;
  return out;
}

export function dot(a: Readonly<Vec2>, b: Readonly<Vec2>): number {
  return a[0] * b[0] + a[1] * b[1];
}

export function cross(a: Readonly<Vec2>, b: Readonly<Vec2>): number {
  return a[0] * b[1] - a[1] * b[0];
}

export function length(a: Readonly<Vec2>): number {
  return Math.hypot(a[0], a[1]);
}

export function distance(a: Readonly<Vec2>, b: Readonly<Vec2>): number {
  return Math.hypot(a[0] - b[0], a[1] - b[1]);
}

export function distanceSq(a: Readonly<Vec2>, b: Readonly<Vec2>): number {
  const dx = a[0] - b[0], dy = a[1] - b[1];
  return dx * dx + dy * dy;
}

export function normalize(out: Vec2, a: Readonly<Vec2>): Vec2 {
  const len = length(a);
  if (len > 0) {
    out[0] = a[0] / len;
    out[1] = a[1] / len;
  } else {
    out[0] = 0;
    out[1] = 0;
  }
  return out;
}

export function lerp(out: Vec2, a: Readonly<Vec2>, b: Readonly<Vec2>, t: number): Vec2 {
  out[0] = a[0] + t * (b[0] - a[0]);
  out[1] = a[1] + t * (b[1] - a[1]);
  return out;
}

export function equalsApprox(a: Readonly<Vec2>, b: Readonly<Vec2>, eps = 1e-5): boolean {
  return Math.abs(a[0] - b[0]) <= eps && Math.abs(a[1] - b[1]) <= eps;
}
