// Browser-side unit test harness — built into modeller.js so Playwright
// tests can call `window.BrutalMeshHarness.run('<suite>')` via page.evaluate.
//
// Tests register themselves at import time; the harness is a flat registry
// that Playwright drives. We intentionally avoid pulling in a JS testing
// framework — the goal is to exercise the same compiled modules the editor
// uses, not to grow a parallel test infrastructure.

export type TestFn = () => void | Promise<void>;

interface RegisteredTest {
  suite: string;
  name: string;
  fn: TestFn;
}

interface TestResult {
  suite: string;
  name: string;
  passed: boolean;
  error?: string;
  durationMs: number;
}

const tests: RegisteredTest[] = [];

export function defineTest(suite: string, name: string, fn: TestFn): void {
  tests.push({ suite, name, fn });
}

export async function runTests(filter?: { suite?: string; name?: string }): Promise<TestResult[]> {
  const results: TestResult[] = [];
  for (const t of tests) {
    if (filter?.suite && t.suite !== filter.suite) continue;
    if (filter?.name && t.name !== filter.name) continue;
    const start = performance.now();
    try {
      await t.fn();
      results.push({ suite: t.suite, name: t.name, passed: true, durationMs: performance.now() - start });
    } catch (err) {
      const msg = err instanceof Error ? `${err.message}\n${err.stack ?? ''}` : String(err);
      results.push({
        suite: t.suite,
        name: t.name,
        passed: false,
        error: msg,
        durationMs: performance.now() - start,
      });
    }
  }
  return results;
}

export function listSuites(): string[] {
  return Array.from(new Set(tests.map((t) => t.suite)));
}

export function assert(cond: unknown, message?: string): asserts cond {
  if (!cond) throw new Error('assertion failed' + (message ? `: ${message}` : ''));
}

export function assertEquals<T>(actual: T, expected: T, message?: string): void {
  if (actual !== expected) {
    throw new Error(
      `assertEquals failed${message ? ` (${message})` : ''}: expected ${String(expected)}, got ${String(actual)}`,
    );
  }
}

export function assertClose(actual: number, expected: number, eps = 1e-6, message?: string): void {
  if (Math.abs(actual - expected) > eps) {
    throw new Error(
      `assertClose failed${message ? ` (${message})` : ''}: expected ${expected} ± ${eps}, got ${actual}`,
    );
  }
}

export function assertThrows(fn: () => unknown, message?: string): void {
  try {
    fn();
  } catch {
    return;
  }
  throw new Error('assertThrows failed' + (message ? `: ${message}` : ''));
}
