// BMSH save / load roundtrip tests.

import { defineTest, assert, assertEquals } from '../harness';
import { Scene, MeshObject } from '../scene/Scene';
import { Material } from '../scene/Material';
import { buildCube } from '../mesh/primitives/Cube';
import { buildPlane } from '../mesh/primitives/Plane';
import { saveBmsh, loadBmsh, BMSH_MAGIC, BmshVersionError } from './BmshFormat';

const SUITE = 'bmshIo';

defineTest(SUITE, 'BMSH file has the right magic + version', () => {
  const scene = new Scene();
  const node = new MeshObject('Cube');
  node.mesh = buildCube();
  scene.addNode(node);
  const blob = saveBmsh(scene);
  const u8 = new Uint8Array(blob);
  assertEquals(String.fromCharCode(u8[0], u8[1], u8[2], u8[3]), BMSH_MAGIC);
  const dv = new DataView(blob);
  assertEquals(dv.getUint32(4, true), 1);
});

defineTest(SUITE, 'roundtrip preserves vertex / edge / face counts and validity', () => {
  const scene = new Scene();
  const node = new MeshObject('Cube');
  node.mesh = buildCube();
  scene.addNode(node);
  const blob = saveBmsh(scene);
  const re = loadBmsh(blob);
  // Find the cube.
  const meshNodes: MeshObject[] = [];
  re.forEachNode((n) => { if (n.kind === 'mesh') meshNodes.push(n as MeshObject); });
  assertEquals(meshNodes.length, 1);
  const m = meshNodes[0].mesh!;
  assertEquals(m.vertexCount(), 8);
  assertEquals(m.edgeCount(), 12);
  assertEquals(m.faceCount(), 6);
  assert(m.validate().ok);
});

defineTest(SUITE, 'roundtrip preserves UVs', () => {
  const scene = new Scene();
  const node = new MeshObject('Plane');
  node.mesh = buildPlane({ segmentsX: 2, segmentsZ: 2 });
  // Tag a specific loop with a deterministic UV.
  const firstLoopId = Array.from(node.mesh!.loops.keys())[0];
  const l = node.mesh!.loops.get(firstLoopId)!;
  l.uv[0] = 0.123; l.uv[1] = 0.456;
  scene.addNode(node);
  const blob = saveBmsh(scene);
  const re = loadBmsh(blob);
  let found: { u: number; v: number } | null = null;
  re.forEachNode((n) => {
    if (n.kind !== 'mesh') return;
    const m = (n as MeshObject).mesh!;
    for (const loop of m.loops.values()) {
      if (Math.abs(loop.uv[0] - 0.123) < 1e-6 && Math.abs(loop.uv[1] - 0.456) < 1e-6) {
        found = { u: loop.uv[0], v: loop.uv[1] };
      }
    }
  });
  assert(found != null);
});

defineTest(SUITE, 'roundtrip preserves seam + hard edge flags', () => {
  const scene = new Scene();
  const node = new MeshObject('Cube');
  node.mesh = buildCube();
  // Mark every edge as hard + seam.
  for (const e of node.mesh!.edges.values()) {
    e.hard = true;
    e.seam = true;
  }
  scene.addNode(node);
  const blob = saveBmsh(scene);
  const re = loadBmsh(blob);
  let allHard = true, allSeam = true;
  re.forEachNode((n) => {
    if (n.kind !== 'mesh') return;
    const m = (n as MeshObject).mesh!;
    for (const e of m.edges.values()) {
      if (!e.hard) allHard = false;
      if (!e.seam) allSeam = false;
    }
  });
  assert(allHard);
  assert(allSeam);
});

defineTest(SUITE, 'roundtrip preserves materials and texture metadata', () => {
  const scene = new Scene();
  const node = new MeshObject('Cube');
  node.mesh = buildCube();
  const mat = new Material('Red');
  mat.setBaseColor(0.9, 0.1, 0.1);
  mat.setTexture({ name: 'flag', width: 2, height: 2, data: new Uint8Array([255, 0, 0, 255, 0, 255, 0, 255, 0, 0, 255, 255, 255, 255, 0, 255]) });
  scene.addMaterial(mat);
  node.materialId = mat.id;
  scene.addNode(node);
  const blob = saveBmsh(scene);
  const re = loadBmsh(blob);
  const reMats = re.materials();
  assertEquals(reMats.length, 1);
  assertEquals(reMats[0].name, 'Red');
  assert(reMats[0].texture != null);
  assertEquals(reMats[0].texture!.width, 2);
});

defineTest(SUITE, 'roundtrip preserves hierarchy parenting', () => {
  const scene = new Scene();
  const parent = new MeshObject('Parent');
  parent.mesh = buildCube();
  scene.addNode(parent);
  const child = new MeshObject('Child');
  child.mesh = buildPlane({ segmentsX: 1, segmentsZ: 1 });
  scene.addNode(child, parent);
  const blob = saveBmsh(scene);
  const re = loadBmsh(blob);
  let pNode: MeshObject | null = null;
  let cNode: MeshObject | null = null;
  re.forEachNode((n) => {
    if (n.name === 'Parent') pNode = n as MeshObject;
    if (n.name === 'Child') cNode = n as MeshObject;
  });
  assert(pNode != null);
  assert(cNode != null);
  assertEquals((cNode as unknown as MeshObject).parent, pNode as unknown as MeshObject);
});

defineTest(SUITE, 'loading an unknown future version throws BmshVersionError', () => {
  // Synthesize a header with version 999.
  const buf = new ArrayBuffer(12);
  const dv = new DataView(buf);
  const u8 = new Uint8Array(buf);
  u8[0] = 66; u8[1] = 77; u8[2] = 83; u8[3] = 72; // "BMSH"
  dv.setUint32(4, 999, true);
  dv.setUint32(8, 0, true);
  let caught: unknown = null;
  try { loadBmsh(buf); } catch (e) { caught = e; }
  assert(caught instanceof BmshVersionError);
});
