// Unit tests for selection state + CPU picking.

import { defineTest, assert, assertEquals } from '../harness';
import { Selection } from './Selection';
import { pickObjectInScene, pickFace, pickVertex, pickEdge } from './Picking';
import { Scene } from '../scene/Scene';
import { MeshObject } from '../scene/MeshObject';
import { buildCube } from '../mesh/primitives/Cube';
import { Camera } from '../render/Camera';
import * as Mat4 from '../core/math/Mat4';
import type { Id } from '../core/Id';

const SUITE = 'picking';

function makeScene(): { scene: Scene; cube: MeshObject; camera: Camera } {
  const scene = new Scene();
  const cube = new MeshObject('Cube');
  cube.mesh = buildCube();
  scene.addNode(cube);
  const camera = new Camera();
  camera.target.set([0, 0, 0]);
  camera.yaw = 0;
  camera.pitch = 0;
  camera.distance = 6;
  return { scene, cube, camera };
}

defineTest(SUITE, 'Selection state: basic API', () => {
  const sel = new Selection();
  const id = 42 as unknown as Id;
  sel.setObjectSelection(id);
  assert(sel.isObjectSelected(id));
  assertEquals(sel.activeObjectId, id);
  sel.clearAll();
  assert(!sel.isObjectSelected(id));
});

defineTest(SUITE, 'Object pick: ray through cube center hits the cube', () => {
  const { scene, cube, camera } = makeScene();
  // Looking from (0,0,6) toward (0,0,0). Center of viewport projects onto the front face.
  const vpRect = { x: 0, y: 0, w: 800, h: 600 };
  const hit = pickObjectInScene(scene, 400, 300, vpRect, camera, 800 / 600);
  assert(hit !== null);
  assertEquals(hit!.node.id, cube.id);
});

defineTest(SUITE, 'Object pick: ray missing the cube returns null', () => {
  const { scene, camera } = makeScene();
  const vpRect = { x: 0, y: 0, w: 800, h: 600 };
  // Sample a far corner of the viewport — projects far from the cube.
  const hit = pickObjectInScene(scene, 5, 5, vpRect, camera, 800 / 600);
  assert(hit === null);
});

defineTest(SUITE, 'Face pick returns a valid face id from center ray', () => {
  const { cube, camera } = makeScene();
  const vpRect = { x: 0, y: 0, w: 800, h: 600 };
  const world = cube.getWorldMatrix() as Float32Array;
  const fid = pickFace(cube.mesh!, world, 400, 300, vpRect, camera, 800 / 600);
  assert(fid !== null);
  assert(cube.mesh!.faces.has(fid!));
});

defineTest(SUITE, 'Vertex pick screen-distance: project a vertex then pick at that pixel', () => {
  const { cube, camera } = makeScene();
  const vpRect = { x: 0, y: 0, w: 800, h: 600 };
  const world = cube.getWorldMatrix() as Float32Array;
  const viewProj = camera.viewProj(800 / 600) as Float32Array;
  // Pick a real cube vertex, project it, then pick at the projected pixel.
  // Project import is heavy in the test; do it via cached math.
  const vertex = cube.mesh!.vertices.values().next().value!;
  // Manual projection.
  const px = vertex.position[0], py = vertex.position[1], pz = vertex.position[2];
  // Transform with world * viewProj.
  // World is identity here, so just viewProj.
  const w = viewProj[3] * px + viewProj[7] * py + viewProj[11] * pz + viewProj[15];
  const ndcX = (viewProj[0] * px + viewProj[4] * py + viewProj[8] * pz + viewProj[12]) / w;
  const ndcY = (viewProj[1] * px + viewProj[5] * py + viewProj[9] * pz + viewProj[13]) / w;
  const screenX = vpRect.x + (ndcX + 1) * 0.5 * vpRect.w;
  const screenY = vpRect.y + (1 - ndcY) * 0.5 * vpRect.h;
  const vid = pickVertex(cube.mesh!, world, screenX, screenY, vpRect, camera, 800 / 600, 6);
  assertEquals(vid, vertex.id);
});

defineTest(SUITE, 'Vertex pick: a pixel far from any vertex returns null', () => {
  const { cube, camera } = makeScene();
  const vpRect = { x: 0, y: 0, w: 800, h: 600 };
  const world = cube.getWorldMatrix() as Float32Array;
  // (0, 0) screen corner is far from any cube vertex (which all sit near center).
  const vid = pickVertex(cube.mesh!, world, 0, 0, vpRect, camera, 800 / 600, 6);
  assert(vid === null);
});

defineTest(SUITE, 'Edge pick: a pixel between two projected vertices grabs the connecting edge', () => {
  const { cube, camera } = makeScene();
  const vpRect = { x: 0, y: 0, w: 800, h: 600 };
  const world = cube.getWorldMatrix() as Float32Array;
  const viewProj = camera.viewProj(800 / 600) as Float32Array;
  // Find an edge and project both endpoints to screen, then pick at the midpoint.
  const edge = cube.mesh!.edges.values().next().value!;
  const va = cube.mesh!.vertices.get(edge.a)!;
  const vb = cube.mesh!.vertices.get(edge.b)!;
  const proj = (p: Float32Array): [number, number] => {
    const w = viewProj[3] * p[0] + viewProj[7] * p[1] + viewProj[11] * p[2] + viewProj[15];
    const nx = (viewProj[0] * p[0] + viewProj[4] * p[1] + viewProj[8] * p[2] + viewProj[12]) / w;
    const ny = (viewProj[1] * p[0] + viewProj[5] * p[1] + viewProj[9] * p[2] + viewProj[13]) / w;
    return [vpRect.x + (nx + 1) * 0.5 * vpRect.w, vpRect.y + (1 - ny) * 0.5 * vpRect.h];
  };
  const [ax, ay] = proj(va.position);
  const [bx, by] = proj(vb.position);
  const mx = (ax + bx) * 0.5;
  const my = (ay + by) * 0.5;
  const eid = pickEdge(cube.mesh!, world, mx, my, vpRect, camera, 800 / 600, 6);
  assert(eid !== null);
});

defineTest(SUITE, 'Picking respects world transform: project the translated cube center, then pick there', () => {
  const { scene, cube, camera } = makeScene();
  const vpRect = { x: 0, y: 0, w: 800, h: 600 };
  cube.transform.setPosition(2.5, 0, 0); // small offset so the cube stays in frustum
  cube.markWorldDirty();
  void Mat4;
  // Project the cube's new center to screen, then pick there.
  const viewProj = camera.viewProj(800 / 600) as Float32Array;
  const cx = 2.5, cy = 0, cz = 0;
  const w = viewProj[3] * cx + viewProj[7] * cy + viewProj[11] * cz + viewProj[15];
  const ndcX = (viewProj[0] * cx + viewProj[4] * cy + viewProj[8] * cz + viewProj[12]) / w;
  const ndcY = (viewProj[1] * cx + viewProj[5] * cy + viewProj[9] * cz + viewProj[13]) / w;
  const screenX = (ndcX + 1) * 0.5 * vpRect.w;
  const screenY = (1 - ndcY) * 0.5 * vpRect.h;
  const hit = pickObjectInScene(scene, screenX, screenY, vpRect, camera, 800 / 600);
  assert(hit !== null, `cube should be pickable at projected center (${screenX}, ${screenY})`);
  assertEquals(hit!.node.id, cube.id);
});
