// Unit quaternion. Layout: [x, y, z, w] — w is the scalar part.

import type { Vec3 } from './Vec3';

export type Quat = Float32Array;

export function create(): Quat {
  const q = new Float32Array(4);
  q[3] = 1;
  return q;
}

export function fromValues(x: number, y: number, z: number, w: number): Quat {
  const q = new Float32Array(4);
  q[0] = x; q[1] = y; q[2] = z; q[3] = w;
  return q;
}

export function identity(out: Quat): Quat {
  out[0] = 0; out[1] = 0; out[2] = 0; out[3] = 1;
  return out;
}

export function copy(out: Quat, a: Readonly<Quat>): Quat {
  out[0] = a[0]; out[1] = a[1]; out[2] = a[2]; out[3] = a[3];
  return out;
}

export function setAxisAngle(out: Quat, axis: Readonly<Vec3>, rad: number): Quat {
  const half = rad * 0.5;
  const s = Math.sin(half);
  out[0] = axis[0] * s;
  out[1] = axis[1] * s;
  out[2] = axis[2] * s;
  out[3] = Math.cos(half);
  return out;
}

export function multiply(out: Quat, a: Readonly<Quat>, b: Readonly<Quat>): Quat {
  const ax = a[0], ay = a[1], az = a[2], aw = a[3];
  const bx = b[0], by = b[1], bz = b[2], bw = b[3];
  out[0] = ax * bw + aw * bx + ay * bz - az * by;
  out[1] = ay * bw + aw * by + az * bx - ax * bz;
  out[2] = az * bw + aw * bz + ax * by - ay * bx;
  out[3] = aw * bw - ax * bx - ay * by - az * bz;
  return out;
}

export function normalize(out: Quat, a: Readonly<Quat>): Quat {
  const x = a[0], y = a[1], z = a[2], w = a[3];
  let len = Math.hypot(x, y, z, w);
  if (len > 0) {
    len = 1 / len;
    out[0] = x * len;
    out[1] = y * len;
    out[2] = z * len;
    out[3] = w * len;
  }
  return out;
}

export function conjugate(out: Quat, a: Readonly<Quat>): Quat {
  out[0] = -a[0];
  out[1] = -a[1];
  out[2] = -a[2];
  out[3] = a[3];
  return out;
}

export function transformVec3(out: Vec3, v: Readonly<Vec3>, q: Readonly<Quat>): Vec3 {
  // out = q * v * q⁻¹, optimized formula.
  const qx = q[0], qy = q[1], qz = q[2], qw = q[3];
  const x = v[0], y = v[1], z = v[2];
  const ix = qw * x + qy * z - qz * y;
  const iy = qw * y + qz * x - qx * z;
  const iz = qw * z + qx * y - qy * x;
  const iw = -qx * x - qy * y - qz * z;
  out[0] = ix * qw + iw * -qx + iy * -qz - iz * -qy;
  out[1] = iy * qw + iw * -qy + iz * -qx - ix * -qz;
  out[2] = iz * qw + iw * -qz + ix * -qy - iy * -qx;
  return out;
}

export function equalsApprox(a: Readonly<Quat>, b: Readonly<Quat>, eps = 1e-5): boolean {
  return (
    Math.abs(a[0] - b[0]) <= eps &&
    Math.abs(a[1] - b[1]) <= eps &&
    Math.abs(a[2] - b[2]) <= eps &&
    Math.abs(a[3] - b[3]) <= eps
  );
}
