// Orbit camera: position derived from a target + spherical coords (yaw, pitch, distance).
// Standard right-handed OpenGL coordinates: +X right, +Y up, -Z forward.

import * as Vec3 from '../core/math/Vec3';
import * as Mat4 from '../core/math/Mat4';

export type CameraMode = 'perspective' | 'orthographic';

export class Camera {
  mode: CameraMode = 'perspective';
  target = Vec3.fromValues(0, 0, 0);
  yaw = Math.PI * 0.25;
  pitch = Math.PI * 0.18;
  distance = 6;
  fovY = Math.PI / 4;
  near = 0.05;
  far = 200;
  orthoSize = 5; // half-height in world units when orthographic

  private _view = Mat4.create();
  private _proj = Mat4.create();
  private _viewProj = Mat4.create();
  private _position = Vec3.create();

  setMode(mode: CameraMode): void {
    this.mode = mode;
  }

  orbit(yawDelta: number, pitchDelta: number): void {
    this.yaw += yawDelta;
    this.pitch = Math.max(-Math.PI / 2 + 0.01, Math.min(Math.PI / 2 - 0.01, this.pitch + pitchDelta));
  }

  pan(dx: number, dy: number): void {
    // Move target along camera-relative X and Y.
    const cosP = Math.cos(this.pitch);
    const sinP = Math.sin(this.pitch);
    const cosY = Math.cos(this.yaw);
    const sinY = Math.sin(this.yaw);
    // Camera right = (cos(yaw), 0, -sin(yaw))
    // Camera up = (-sin(yaw)*sin(pitch), cos(pitch), -cos(yaw)*sin(pitch))
    const speed = this.distance * 0.0015;
    this.target[0] -= (dx * cosY + dy * sinY * sinP) * speed;
    this.target[1] += dy * cosP * speed;
    this.target[2] -= (-dx * sinY + dy * cosY * sinP) * speed;
  }

  dolly(amount: number): void {
    const factor = Math.exp(-amount * 0.001);
    this.distance = Math.max(0.1, Math.min(500, this.distance * factor));
    if (this.mode === 'orthographic') {
      this.orthoSize = Math.max(0.1, Math.min(200, this.orthoSize * factor));
    }
  }

  /** Camera world position derived from target + spherical orbit. */
  position(): Readonly<Vec3.Vec3> {
    const cp = Math.cos(this.pitch);
    const sp = Math.sin(this.pitch);
    const cy = Math.cos(this.yaw);
    const sy = Math.sin(this.yaw);
    this._position[0] = this.target[0] + this.distance * cp * sy;
    this._position[1] = this.target[1] + this.distance * sp;
    this._position[2] = this.target[2] + this.distance * cp * cy;
    return this._position;
  }

  /** Forward direction in world space (target - position, normalized). */
  forward(out: Vec3.Vec3): Vec3.Vec3 {
    const pos = this.position();
    Vec3.sub(out, this.target, pos);
    return Vec3.normalize(out, out);
  }

  view(): Readonly<Mat4.Mat4> {
    return Mat4.lookAt(this._view, this.position(), this.target, Vec3.UNIT_Y);
  }

  proj(aspect: number): Readonly<Mat4.Mat4> {
    if (this.mode === 'perspective') {
      Mat4.perspective(this._proj, this.fovY, aspect, this.near, this.far);
    } else {
      const w = this.orthoSize * aspect;
      const h = this.orthoSize;
      Mat4.ortho(this._proj, -w, w, -h, h, this.near, this.far);
    }
    return this._proj;
  }

  viewProj(aspect: number): Readonly<Mat4.Mat4> {
    Mat4.multiply(this._viewProj, this.proj(aspect), this.view());
    return this._viewProj;
  }

  reset(): void {
    Vec3.set(this.target, 0, 0, 0);
    this.yaw = Math.PI * 0.25;
    this.pitch = Math.PI * 0.18;
    this.distance = 6;
  }

  /** Snap to a canonical orthographic view. */
  setOrientation(name: 'top' | 'front' | 'right' | 'back' | 'left' | 'bottom' | 'perspective'): void {
    switch (name) {
      case 'top':    this.yaw = 0;          this.pitch = Math.PI / 2 - 0.001; break;
      case 'bottom': this.yaw = 0;          this.pitch = -Math.PI / 2 + 0.001; break;
      case 'front':  this.yaw = 0;          this.pitch = 0; break;
      case 'back':   this.yaw = Math.PI;    this.pitch = 0; break;
      case 'right':  this.yaw = Math.PI / 2;this.pitch = 0; break;
      case 'left':   this.yaw = -Math.PI/2; this.pitch = 0; break;
      case 'perspective':
      default:       this.yaw = Math.PI*0.25; this.pitch = Math.PI*0.18; break;
    }
  }
}
