// ReferenceImage — image plane scene node for modelling reference.

import { SceneNode } from './SceneNode';

export interface ReferenceImagePixels {
  name: string;
  width: number;
  height: number;
  data: Uint8Array | null;
}

export class ReferenceImage extends SceneNode {
  pixels: ReferenceImagePixels | null = null;
  opacity = 1.0;
  /** Locked nodes can't be picked or moved through the UI. */
  locked = false;
  /** Image plane size in world units. The plane lies in the XY plane by default. */
  width = 1.0;
  height = 1.0;
  /** Bumped each time pixels change; renderers use this to decide re-upload. */
  pixelVersion = 0;

  constructor(name = 'Reference_Image') {
    super(name, 'reference');
  }

  setPixels(p: ReferenceImagePixels | null): void {
    this.pixels = p;
    this.pixelVersion++;
  }

  setLocked(l: boolean): void {
    this.locked = l;
    this.selectable = !l;
  }

  serialize(): {
    name: string;
    opacity: number;
    locked: boolean;
    width: number;
    height: number;
    pixels: { name: string; width: number; height: number } | null;
    transform: {
      position: [number, number, number];
      rotation: [number, number, number, number];
      scale: [number, number, number];
    };
    visible: boolean;
  } {
    return {
      name: this.name,
      opacity: this.opacity,
      locked: this.locked,
      width: this.width,
      height: this.height,
      pixels: this.pixels ? { name: this.pixels.name, width: this.pixels.width, height: this.pixels.height } : null,
      transform: {
        position: [this.transform.position[0], this.transform.position[1], this.transform.position[2]],
        rotation: [this.transform.rotation[0], this.transform.rotation[1], this.transform.rotation[2], this.transform.rotation[3]],
        scale: [this.transform.scale[0], this.transform.scale[1], this.transform.scale[2]],
      },
      visible: this.visible,
    };
  }
}
