// Gizmo base — common math + rendering helpers.

import * as Vec3 from '../core/math/Vec3';
import * as Mat4 from '../core/math/Mat4';
import type { Camera } from '../render/Camera';
import type { StripBatch } from '../render/StripRenderer';
import type { SceneNode } from '../scene/SceneNode';

export type GizmoAxis = 'x' | 'y' | 'z' | 'all';

export interface GizmoHit {
  axis: GizmoAxis;
}

export interface Gizmo {
  /** Build strip geometry for the gizmo at the node's position. */
  render(strips: StripBatch, node: SceneNode, camera: Camera, vpRect: { x: number; y: number; w: number; h: number }, aspect: number): void;
  /** Screen-space hit test. Returns the axis under the cursor, or null. */
  hit(screenX: number, screenY: number, node: SceneNode, camera: Camera, vpRect: { x: number; y: number; w: number; h: number }, aspect: number): GizmoHit | null;
}

/** Project a world point to screen. Returns [x, y, ndcZ] or null if behind. */
export function projectToScreen(world: Readonly<Vec3.Vec3>, viewProj: Float32Array, vpRect: { x: number; y: number; w: number; h: number }): [number, number, number] | null {
  const w = viewProj[3] * world[0] + viewProj[7] * world[1] + viewProj[11] * world[2] + viewProj[15];
  if (Math.abs(w) < 1e-6) return null;
  const ndcX = (viewProj[0] * world[0] + viewProj[4] * world[1] + viewProj[8] * world[2] + viewProj[12]) / w;
  const ndcY = (viewProj[1] * world[0] + viewProj[5] * world[1] + viewProj[9] * world[2] + viewProj[13]) / w;
  const ndcZ = (viewProj[2] * world[0] + viewProj[6] * world[1] + viewProj[10] * world[2] + viewProj[14]) / w;
  return [vpRect.x + (ndcX + 1) * 0.5 * vpRect.w, vpRect.y + (1 - ndcY) * 0.5 * vpRect.h, ndcZ];
}

/** Compute gizmo handle length in world units so it renders ~fixed pixels at this view. */
export function worldSizeForScreenPx(targetPx: number, camera: Camera, distance: number, aspect: number, vpH: number): number {
  // Approximate: gizmo length in world = (targetPx / vpH) * (visible world height at distance).
  const halfH = Math.tan(camera.fovY / 2) * distance;
  void aspect;
  return (targetPx / vpH) * halfH * 2;
}

export function getNodeOrigin(out: Vec3.Vec3, node: SceneNode): Vec3.Vec3 {
  const m = node.getWorldMatrix();
  out[0] = m[12]; out[1] = m[13]; out[2] = m[14];
  return out;
}

export function pointSegmentDistanceSq(px: number, py: number, ax: number, ay: number, bx: number, by: number): number {
  const dx = bx - ax, dy = by - ay;
  const lenSq = dx * dx + dy * dy;
  if (lenSq < 1e-9) {
    const ex = px - ax, ey = py - ay;
    return ex * ex + ey * ey;
  }
  let t = ((px - ax) * dx + (py - ay) * dy) / lenSq;
  t = Math.max(0, Math.min(1, t));
  const cx = ax + t * dx;
  const cy = ay + t * dy;
  const ex = px - cx, ey = py - cy;
  return ex * ex + ey * ey;
}

export const AXIS_VECTORS: Record<GizmoAxis, Readonly<Vec3.Vec3>> = {
  x: Vec3.fromValues(1, 0, 0),
  y: Vec3.fromValues(0, 1, 0),
  z: Vec3.fromValues(0, 0, 1),
  all: Vec3.fromValues(1, 1, 1),
};

void Mat4;
