// Ray (origin + direction) plus geometric tests (plane, triangle, AABB).

import * as Vec3 from './Vec3';
import type { Vec3 as Vec3T } from './Vec3';

export interface Ray {
  origin: Vec3T;
  direction: Vec3T; // assumed normalized
}

export function create(): Ray {
  return { origin: Vec3.create(), direction: Vec3.fromValues(0, 0, -1) };
}

export function set(out: Ray, origin: Readonly<Vec3T>, direction: Readonly<Vec3T>): Ray {
  Vec3.copy(out.origin, origin);
  Vec3.normalize(out.direction, direction);
  return out;
}

export function pointAt(out: Vec3T, ray: Ray, t: number): Vec3T {
  out[0] = ray.origin[0] + ray.direction[0] * t;
  out[1] = ray.origin[1] + ray.direction[1] * t;
  out[2] = ray.origin[2] + ray.direction[2] * t;
  return out;
}

/**
 * Möller–Trumbore ray–triangle intersection. Returns the parametric t along
 * the ray for the hit, or NaN if there's no intersection. Optional `outUv`
 * receives the barycentric (u, v) on the triangle.
 */
export function intersectTriangle(
  ray: Ray,
  v0: Readonly<Vec3T>,
  v1: Readonly<Vec3T>,
  v2: Readonly<Vec3T>,
  outUv?: Float32Array,
  doubleSided = true,
  eps = 1e-7,
): number {
  const edge1 = _e1;
  const edge2 = _e2;
  const h = _h;
  const s = _s;
  const q = _q;
  Vec3.sub(edge1, v1, v0);
  Vec3.sub(edge2, v2, v0);
  Vec3.cross(h, ray.direction, edge2);
  const a = Vec3.dot(edge1, h);
  if (!doubleSided && a < eps) return NaN;
  if (Math.abs(a) < eps) return NaN;
  const f = 1 / a;
  Vec3.sub(s, ray.origin, v0);
  const u = f * Vec3.dot(s, h);
  if (u < 0 || u > 1) return NaN;
  Vec3.cross(q, s, edge1);
  const v = f * Vec3.dot(ray.direction, q);
  if (v < 0 || u + v > 1) return NaN;
  const t = f * Vec3.dot(edge2, q);
  if (t < eps) return NaN;
  if (outUv) {
    outUv[0] = u;
    outUv[1] = v;
  }
  return t;
}

const _e1 = Vec3.create();
const _e2 = Vec3.create();
const _h = Vec3.create();
const _s = Vec3.create();
const _q = Vec3.create();
