// Wavefront OBJ + MTL import / export.
//
// Supports:
//   - vertex positions (v), texture coords (vt), normals (vn)
//   - faces (f) with triangles, quads, n-gons; v / v/vt / v//vn / v/vt/vn formats
//   - object groups (o name, g name)
//   - basic MTL references (mtllib, usemtl)
//   - basic MTL output: Kd (base color), d (opacity), Ka, Ks, Ns
//
// Limitations: we don't support smoothing groups (s), free-form geometry,
// curves, or MTL texture map paths beyond a single `map_Kd`.

import { EditableMesh } from '../mesh/EditableMesh';
import { Scene, MeshObject, Material } from '../scene/Scene';
import type { Id } from '../core/Id';

export interface ObjImportResult {
  scene: Scene;
  meshes: MeshObject[];
  materials: Material[];
}

interface MtlSnapshot {
  name: string;
  Kd?: [number, number, number];
  Ka?: [number, number, number];
  Ks?: [number, number, number];
  Ns?: number;
  d?: number; // opacity 0..1
  map_Kd?: string;
}

export function parseMtl(src: string): MtlSnapshot[] {
  const out: MtlSnapshot[] = [];
  let cur: MtlSnapshot | null = null;
  for (const rawLine of src.split(/\r?\n/)) {
    const line = rawLine.trim();
    if (!line || line.startsWith('#')) continue;
    const parts = line.split(/\s+/);
    const tag = parts[0];
    if (tag === 'newmtl') {
      cur = { name: parts.slice(1).join(' ') };
      out.push(cur);
    } else if (!cur) {
      continue;
    } else if (tag === 'Kd') {
      cur.Kd = [parseFloat(parts[1]), parseFloat(parts[2]), parseFloat(parts[3])];
    } else if (tag === 'Ka') {
      cur.Ka = [parseFloat(parts[1]), parseFloat(parts[2]), parseFloat(parts[3])];
    } else if (tag === 'Ks') {
      cur.Ks = [parseFloat(parts[1]), parseFloat(parts[2]), parseFloat(parts[3])];
    } else if (tag === 'Ns') {
      cur.Ns = parseFloat(parts[1]);
    } else if (tag === 'd') {
      cur.d = parseFloat(parts[1]);
    } else if (tag === 'map_Kd') {
      cur.map_Kd = parts.slice(1).join(' ');
    }
  }
  return out;
}

/** Pre-built OBJ data prior to topology construction. */
interface ObjBucket {
  name: string;
  faceRefs: Array<{ verts: Array<{ vi: number; vti?: number; vni?: number }>; materialName?: string }>;
}

export function parseObj(src: string): {
  positions: Array<[number, number, number]>;
  uvs: Array<[number, number]>;
  normals: Array<[number, number, number]>;
  groups: ObjBucket[];
  mtllibs: string[];
} {
  const positions: Array<[number, number, number]> = [];
  const uvs: Array<[number, number]> = [];
  const normals: Array<[number, number, number]> = [];
  const groups: ObjBucket[] = [];
  const mtllibs: string[] = [];
  let cur: ObjBucket = { name: 'default', faceRefs: [] };
  let curMaterial: string | undefined = undefined;
  groups.push(cur);
  for (const rawLine of src.split(/\r?\n/)) {
    const line = rawLine.trim();
    if (!line || line.startsWith('#')) continue;
    const parts = line.split(/\s+/);
    const tag = parts[0];
    if (tag === 'v') {
      positions.push([parseFloat(parts[1]), parseFloat(parts[2]), parseFloat(parts[3])]);
    } else if (tag === 'vt') {
      uvs.push([parseFloat(parts[1]), parseFloat(parts[2])]);
    } else if (tag === 'vn') {
      normals.push([parseFloat(parts[1]), parseFloat(parts[2]), parseFloat(parts[3])]);
    } else if (tag === 'f') {
      const verts = parts.slice(1).map((token) => {
        const ts = token.split('/');
        const vi = parseInt(ts[0], 10);
        const vti = ts[1] ? parseInt(ts[1], 10) : undefined;
        const vni = ts[2] ? parseInt(ts[2], 10) : undefined;
        return { vi, vti, vni };
      });
      cur.faceRefs.push({ verts, materialName: curMaterial });
    } else if (tag === 'o' || tag === 'g') {
      const name = parts.slice(1).join(' ') || 'group';
      if (cur.faceRefs.length === 0) cur.name = name;
      else {
        cur = { name, faceRefs: [] };
        groups.push(cur);
      }
    } else if (tag === 'usemtl') {
      curMaterial = parts.slice(1).join(' ');
    } else if (tag === 'mtllib') {
      mtllibs.push(parts.slice(1).join(' '));
    }
  }
  return { positions, uvs, normals, groups, mtllibs };
}

/**
 * Import an OBJ source (+ optional MTL source) into a Scene.
 * Each `o`/`g` group becomes a MeshObject. Materials referenced via
 * usemtl are matched against the MTL definitions.
 */
export function importObj(objSrc: string, mtlSrc: string | null = null): ObjImportResult {
  const obj = parseObj(objSrc);
  const mtls = mtlSrc ? parseMtl(mtlSrc) : [];
  const scene = new Scene();
  const matsByName = new Map<string, Material>();
  for (const m of mtls) {
    const mat = new Material(m.name);
    if (m.Kd) mat.setBaseColor(m.Kd[0], m.Kd[1], m.Kd[2]);
    if (m.Ka) mat.ambient = { r: m.Ka[0], g: m.Ka[1], b: m.Ka[2] };
    if (m.Ks) mat.specular = { r: m.Ks[0], g: m.Ks[1], b: m.Ks[2] };
    if (m.Ns != null) mat.shininess = m.Ns;
    if (m.d != null) mat.opacity = m.d;
    scene.addMaterial(mat);
    matsByName.set(mat.name, mat);
  }
  const meshes: MeshObject[] = [];
  for (const group of obj.groups) {
    if (group.faceRefs.length === 0) continue;
    const node = new MeshObject(group.name);
    const mesh = new EditableMesh();
    // Local-to-global vertex remap.
    const vertMap = new Map<number, Id>();
    const getVert = (vi: number): Id => {
      let id = vertMap.get(vi);
      if (id != null) return id;
      // OBJ is 1-indexed.
      const pos = obj.positions[vi - 1];
      if (!pos) throw new Error(`Vertex index out of range: ${vi}`);
      const v = mesh.addVertex(pos[0], pos[1], pos[2]);
      vertMap.set(vi, v.id);
      return v.id;
    };
    let primaryMat: Id | null = null;
    for (const fr of group.faceRefs) {
      const seq: Id[] = fr.verts.map((v) => getVert(v.vi));
      // Dedupe consecutive matches.
      const dedup: Id[] = [];
      for (const id of seq) {
        if (id !== dedup[dedup.length - 1]) dedup.push(id);
      }
      if (dedup.length > 1 && dedup[0] === dedup[dedup.length - 1]) dedup.pop();
      if (dedup.length < 3) continue;
      const mat = fr.materialName ? matsByName.get(fr.materialName) : null;
      const face = mesh.addFace(dedup, mat ? mat.id : null);
      // Apply per-loop UVs / normals.
      const loops = mesh.faceLoops(face.id);
      for (let i = 0; i < loops.length; i++) {
        const ref = fr.verts[i];
        if (ref && ref.vti != null && obj.uvs[ref.vti - 1]) {
          loops[i].uv[0] = obj.uvs[ref.vti - 1][0];
          loops[i].uv[1] = obj.uvs[ref.vti - 1][1];
        }
        if (ref && ref.vni != null && obj.normals[ref.vni - 1]) {
          loops[i].normal[0] = obj.normals[ref.vni - 1][0];
          loops[i].normal[1] = obj.normals[ref.vni - 1][1];
          loops[i].normal[2] = obj.normals[ref.vni - 1][2];
        }
      }
      if (mat && !primaryMat) primaryMat = mat.id;
    }
    mesh.recomputeFaceNormals();
    node.mesh = mesh;
    node.materialId = primaryMat;
    scene.addNode(node);
    meshes.push(node);
  }
  return { scene, meshes, materials: scene.materials() as Material[] };
}

export interface ObjExportOptions {
  /** Optional MTL filename to reference in the OBJ (and to emit alongside). */
  mtlPath?: string;
  /** Include per-loop UVs? */
  includeUvs?: boolean;
  /** Include per-loop normals? */
  includeNormals?: boolean;
}

export interface ObjExportResult {
  obj: string;
  mtl: string | null;
}

/** Export every MeshObject in `scene` to a single OBJ + MTL string pair. */
export function exportObj(scene: Scene, opts: ObjExportOptions = {}): ObjExportResult {
  const lines: string[] = [];
  const matLines: string[] = [];
  const mats = scene.materials() as Material[];
  const matNameById = new Map<Id, string>();
  if (opts.mtlPath && mats.length > 0) lines.push(`mtllib ${opts.mtlPath}`);
  // Emit MTL block.
  for (const mat of mats) {
    matNameById.set(mat.id, mat.name);
    matLines.push(`newmtl ${mat.name}`);
    matLines.push(`Kd ${mat.baseColor.r.toFixed(6)} ${mat.baseColor.g.toFixed(6)} ${mat.baseColor.b.toFixed(6)}`);
    matLines.push(`Ka ${mat.ambient.r.toFixed(6)} ${mat.ambient.g.toFixed(6)} ${mat.ambient.b.toFixed(6)}`);
    matLines.push(`Ks ${mat.specular.r.toFixed(6)} ${mat.specular.g.toFixed(6)} ${mat.specular.b.toFixed(6)}`);
    matLines.push(`Ns ${mat.shininess.toFixed(4)}`);
    matLines.push(`d ${mat.opacity.toFixed(4)}`);
    if (mat.texture) matLines.push(`map_Kd ${mat.texture.name}`);
    matLines.push('');
  }
  // Emit each MeshObject as its own `o` group.
  // OBJ indices are 1-based and global across the file.
  let nextPosIdx = 1;
  let nextUvIdx = 1;
  let nextNormalIdx = 1;
  const includeUvs = opts.includeUvs ?? true;
  const includeNormals = opts.includeNormals ?? true;
  scene.forEachNode((n) => {
    if (n.kind !== 'mesh') return;
    const node = n as MeshObject;
    if (!node.mesh) return;
    lines.push(`o ${node.name}`);
    const m = node.mesh;
    // Vertex positions.
    const posMap = new Map<Id, number>();
    for (const v of m.vertices.values()) {
      lines.push(`v ${v.position[0].toFixed(6)} ${v.position[1].toFixed(6)} ${v.position[2].toFixed(6)}`);
      posMap.set(v.id, nextPosIdx);
      nextPosIdx++;
    }
    // Per-loop UVs.
    const uvMap = new Map<Id, number>();
    if (includeUvs) {
      for (const loop of m.loops.values()) {
        lines.push(`vt ${loop.uv[0].toFixed(6)} ${loop.uv[1].toFixed(6)}`);
        uvMap.set(loop.id, nextUvIdx);
        nextUvIdx++;
      }
    }
    // Per-loop normals (defer to face normals if loop normals are zero).
    const normMap = new Map<Id, number>();
    if (includeNormals) {
      for (const loop of m.loops.values()) {
        const f = m.faces.get(loop.faceId);
        const n2 = (loop.normal[0] !== 0 || loop.normal[1] !== 0 || loop.normal[2] !== 0)
          ? loop.normal
          : (f ? f.normal : [0, 0, 1]);
        lines.push(`vn ${n2[0].toFixed(6)} ${n2[1].toFixed(6)} ${n2[2].toFixed(6)}`);
        normMap.set(loop.id, nextNormalIdx);
        nextNormalIdx++;
      }
    }
    // Faces.
    if (node.materialId != null) {
      const matName = matNameById.get(node.materialId);
      if (matName) lines.push(`usemtl ${matName}`);
    }
    for (const face of m.faces.values()) {
      const tokens: string[] = [];
      for (const lid of face.loops) {
        const loop = m.loops.get(lid);
        if (!loop) continue;
        const vi = posMap.get(loop.vertexId)!;
        const vti = uvMap.get(lid);
        const vni = normMap.get(lid);
        if (vti != null && vni != null) tokens.push(`${vi}/${vti}/${vni}`);
        else if (vti != null) tokens.push(`${vi}/${vti}`);
        else if (vni != null) tokens.push(`${vi}//${vni}`);
        else tokens.push(`${vi}`);
      }
      lines.push(`f ${tokens.join(' ')}`);
    }
  });
  return { obj: lines.join('\n') + '\n', mtl: matLines.length > 0 ? matLines.join('\n') + '\n' : null };
}
