// Seam-aware unwrap + island packing.
//
// The unwrap algorithm is intentionally simple:
//   1. Group faces into islands using BFS over non-seam edges.
//   2. For each island, compute the average normal and project each face
//      vertex into a tangent plane (one 2D coord per loop).
//   3. Normalize each island's UVs to its own (0..1) bbox before packing.
//
// The packer is a row-based shelf packer — sufficient for "no overlap"
// guarantees on small fixtures.

import { EditableMesh } from './EditableMesh';
import type { Id } from '../core/Id';
import * as Vec3 from '../core/math/Vec3';

export interface UvIsland {
  faceIds: Id[];
  /** Per-loop UV (before packing). */
  uvByLoop: Map<Id, [number, number]>;
  /** Bounding box in local UV space (after normalization to 0..1). */
  bbox: { minU: number; minV: number; maxU: number; maxV: number };
}

function neighbours(mesh: EditableMesh, faceId: Id): Iterable<{ faceId: Id; edgeId: Id }> {
  const out: Array<{ faceId: Id; edgeId: Id }> = [];
  const face = mesh.faces.get(faceId);
  if (!face) return out;
  for (const lid of face.loops) {
    const loop = mesh.loops.get(lid);
    if (!loop) continue;
    const edge = mesh.edges.get(loop.edgeId);
    if (!edge) continue;
    for (const olid of edge.loops) {
      const ol = mesh.loops.get(olid);
      if (!ol) continue;
      if (ol.faceId === faceId) continue;
      out.push({ faceId: ol.faceId, edgeId: edge.id });
    }
  }
  return out;
}

/** Split faces into islands across seam edges. */
export function findIslands(mesh: EditableMesh): Id[][] {
  const visited = new Set<Id>();
  const islands: Id[][] = [];
  for (const startFid of mesh.faces.keys()) {
    if (visited.has(startFid)) continue;
    const island: Id[] = [];
    const queue: Id[] = [startFid];
    visited.add(startFid);
    while (queue.length > 0) {
      const cur = queue.shift()!;
      island.push(cur);
      for (const { faceId, edgeId } of neighbours(mesh, cur)) {
        if (visited.has(faceId)) continue;
        const e = mesh.edges.get(edgeId);
        if (!e || e.seam) continue; // Don't cross seams.
        visited.add(faceId);
        queue.push(faceId);
      }
    }
    islands.push(island);
  }
  return islands;
}

/** Project face vertices to 2D using the island's averaged normal as the plane normal. */
function projectIsland(mesh: EditableMesh, faceIds: Id[]): Map<Id, [number, number]> {
  // Average normal.
  const avg = Vec3.create();
  let count = 0;
  for (const fid of faceIds) {
    const f = mesh.faces.get(fid);
    if (!f) continue;
    Vec3.add(avg, avg, f.normal);
    count++;
  }
  if (count > 0) Vec3.scale(avg, avg, 1 / count);
  if (Vec3.length(avg) < 1e-6) {
    Vec3.set(avg, 0, 1, 0);
  } else {
    Vec3.normalize(avg, avg);
  }
  // Build a 2D basis (u, v) perpendicular to avg.
  const up = Math.abs(avg[1]) < 0.99 ? Vec3.fromValues(0, 1, 0) : Vec3.fromValues(1, 0, 0);
  const u = Vec3.create();
  Vec3.cross(u, up, avg);
  Vec3.normalize(u, u);
  const v = Vec3.create();
  Vec3.cross(v, avg, u);
  Vec3.normalize(v, v);
  // Project each loop's vertex onto (u, v).
  const out = new Map<Id, [number, number]>();
  for (const fid of faceIds) {
    const f = mesh.faces.get(fid);
    if (!f) continue;
    for (const lid of f.loops) {
      const loop = mesh.loops.get(lid);
      if (!loop) continue;
      const vert = mesh.vertices.get(loop.vertexId);
      if (!vert) continue;
      const pu = vert.position[0] * u[0] + vert.position[1] * u[1] + vert.position[2] * u[2];
      const pv = vert.position[0] * v[0] + vert.position[1] * v[1] + vert.position[2] * v[2];
      out.set(lid, [pu, pv]);
    }
  }
  return out;
}

/** Compute the (min, max) bbox of an island's UVs. */
function islandBounds(uvByLoop: Map<Id, [number, number]>): { minU: number; minV: number; maxU: number; maxV: number } {
  let minU = Infinity, minV = Infinity, maxU = -Infinity, maxV = -Infinity;
  for (const [u, v] of uvByLoop.values()) {
    if (u < minU) minU = u;
    if (v < minV) minV = v;
    if (u > maxU) maxU = u;
    if (v > maxV) maxV = v;
  }
  if (!isFinite(minU)) { minU = 0; maxU = 1; minV = 0; maxV = 1; }
  return { minU, minV, maxU, maxV };
}

/** Normalize an island's UVs into (0..1) without applying packing. */
function normalizeIsland(uvByLoop: Map<Id, [number, number]>): { bbox: ReturnType<typeof islandBounds> } {
  const bbox = islandBounds(uvByLoop);
  const du = bbox.maxU - bbox.minU || 1;
  const dv = bbox.maxV - bbox.minV || 1;
  for (const [lid, [u, v]] of uvByLoop) {
    uvByLoop.set(lid, [(u - bbox.minU) / du, (v - bbox.minV) / dv]);
  }
  return { bbox: { minU: 0, minV: 0, maxU: 1, maxV: 1 } };
}

/** Unwrap every island in `mesh` and store the result per loop. */
export function unwrap(mesh: EditableMesh): UvIsland[] {
  mesh.recomputeFaceNormals();
  const islandIds = findIslands(mesh);
  const islands: UvIsland[] = [];
  for (const faceIds of islandIds) {
    const uvByLoop = projectIsland(mesh, faceIds);
    normalizeIsland(uvByLoop);
    islands.push({ faceIds, uvByLoop, bbox: { minU: 0, minV: 0, maxU: 1, maxV: 1 } });
  }
  return islands;
}

/**
 * Pack islands into the (0..1)×(0..1) UV square. Each island is given a
 * cell of `cellSize × cellSize`. We use a row-based grid where each cell
 * holds one island, scaled to fit inside.
 *
 * No-overlap is guaranteed by the grid layout.
 */
export function packIslands(islands: UvIsland[], padding = 0.01): void {
  const n = islands.length;
  if (n === 0) return;
  const cols = Math.ceil(Math.sqrt(n));
  const rows = Math.ceil(n / cols);
  const cellW = (1 - padding * (cols + 1)) / cols;
  const cellH = (1 - padding * (rows + 1)) / rows;
  for (let i = 0; i < n; i++) {
    const col = i % cols;
    const row = Math.floor(i / cols);
    const offsetU = padding + col * (cellW + padding);
    const offsetV = padding + row * (cellH + padding);
    const island = islands[i];
    for (const [lid, [u, v]] of island.uvByLoop) {
      island.uvByLoop.set(lid, [offsetU + u * cellW, offsetV + v * cellH]);
    }
    island.bbox = { minU: offsetU, minV: offsetV, maxU: offsetU + cellW, maxV: offsetV + cellH };
  }
}

/** Apply island UVs to the mesh in place. */
export function applyUvIslands(mesh: EditableMesh, islands: UvIsland[]): void {
  for (const island of islands) {
    for (const [lid, [u, v]] of island.uvByLoop) {
      const loop = mesh.loops.get(lid);
      if (!loop) continue;
      loop.uv[0] = u;
      loop.uv[1] = v;
    }
  }
}

/** Convenience: run unwrap + pack + apply in one shot. */
export function autoUnwrapAndPack(mesh: EditableMesh, padding = 0.01): UvIsland[] {
  const islands = unwrap(mesh);
  packIslands(islands, padding);
  applyUvIslands(mesh, islands);
  return islands;
}
