// Cube primitive: 8 verts, 12 edges, 6 quad faces.

import { EditableMesh } from '../EditableMesh';

export interface CubeParams {
  size?: number; // edge length, default 2
}

export function buildCube(params: CubeParams = {}): EditableMesh {
  const s = (params.size ?? 2) * 0.5;
  const m = new EditableMesh();
  // 8 corners.
  const v000 = m.addVertex(-s, -s, -s).id;
  const v100 = m.addVertex(s, -s, -s).id;
  const v110 = m.addVertex(s, s, -s).id;
  const v010 = m.addVertex(-s, s, -s).id;
  const v001 = m.addVertex(-s, -s, s).id;
  const v101 = m.addVertex(s, -s, s).id;
  const v111 = m.addVertex(s, s, s).id;
  const v011 = m.addVertex(-s, s, s).id;
  // 6 faces, CCW from outside.
  const faces = [
    m.addFace([v001, v101, v111, v011]).id, // +Z front
    m.addFace([v100, v000, v010, v110]).id, // -Z back
    m.addFace([v000, v001, v011, v010]).id, // -X left
    m.addFace([v101, v100, v110, v111]).id, // +X right
    m.addFace([v011, v111, v110, v010]).id, // +Y top
    m.addFace([v001, v000, v100, v101]).id, // -Y bottom
  ];
  // Per-corner UVs: each face mapped to its own 0..1 quad.
  for (const fid of faces) {
    const loops = m.faceLoops(fid);
    const uvs: Array<[number, number]> = [[0, 0], [1, 0], [1, 1], [0, 1]];
    for (let i = 0; i < loops.length; i++) {
      loops[i].uv[0] = uvs[i][0];
      loops[i].uv[1] = uvs[i][1];
    }
  }
  m.recomputeFaceNormals();
  return m;
}
