// Screen-space strip rendering — used by wire overlays, selection outlines,
// and gizmo lines. Each line segment expands in the vertex shader to a
// fixed pixel-width quad, so width stays constant across DPR and zoom.
//
// We avoid GL_LINES entirely (idea.md hard constraint).

import { ShaderProgram } from './ShaderProgram';
import type { Camera } from './Camera';

const FLOATS_PER_VERT = 9; // aPosA(3) + aPosB(3) + aOffset(2) + aColor(1)
const VERTS_PER_SEG = 4;
const INDICES_PER_SEG = 6;

const VERT = `#version 300 es
precision highp float;
layout(location=0) in vec3 aPosA;
layout(location=1) in vec3 aPosB;
layout(location=2) in vec2 aOffset; // (side ±1, t in [0..1])
layout(location=3) in float aColorPacked;
uniform mat4 uViewProj;
uniform vec2 uPixelSize;
uniform float uWidth;
out vec3 vColor;

vec3 unpackColor(float p) {
  float r = floor(p / (256.0 * 256.0));
  float g = floor(mod(p / 256.0, 256.0));
  float b = mod(p, 256.0);
  return vec3(r, g, b) / 255.0;
}

void main() {
  vec4 clipA = uViewProj * vec4(aPosA, 1.0);
  vec4 clipB = uViewProj * vec4(aPosB, 1.0);
  // Compute direction in NDC.
  vec2 ndcA = clipA.xy / max(abs(clipA.w), 1e-4);
  vec2 ndcB = clipB.xy / max(abs(clipB.w), 1e-4);
  vec2 d = ndcB - ndcA;
  if (length(d) < 1e-6) d = vec2(1.0, 0.0);
  vec2 dir = normalize(d);
  vec2 perp = vec2(-dir.y, dir.x);
  vec4 clip = mix(clipA, clipB, aOffset.y);
  vec2 offsetNdc = perp * uWidth * uPixelSize * aOffset.x;
  clip.xy += offsetNdc * clip.w;
  vColor = unpackColor(aColorPacked);
  gl_Position = clip;
}`;

const FRAG = `#version 300 es
precision highp float;
in vec3 vColor;
uniform float uAlpha;
out vec4 fragColor;
void main() {
  fragColor = vec4(vColor, uAlpha);
}`;

interface Segment {
  ax: number; ay: number; az: number;
  bx: number; by: number; bz: number;
  color: number; // packed r*256² + g*256 + b
}

export class StripBatch {
  width = 1.5;
  alpha = 1.0;
  private segs: Segment[] = [];
  private gpu: { vao: WebGLVertexArrayObject; vbo: WebGLBuffer; ebo: WebGLBuffer; capacity: number } | null = null;
  private program: ShaderProgram;
  private readonly gl: WebGL2RenderingContext;

  constructor(gl: WebGL2RenderingContext) {
    this.gl = gl;
    this.program = new ShaderProgram(gl, VERT, FRAG);
  }

  reset(): void {
    this.segs.length = 0;
  }

  add(ax: number, ay: number, az: number, bx: number, by: number, bz: number, r = 0.85, g = 0.85, b = 0.85): void {
    const cr = Math.round(Math.max(0, Math.min(1, r)) * 255);
    const cg = Math.round(Math.max(0, Math.min(1, g)) * 255);
    const cb = Math.round(Math.max(0, Math.min(1, b)) * 255);
    this.segs.push({ ax, ay, az, bx, by, bz, color: cr * 65536 + cg * 256 + cb });
  }

  segmentCount(): number {
    return this.segs.length;
  }

  /** Build CPU vertex+index data for the current segment list. Returns the raw buffers (exposed for tests). */
  buildBuffers(): { vertices: Float32Array; indices: Uint32Array } {
    const n = this.segs.length;
    const vertices = new Float32Array(n * VERTS_PER_SEG * FLOATS_PER_VERT);
    const indices = new Uint32Array(n * INDICES_PER_SEG);
    // Offset table: 4 vertices per segment.
    const offsets = [
      { side: -1, t: 0 },
      { side: 1, t: 0 },
      { side: -1, t: 1 },
      { side: 1, t: 1 },
    ];
    let vp = 0;
    let ip = 0;
    for (let s = 0; s < n; s++) {
      const seg = this.segs[s];
      const base = s * VERTS_PER_SEG;
      for (let k = 0; k < VERTS_PER_SEG; k++) {
        const o = offsets[k];
        vertices[vp++] = seg.ax;
        vertices[vp++] = seg.ay;
        vertices[vp++] = seg.az;
        vertices[vp++] = seg.bx;
        vertices[vp++] = seg.by;
        vertices[vp++] = seg.bz;
        vertices[vp++] = o.side;
        vertices[vp++] = o.t;
        vertices[vp++] = seg.color;
      }
      indices[ip++] = base + 0;
      indices[ip++] = base + 1;
      indices[ip++] = base + 2;
      indices[ip++] = base + 1;
      indices[ip++] = base + 3;
      indices[ip++] = base + 2;
    }
    return { vertices, indices };
  }

  draw(camera: Camera, aspect: number, viewportPxW: number, viewportPxH: number): void {
    const { gl } = this;
    if (this.segs.length === 0) return;
    const { vertices, indices } = this.buildBuffers();
    this.ensureGpu(vertices.byteLength, indices.byteLength);
    gl.bindVertexArray(this.gpu!.vao);
    gl.bindBuffer(gl.ARRAY_BUFFER, this.gpu!.vbo);
    gl.bufferSubData(gl.ARRAY_BUFFER, 0, vertices);
    gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, this.gpu!.ebo);
    gl.bufferSubData(gl.ELEMENT_ARRAY_BUFFER, 0, indices);

    this.program.use();
    this.program.setMat4('uViewProj', camera.viewProj(aspect) as Float32Array);
    const pxW = 2 / Math.max(1, viewportPxW);
    const pxH = 2 / Math.max(1, viewportPxH);
    const loc = this.program.loc('uPixelSize');
    if (loc) gl.uniform2f(loc, pxW, pxH);
    this.program.setFloat('uWidth', this.width * 0.5); // half-width per side
    this.program.setFloat('uAlpha', this.alpha);

    gl.enable(gl.BLEND);
    gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);
    gl.depthMask(false);
    gl.drawElements(gl.TRIANGLES, indices.length, gl.UNSIGNED_INT, 0);
    gl.depthMask(true);
    gl.disable(gl.BLEND);
    gl.bindVertexArray(null);
  }

  private ensureGpu(vBytes: number, iBytes: number): void {
    const { gl } = this;
    if (!this.gpu || this.gpu.capacity < Math.max(vBytes, iBytes)) {
      this.disposeGpu();
      const vao = gl.createVertexArray()!;
      const vbo = gl.createBuffer()!;
      const ebo = gl.createBuffer()!;
      gl.bindVertexArray(vao);
      gl.bindBuffer(gl.ARRAY_BUFFER, vbo);
      gl.bufferData(gl.ARRAY_BUFFER, Math.max(vBytes, 1024 * 16), gl.DYNAMIC_DRAW);
      const stride = FLOATS_PER_VERT * 4;
      gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0, 3, gl.FLOAT, false, stride, 0);
      gl.enableVertexAttribArray(1); gl.vertexAttribPointer(1, 3, gl.FLOAT, false, stride, 12);
      gl.enableVertexAttribArray(2); gl.vertexAttribPointer(2, 2, gl.FLOAT, false, stride, 24);
      gl.enableVertexAttribArray(3); gl.vertexAttribPointer(3, 1, gl.FLOAT, false, stride, 32);
      gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, ebo);
      gl.bufferData(gl.ELEMENT_ARRAY_BUFFER, Math.max(iBytes, 1024 * 4), gl.DYNAMIC_DRAW);
      gl.bindVertexArray(null);
      this.gpu = { vao, vbo, ebo, capacity: Math.max(vBytes, iBytes) };
    }
  }

  private disposeGpu(): void {
    if (!this.gpu) return;
    const { gl } = this;
    gl.deleteVertexArray(this.gpu.vao);
    gl.deleteBuffer(this.gpu.vbo);
    gl.deleteBuffer(this.gpu.ebo);
    this.gpu = null;
  }

  dispose(): void {
    this.disposeGpu();
    this.program.dispose();
  }
}
