// UiRoot — orchestrates the Gwen-based editor shell.
//
// Layout (matches notes/gwen-integration.md §4):
//   ┌─────────────────────────────────────────────────────────┐
//   │ MenuStrip (top)                                          │
//   ├─────────────────────────────────────────────────────────┤
//   │ ActionBar horizontal (top)                               │
//   ├──────┬───────────────────────────────┬──────────────────┤
//   │ Tool │ ViewportHost (fill, DockBase) │ Outliner /       │
//   │ Pal- │ — 3D pass paints here         │ Inspector /      │
//   │ ette │                               │ Materials /      │
//   │      │                               │ History /        │
//   │      │                               │ Export tabs      │
//   ├──────┴───────────────────────────────┴──────────────────┤
//   │ StatusBar (bottom)                                       │
//   └─────────────────────────────────────────────────────────┘
//
// Item 4 deliverable: every region is present as a Gwen control, the
// viewport host occupies the fill, and the shell exposes debug refs that
// Playwright can poll.

import { ViewportHost } from './ViewportHost';
import { buildTopMenu, type TopMenuRefs } from './TopMenu';
import { buildToolShelf, type ToolShelfRefs } from './ToolShelf';
import { buildActionBar, type ActionBarRefs } from './ActionBar';
import { buildFooter, type FooterRefs } from './Footer';
import { buildRightDock, type RightDockRefs } from './RightDock';
import { buildViewWidget, type ViewWidgetRefs } from './ViewWidget';

export interface UiRefs {
  menu: TopMenuRefs;
  toolShelf: ToolShelfRefs;
  actionBar: ActionBarRefs;
  rightDock: RightDockRefs;
  footer: FooterRefs;
  viewport: ViewportHost;
  viewWidget: ViewWidgetRefs;
  applyResponsiveLayout(): void;
}

const TOP_MENU_HEIGHT = 24;
const ACTION_BAR_HEIGHT = 30;
const FOOTER_HEIGHT = 22;
const TOOL_SHELF_WIDTH = 44;
const RIGHT_DOCK_WIDTH = 260;
const RIGHT_DOCK_MIN = 120;

function clampRightDockWidth(canvasW: number): number {
  // Leave ≥ 50% of the remaining width (after the toolshelf) for the viewport.
  const remaining = Math.max(0, canvasW - TOOL_SHELF_WIDTH);
  const cap = Math.floor(remaining * 0.5);
  return Math.max(RIGHT_DOCK_MIN, Math.min(RIGHT_DOCK_WIDTH, cap));
}

export function buildUi(canvas: Gwen.Canvas): UiRefs {
  // Top menu (file/edit/view/...).
  const menu = buildTopMenu(canvas);
  menu.strip.dock(Gwen.Pos.Top);
  menu.strip.setHeight(TOP_MENU_HEIGHT);

  // Footer (status bar) docked Bottom early so it claims its row first.
  const footer = buildFooter(canvas);
  footer.bar.dock(Gwen.Pos.Bottom);
  footer.bar.setHeight(FOOTER_HEIGHT);

  // Top action bar docks Top (below the menu strip).
  const actionBar = buildActionBar(canvas);
  actionBar.bar.dock(Gwen.Pos.Top);
  actionBar.bar.setHeight(ACTION_BAR_HEIGHT);

  // Left tool palette docks Left.
  const toolShelf = buildToolShelf(canvas);
  toolShelf.bar.dock(Gwen.Pos.Left);
  toolShelf.bar.setWidth(TOOL_SHELF_WIDTH);

  // Right dock with tabs.
  const dock = new Gwen.DockBase(canvas);
  dock.dock(Gwen.Pos.Fill);
  const right = dock.getRight();
  right.setWidth(clampRightDockWidth(canvas.width()));
  const rightDock = buildRightDock(right);

  // Central viewport host inside the dock's fill.
  const viewport = new ViewportHost(dock);
  viewport.dock(Gwen.Pos.Fill);

  // Floating view widget pinned to the viewport's upper-right corner.
  const viewWidget = buildViewWidget(viewport);
  viewWidget.bar.setBounds(0, 0, 7 * 22, 22);
  const positionWidget = (): void => {
    const b = viewport.getBounds();
    viewWidget.bar.setPos(Math.max(0, b.w - viewWidget.bar.width() - 6), 6);
  };
  positionWidget();

  return {
    menu,
    toolShelf,
    actionBar,
    rightDock,
    footer,
    viewport,
    viewWidget,
    applyResponsiveLayout(): void {
      right.setWidth(clampRightDockWidth(canvas.width()));
      positionWidget();
    },
  };
}
