// BMesh-style topology records used by EditableMesh.

import * as Vec2 from '../core/math/Vec2';
import * as Vec3 from '../core/math/Vec3';
import type { Id } from '../core/Id';

export interface Vertex {
  id: Id;
  position: Vec3.Vec3;
  normal: Vec3.Vec3;
  /** Edge ids that include this vertex. Order is unspecified. */
  edges: Id[];
}

export interface Edge {
  id: Id;
  a: Id;
  b: Id;
  /** Loops that traverse this edge (in either direction). Length > 2 ⇒ non-manifold. */
  loops: Id[];
  hard: boolean;
  seam: boolean;
}

export interface Loop {
  id: Id;
  faceId: Id;
  edgeId: Id;
  /**
   * "Start" vertex of this loop's directed edge. Within the face, the next
   * loop's vertex is this loop's other edge endpoint.
   */
  vertexId: Id;
  uv: Vec2.Vec2;
  /** Per-corner normal — diverges across hard edges. */
  normal: Vec3.Vec3;
}

export interface Face {
  id: Id;
  /** Ordered loop ids forming the face boundary (CCW from front). */
  loops: Id[];
  normal: Vec3.Vec3;
  materialId: Id | null;
}

export function makeVertex(id: Id, x: number, y: number, z: number): Vertex {
  return { id, position: Vec3.fromValues(x, y, z), normal: Vec3.fromValues(0, 0, 0), edges: [] };
}

export function makeEdge(id: Id, a: Id, b: Id): Edge {
  return { id, a, b, loops: [], hard: false, seam: false };
}

export function makeLoop(id: Id, faceId: Id, edgeId: Id, vertexId: Id): Loop {
  return { id, faceId, edgeId, vertexId, uv: Vec2.create(), normal: Vec3.create() };
}

export function makeFace(id: Id): Face {
  return { id, loops: [], normal: Vec3.create(), materialId: null };
}
