// ViewportHost — Base subclass that occupies the central area inside the
// DockBase fill. It captures viewport pointer events (for camera/tools/
// gizmos in later items) and reports its render bounds so the 3D pass
// knows where to render. The 3D pass renders before Gwen, and the
// viewport area is left transparent in Gwen so the 3D pixels show through.

export interface ViewportInputDelegate {
  pointerDown?(button: number, x: number, y: number): void;
  pointerMove?(x: number, y: number, dx: number, dy: number): void;
  pointerUp?(button: number, x: number, y: number): void;
  wheel?(delta: number, x: number, y: number): boolean;
}

export class ViewportHost extends Gwen.Base {
  delegate: ViewportInputDelegate | null = null;
  private _lastPointer: { x: number; y: number } = { x: 0, y: 0 };

  constructor(parent: Gwen.Base | null) {
    super(parent);
    this.setMouseInputEnabled(true);
    this.setKeyboardInputEnabled(true);
    this.setShouldDrawBackground(false);
  }

  /** Bounds of the viewport area in CSS pixels (logical coords). */
  getViewportRect(): { x: number; y: number; w: number; h: number } {
    const b = this.getBounds();
    return { x: b.x, y: b.y, w: b.w, h: b.h };
  }

  override render(_skin: Gwen.Skin): void {
    // No-op. The 3D pass paints inside our bounds; Gwen leaves it alone.
  }

  override onMouseClickLeft(x: number, y: number, pressed: boolean): void {
    this._lastPointer = { x, y };
    if (pressed) this.delegate?.pointerDown?.(0, x, y);
    else this.delegate?.pointerUp?.(0, x, y);
  }

  override onMouseClickRight(x: number, y: number, pressed: boolean): void {
    this._lastPointer = { x, y };
    if (pressed) this.delegate?.pointerDown?.(2, x, y);
    else this.delegate?.pointerUp?.(2, x, y);
  }

  /**
   * Gwen does not expose a built-in middle-click hook on `Base`. Synthesize
   * one by overriding the lower-level `onMouseClick` if Gwen routes it, or
   * accept that middle-click is handled via the canvas-level input fanout.
   * To make middle work we expose a manual entry point that App wires from
   * Gwen's canvas-level input fanout in App.ts.
   */
  injectMiddleClick(x: number, y: number, pressed: boolean): void {
    this._lastPointer = { x, y };
    if (pressed) this.delegate?.pointerDown?.(1, x, y);
    else this.delegate?.pointerUp?.(1, x, y);
  }

  override onMouseMoved(x: number, y: number, dx: number, dy: number): void {
    this._lastPointer = { x, y };
    this.delegate?.pointerMove?.(x, y, dx, dy);
  }

  override onMouseWheeled(delta: number): boolean {
    return this.delegate?.wheel?.(delta, this._lastPointer.x, this._lastPointer.y) ?? false;
  }

  /** Convert a canvas-space point to a coordinate relative to this host. */
  canvasToLocal(cx: number, cy: number): { x: number; y: number } {
    let dx = 0, dy = 0;
    let node: Gwen.Base | null = this;
    while (node) {
      const b = node.getBounds();
      dx += b.x;
      dy += b.y;
      node = node.parent;
    }
    return { x: cx - dx, y: cy - dy };
  }
}
