// Face-mode operations: data tests with topology validation.

import { defineTest, assert, assertEquals } from '../harness';
import { buildCube } from './primitives/Cube';
import { buildPlane } from './primitives/Plane';
import { EditableMesh } from './EditableMesh';
import {
  translateFaces,
  rotateFaces,
  scaleFaces,
  extrudeFaces,
  insetFaces,
  pokeFaces,
  triangulateFaces,
  deleteFaces,
  separateFaces,
} from './OperationsFace';
import type { Id } from '../core/Id';

const SUITE = 'faceOps';

function topologyOk(m: EditableMesh): boolean {
  const r = m.validate();
  if (r.ok) return true;
  return r.errors.every((e) => !e.includes('loose vertex'));
}

defineTest(SUITE, 'translate faces moves face verts', () => {
  const m = buildCube();
  const fid = Array.from(m.faces.keys())[0];
  const f = m.faces.get(fid)!;
  const vid = m.loops.get(f.loops[0])!.vertexId;
  const before = [...m.vertices.get(vid)!.position];
  translateFaces(m, [fid], 1, 2, 3);
  const after = m.vertices.get(vid)!.position;
  assert(Math.abs(after[0] - before[0] - 1) < 1e-6);
  assert(Math.abs(after[1] - before[1] - 2) < 1e-6);
  assert(Math.abs(after[2] - before[2] - 3) < 1e-6);
  assert(topologyOk(m));
});

defineTest(SUITE, 'rotate faces around Y rotates each face vert', () => {
  const m = buildCube();
  const fid = Array.from(m.faces.keys())[0];
  const f = m.faces.get(fid)!;
  const vid = m.loops.get(f.loops[0])!.vertexId;
  const before = [...m.vertices.get(vid)!.position];
  rotateFaces(m, [fid], 'y', Math.PI / 2);
  const after = m.vertices.get(vid)!.position;
  assert(Math.abs(after[0] - before[2]) < 1e-5);
  assert(topologyOk(m));
});

defineTest(SUITE, 'scale faces scales each face vert', () => {
  const m = buildCube();
  const fid = Array.from(m.faces.keys())[0];
  const f = m.faces.get(fid)!;
  const vid = m.loops.get(f.loops[0])!.vertexId;
  const before = [...m.vertices.get(vid)!.position];
  scaleFaces(m, [fid], 2, 2, 2);
  const after = m.vertices.get(vid)!.position;
  assert(Math.abs(after[0] - before[0] * 2) < 1e-5);
});

defineTest(SUITE, 'extrudeFaces adds 4 side quads + 1 cap on a cube face', () => {
  const m = buildCube();
  const fid = Array.from(m.faces.keys())[0];
  const beforeVerts = m.vertexCount();
  const beforeFaces = m.faceCount();
  const caps = extrudeFaces(m, [fid]);
  assert(caps.length === 1);
  assert(m.vertexCount() === beforeVerts + 4);
  // Cube face had 4 corners → 4 duplicates + 4 side quads + 1 cap - 1 original = +4 faces
  assert(m.faceCount() === beforeFaces + 4);
  assert(topologyOk(m));
});

defineTest(SUITE, 'insetFaces shrinks a face inward and adds side quads', () => {
  const m = buildCube();
  const fid = Array.from(m.faces.keys())[0];
  const beforeFaces = m.faceCount();
  const caps = insetFaces(m, [fid], 0.1);
  assert(caps.length === 1);
  // Original face was 1 quad → cap (1) + 4 sides = 5 new faces, minus original = +4.
  assert(m.faceCount() === beforeFaces + 4);
  assert(topologyOk(m));
});

defineTest(SUITE, 'pokeFaces fans a quad into 4 triangles', () => {
  const m = buildPlane({ segmentsX: 1, segmentsZ: 1 });
  const fid = Array.from(m.faces.keys())[0];
  const beforeFaces = m.faceCount();
  const centers = pokeFaces(m, [fid]);
  assertEquals(centers.length, 1);
  // 1 quad → 4 tris.
  assertEquals(m.faceCount(), beforeFaces + 3);
  assert(topologyOk(m));
});

defineTest(SUITE, 'triangulateFaces splits an n-gon into n-2 triangles', () => {
  // Build a hexagon.
  const m = new EditableMesh();
  const ids: Id[] = [];
  for (let i = 0; i < 6; i++) {
    const a = (i / 6) * Math.PI * 2;
    ids.push(m.addVertex(Math.cos(a), 0, Math.sin(a)).id);
  }
  m.addFace(ids);
  const before = m.faceCount();
  const fid = Array.from(m.faces.keys())[0];
  triangulateFaces(m, [fid]);
  assertEquals(m.faceCount(), before + 3); // 6-2 = 4 tris -1 hex = +3
});

defineTest(SUITE, 'deleteFaces removes face but keeps loose verts cleaned up', () => {
  const m = buildCube();
  const ids = Array.from(m.faces.keys()).slice(0, 1);
  const before = m.faceCount();
  deleteFaces(m, ids);
  assertEquals(m.faceCount(), before - 1);
});

defineTest(SUITE, 'separateFaces moves selected faces into a new mesh', () => {
  const m = buildCube();
  const before = m.faceCount();
  const ids = Array.from(m.faces.keys()).slice(0, 2);
  const out = separateFaces(m, ids);
  assertEquals(m.faceCount(), before - 2);
  assertEquals(out.faceCount(), 2);
  assert(topologyOk(out));
});
