// Reference image plane renderer. Draws a textured quad in world space
// per ReferenceImage node, with alpha blending controlled by `opacity`.

import { ShaderProgram } from './ShaderProgram';
import { GpuMesh } from './Buffers';
import type { Camera } from './Camera';
import type { ReferenceImage } from '../scene/ReferenceImage';
import * as Mat4 from '../core/math/Mat4';
import type { Id } from '../core/Id';

const VERT = `#version 300 es
precision highp float;
layout(location=0) in vec3 aPos;
layout(location=1) in vec2 aUv;
uniform mat4 uModel;
uniform mat4 uViewProj;
out vec2 vUv;
void main() {
  vUv = aUv;
  gl_Position = uViewProj * uModel * vec4(aPos, 1.0);
}`;

const FRAG = `#version 300 es
precision highp float;
in vec2 vUv;
uniform sampler2D uTex;
uniform float uOpacity;
out vec4 fragColor;
void main() {
  vec4 t = texture(uTex, vUv);
  fragColor = vec4(t.rgb, t.a * uOpacity);
}`;

interface TexSlot { tex: WebGLTexture; version: number }

export class ReferenceImageRenderer {
  readonly gl: WebGL2RenderingContext;
  private program: ShaderProgram;
  private quad: GpuMesh;
  private texCache = new Map<Id, TexSlot>();
  private fallback: WebGLTexture | null = null;

  constructor(gl: WebGL2RenderingContext) {
    this.gl = gl;
    this.program = new ShaderProgram(gl, VERT, FRAG);
    this.quad = new GpuMesh(gl);
    // Quad in the XY plane, centered at origin, +X right, +Y up.
    this.quad.uploadAttributes([
      { attribIndex: 0, componentsPerVertex: 3, data: new Float32Array([-0.5, -0.5, 0, 0.5, -0.5, 0, 0.5, 0.5, 0, -0.5, 0.5, 0]) },
      { attribIndex: 1, componentsPerVertex: 2, data: new Float32Array([0, 0, 1, 0, 1, 1, 0, 1]) },
    ]);
    this.quad.uploadIndices(new Uint32Array([0, 1, 2, 0, 2, 3]));
  }

  private ensureTexture(ref: ReferenceImage): WebGLTexture | null {
    if (!ref.pixels || !ref.pixels.data) return null;
    let slot = this.texCache.get(ref.id);
    if (!slot) {
      const tex = this.gl.createTexture();
      if (!tex) return null;
      slot = { tex, version: -1 };
      this.texCache.set(ref.id, slot);
    }
    if (slot.version !== ref.pixelVersion) {
      const { gl } = this;
      gl.bindTexture(gl.TEXTURE_2D, slot.tex);
      gl.pixelStorei(gl.UNPACK_ALIGNMENT, 1);
      gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, ref.pixels.width, ref.pixels.height, 0, gl.RGBA, gl.UNSIGNED_BYTE, ref.pixels.data);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
      slot.version = ref.pixelVersion;
    }
    return slot.tex;
  }

  private ensureFallback(): WebGLTexture {
    if (this.fallback) return this.fallback;
    const { gl } = this;
    const tex = gl.createTexture()!;
    gl.bindTexture(gl.TEXTURE_2D, tex);
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, 1, 1, 0, gl.RGBA, gl.UNSIGNED_BYTE, new Uint8Array([200, 200, 220, 200]));
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST);
    this.fallback = tex;
    return tex;
  }

  draw(ref: ReferenceImage, camera: Camera, aspect: number): void {
    if (!ref.isEffectivelyVisible()) return;
    const { gl } = this;
    this.program.use();
    // Scale model matrix by the image's width / height.
    const scaled = Mat4.create();
    Mat4.copy(scaled, ref.getWorldMatrix());
    // Apply local size: pre-multiply by a scale matrix.
    const sx = ref.width;
    const sy = ref.height;
    // Apply on the right side: world = parentWorld * local * scale.
    // We don't want to mutate the cached world matrix, so produce a fresh one.
    const local = Mat4.create();
    Mat4.identity(local);
    local[0] = sx;
    local[5] = sy;
    const final = Mat4.create();
    Mat4.multiply(final, ref.getWorldMatrix(), local);
    this.program.setMat4('uModel', final as Float32Array);
    this.program.setMat4('uViewProj', camera.viewProj(aspect) as Float32Array);
    this.program.setFloat('uOpacity', ref.opacity);
    gl.activeTexture(gl.TEXTURE0);
    const tex = this.ensureTexture(ref) ?? this.ensureFallback();
    gl.bindTexture(gl.TEXTURE_2D, tex);
    const loc = this.program.loc('uTex');
    if (loc) gl.uniform1i(loc, 0);
    gl.enable(gl.BLEND);
    gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);
    gl.depthMask(false);
    this.quad.drawTriangles();
    gl.depthMask(true);
    gl.disable(gl.BLEND);
  }

  dispose(): void {
    const { gl } = this;
    this.program.dispose();
    this.quad.dispose();
    for (const slot of this.texCache.values()) gl.deleteTexture(slot.tex);
    this.texCache.clear();
    if (this.fallback) gl.deleteTexture(this.fallback);
    this.fallback = null;
  }
}
