// Material — object-level material (per idea.md). OBJ-compatible MTL fields
// kept simple: base color, opacity, ambient, diffuse, specular, shininess,
// optional texture image. No PBR.

import { nextId, type Id } from '../core/Id';

export interface RGB {
  r: number; // 0..1
  g: number;
  b: number;
}

export interface MaterialTextureImage {
  name: string;
  width: number;
  height: number;
  data: Uint8Array | null; // RGBA8; null while pending upload
}

export class Material {
  readonly id: Id;
  name: string;
  baseColor: RGB = { r: 0.78, g: 0.78, b: 0.78 };
  opacity = 1.0;
  ambient: RGB = { r: 0.2, g: 0.2, b: 0.2 };
  diffuse: RGB = { r: 0.78, g: 0.78, b: 0.78 };
  specular: RGB = { r: 0.05, g: 0.05, b: 0.05 };
  shininess = 16;
  texture: MaterialTextureImage | null = null;
  /** Bumped each time the texture image changes; used by the renderer to detect re-uploads. */
  textureVersion = 0;

  constructor(name = 'Material') {
    this.id = nextId();
    this.name = name;
  }

  setBaseColor(r: number, g: number, b: number): void {
    this.baseColor = { r, g, b };
    this.diffuse = { r, g, b };
  }

  setTexture(tex: MaterialTextureImage | null): void {
    this.texture = tex;
    this.textureVersion++;
  }

  /** Plain-object snapshot suitable for OBJ/MTL or JSON export. */
  serialize(): {
    name: string;
    baseColor: RGB;
    opacity: number;
    ambient: RGB;
    diffuse: RGB;
    specular: RGB;
    shininess: number;
    texture: { name: string; width: number; height: number } | null;
  } {
    return {
      name: this.name,
      baseColor: { ...this.baseColor },
      opacity: this.opacity,
      ambient: { ...this.ambient },
      diffuse: { ...this.diffuse },
      specular: { ...this.specular },
      shininess: this.shininess,
      texture: this.texture ? { name: this.texture.name, width: this.texture.width, height: this.texture.height } : null,
    };
  }

  static createDefaultGray(name = 'Mat_Gray'): Material {
    return new Material(name);
  }
}
