// Create a primitive MeshObject and add it to the scene root. The command
// re-builds the mesh on redo/replaceTop using the current params, so the
// action bar can swap parameters in place.

import type { Command } from '../Commands';
import { MeshObject } from '../../scene/MeshObject';
import type { Scene } from '../../scene/Scene';
import {
  buildCube, buildPlane, buildCylinder, buildCone,
  buildDisk, buildUvSphere, buildIcoSphere, buildTorus,
  type CubeParams, type PlaneParams, type CylinderParams, type ConeParams,
  type DiskParams, type UvSphereParams, type IcoSphereParams, type TorusParams,
} from '../../mesh/primitives';

export type PrimitiveKind = 'cube' | 'plane' | 'cylinder' | 'cone' | 'disk' | 'uvsphere' | 'icosphere' | 'torus';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export type PrimitiveParams = CubeParams | PlaneParams | CylinderParams | ConeParams | DiskParams | UvSphereParams | IcoSphereParams | TorusParams | Record<string, any>;

function buildMesh(kind: PrimitiveKind, params: PrimitiveParams): import('../../mesh/EditableMesh').EditableMesh {
  switch (kind) {
    case 'cube': return buildCube(params as CubeParams);
    case 'plane': return buildPlane(params as PlaneParams);
    case 'cylinder': return buildCylinder(params as CylinderParams);
    case 'cone': return buildCone(params as ConeParams);
    case 'disk': return buildDisk(params as DiskParams);
    case 'uvsphere': return buildUvSphere(params as UvSphereParams);
    case 'icosphere': return buildIcoSphere(params as IcoSphereParams);
    case 'torus': return buildTorus(params as TorusParams);
  }
}

const DEFAULT_NAME: Record<PrimitiveKind, string> = {
  cube: 'Cube',
  plane: 'Plane',
  cylinder: 'Cylinder',
  cone: 'Cone',
  disk: 'Disk',
  uvsphere: 'UV Sphere',
  icosphere: 'Ico Sphere',
  torus: 'Torus',
};

export class CreatePrimitiveCommand implements Command {
  readonly label: string;
  /** The newly-added node — captured on first `do()` and re-used on redo. */
  node: MeshObject | null = null;
  constructor(public readonly scene: Scene, public readonly kind: PrimitiveKind, public params: PrimitiveParams = {}) {
    this.label = 'Add ' + DEFAULT_NAME[kind];
  }
  do(): void {
    if (this.node == null) {
      const m = buildMesh(this.kind, this.params);
      this.node = new MeshObject(DEFAULT_NAME[this.kind]);
      this.node.mesh = m;
      this.scene.addNode(this.node);
    } else if (!this.node.parent) {
      // Redo path.
      this.node.mesh = buildMesh(this.kind, this.params);
      this.scene.addNode(this.node);
    }
  }
  undo(): void {
    if (this.node && this.node.parent) {
      this.scene.removeNode(this.node);
    }
  }
  /**
   * Used by `History.replaceTop` to update the mesh in place when the user
   * tweaks params via the action bar.
   */
  rebuildWith(params: PrimitiveParams): void {
    this.params = params;
    if (this.node) this.node.mesh = buildMesh(this.kind, this.params);
  }
}
