// Deep-copy an EditableMesh. Two variants:
//
//   `cloneMesh`             — assigns fresh ids (used for Duplicate / Combine
//                             where the new mesh is a distinct object).
//   `cloneMeshPreservingIds` — copies every record verbatim so external
//                             references to vertex / edge / face ids stay
//                             valid (used for undo snapshots).

import { EditableMesh } from './EditableMesh';
import { type Id } from '../core/Id';
import * as Vec2 from '../core/math/Vec2';
import * as Vec3 from '../core/math/Vec3';

export function cloneMesh(src: EditableMesh): EditableMesh {
  const dst = new EditableMesh();
  const vertMap = new Map<Id, Id>();
  for (const v of src.vertices.values()) {
    const n = dst.addVertex(v.position[0], v.position[1], v.position[2]);
    vertMap.set(v.id, n.id);
  }
  for (const f of src.faces.values()) {
    const vertIds = f.loops.map((lid) => {
      const loop = src.loops.get(lid)!;
      return vertMap.get(loop.vertexId)!;
    });
    const newFace = dst.addFace(vertIds, f.materialId);
    const newLoops = dst.faceLoops(newFace.id);
    const srcLoops = f.loops.map((lid) => src.loops.get(lid)!);
    for (let i = 0; i < newLoops.length; i++) {
      newLoops[i].uv[0] = srcLoops[i].uv[0];
      newLoops[i].uv[1] = srcLoops[i].uv[1];
      newLoops[i].normal[0] = srcLoops[i].normal[0];
      newLoops[i].normal[1] = srcLoops[i].normal[1];
      newLoops[i].normal[2] = srcLoops[i].normal[2];
    }
    newFace.normal[0] = f.normal[0];
    newFace.normal[1] = f.normal[1];
    newFace.normal[2] = f.normal[2];
  }
  for (const e of src.edges.values()) {
    const a = vertMap.get(e.a);
    const b = vertMap.get(e.b);
    if (a == null || b == null) continue;
    const newEdge = findEdge(dst, a, b);
    if (newEdge) {
      newEdge.hard = e.hard;
      newEdge.seam = e.seam;
    }
  }
  return dst;
}

/**
 * Structural clone — copies the entire EditableMesh keeping all internal
 * ids intact. Use for undo snapshots so callers' captured ids stay valid.
 */
export function cloneMeshPreservingIds(src: EditableMesh): EditableMesh {
  const dst = new EditableMesh();
  for (const v of src.vertices.values()) {
    dst.vertices.set(v.id, {
      id: v.id,
      position: Vec3.fromValues(v.position[0], v.position[1], v.position[2]),
      normal: Vec3.fromValues(v.normal[0], v.normal[1], v.normal[2]),
      edges: [...v.edges],
    });
  }
  for (const e of src.edges.values()) {
    dst.edges.set(e.id, {
      id: e.id,
      a: e.a,
      b: e.b,
      loops: [...e.loops],
      hard: e.hard,
      seam: e.seam,
    });
  }
  for (const l of src.loops.values()) {
    dst.loops.set(l.id, {
      id: l.id,
      faceId: l.faceId,
      edgeId: l.edgeId,
      vertexId: l.vertexId,
      uv: Vec2.fromValues(l.uv[0], l.uv[1]),
      normal: Vec3.fromValues(l.normal[0], l.normal[1], l.normal[2]),
    });
  }
  for (const f of src.faces.values()) {
    dst.faces.set(f.id, {
      id: f.id,
      loops: [...f.loops],
      normal: Vec3.fromValues(f.normal[0], f.normal[1], f.normal[2]),
      materialId: f.materialId,
    });
  }
  return dst;
}

function findEdge(mesh: EditableMesh, a: Id, b: Id): import('./Topology').Edge | null {
  const va = mesh.vertices.get(a);
  if (!va) return null;
  for (const eid of va.edges) {
    const e = mesh.edges.get(eid);
    if (!e) continue;
    if ((e.a === a && e.b === b) || (e.a === b && e.b === a)) return e;
  }
  return null;
}
