// Verify each object command applies, undoes, redoes correctly.

import { defineTest, assert, assertEquals } from '../../harness';
import { Scene } from '../../scene/Scene';
import { MeshObject } from '../../scene/MeshObject';
import { History } from '../Commands';
import {
  ShadeSmoothCommand,
  ShadeFlatCommand,
  SubdivideCommand,
  CatmullClarkCommand,
  MirrorCommand,
  DuplicateCommand,
  DeleteObjectCommand,
  CombineCommand,
} from './ObjectCommands';
import { buildCube } from '../../mesh/primitives/Cube';

const SUITE = 'objectCommands';

function makeScene(): { scene: Scene; cube: MeshObject; history: History } {
  const scene = new Scene();
  const cube = new MeshObject('Cube');
  cube.mesh = buildCube();
  scene.addNode(cube);
  return { scene, cube, history: new History() };
}

defineTest(SUITE, 'ShadeFlat → Shade Smooth round-trip via undo', () => {
  const { cube, history } = makeScene();
  history.execute(new ShadeFlatCommand(cube));
  for (const e of cube.mesh!.edges.values()) assertEquals(e.hard, true);
  history.undo();
  for (const e of cube.mesh!.edges.values()) assertEquals(e.hard, false);
  history.redo();
  for (const e of cube.mesh!.edges.values()) assertEquals(e.hard, true);
});

defineTest(SUITE, 'Subdivide quad face count grows then undo restores', () => {
  const { cube, history } = makeScene();
  const before = cube.mesh!.faceCount();
  history.execute(new SubdivideCommand(cube));
  assert(cube.mesh!.faceCount() > before);
  history.undo();
  assertEquals(cube.mesh!.faceCount(), before);
});

defineTest(SUITE, 'CatmullClark first pass behaves like Subdivide', () => {
  const { cube, history } = makeScene();
  const before = cube.mesh!.faceCount();
  history.execute(new CatmullClarkCommand(cube));
  assert(cube.mesh!.faceCount() > before);
});

defineTest(SUITE, 'Duplicate adds a sibling; undo removes it', () => {
  const { scene, cube, history } = makeScene();
  history.execute(new DuplicateCommand(scene, cube));
  assertEquals(scene.root.children.length, 2);
  history.undo();
  assertEquals(scene.root.children.length, 1);
});

defineTest(SUITE, 'Delete removes the node; undo restores it', () => {
  const { scene, cube, history } = makeScene();
  history.execute(new DeleteObjectCommand(scene, cube));
  assertEquals(scene.root.children.length, 0);
  history.undo();
  assertEquals(scene.root.children.length, 1);
});

defineTest(SUITE, 'Combine merges two cubes into one; undo restores both', () => {
  const { scene, cube, history } = makeScene();
  const cube2 = new MeshObject('Cube2');
  cube2.mesh = buildCube();
  scene.addNode(cube2);
  history.execute(new CombineCommand(scene, [cube, cube2]));
  assertEquals(scene.root.children.length, 1);
  history.undo();
  assertEquals(scene.root.children.length, 2);
});

defineTest(SUITE, 'Mirror across X preserves topology validity', () => {
  const { cube, history } = makeScene();
  // Move cube off the X=0 plane so mirror really doubles geometry.
  cube.transform.setPosition(2, 0, 0);
  history.execute(new MirrorCommand(cube, 'x', false));
  const r = cube.mesh!.validate();
  assert(r.ok, r.errors.join('; '));
});
