// Minimal VAO/VBO/EBO wrapper for the editor's draw calls. We always
// upload interleaved-less buffers (separate VBOs per attribute) — keeps
// the editor render-mesh shape (positions, normals, uvs, ids) tractable.

export interface VertexBufferLayout {
  attribIndex: number;
  componentsPerVertex: number;
  data: Float32Array;
  /** Number of bytes per component — default Float32. */
  bytesPerComponent?: number;
  /** Integer attribute? */
  asInt?: boolean;
}

export class GpuMesh {
  readonly gl: WebGL2RenderingContext;
  readonly vao: WebGLVertexArrayObject;
  private vbos: WebGLBuffer[] = [];
  private ebo: WebGLBuffer | null = null;
  indexCount = 0;

  constructor(gl: WebGL2RenderingContext) {
    this.gl = gl;
    const v = gl.createVertexArray();
    if (!v) throw new Error('createVertexArray failed');
    this.vao = v;
  }

  uploadAttributes(layouts: VertexBufferLayout[]): void {
    const { gl } = this;
    gl.bindVertexArray(this.vao);
    // Reset old VBOs.
    for (const b of this.vbos) gl.deleteBuffer(b);
    this.vbos = [];
    for (const l of layouts) {
      const vbo = gl.createBuffer();
      if (!vbo) throw new Error('createBuffer failed');
      gl.bindBuffer(gl.ARRAY_BUFFER, vbo);
      gl.bufferData(gl.ARRAY_BUFFER, l.data, gl.STATIC_DRAW);
      gl.enableVertexAttribArray(l.attribIndex);
      gl.vertexAttribPointer(l.attribIndex, l.componentsPerVertex, gl.FLOAT, false, 0, 0);
      this.vbos.push(vbo);
    }
    gl.bindVertexArray(null);
  }

  uploadIndices(data: Uint32Array): void {
    const { gl } = this;
    if (!this.ebo) {
      const e = gl.createBuffer();
      if (!e) throw new Error('createBuffer failed');
      this.ebo = e;
    }
    gl.bindVertexArray(this.vao);
    gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, this.ebo);
    gl.bufferData(gl.ELEMENT_ARRAY_BUFFER, data, gl.STATIC_DRAW);
    gl.bindVertexArray(null);
    this.indexCount = data.length;
  }

  drawTriangles(): void {
    const { gl } = this;
    gl.bindVertexArray(this.vao);
    gl.drawElements(gl.TRIANGLES, this.indexCount, gl.UNSIGNED_INT, 0);
    gl.bindVertexArray(null);
  }

  dispose(): void {
    const { gl } = this;
    for (const b of this.vbos) gl.deleteBuffer(b);
    if (this.ebo) gl.deleteBuffer(this.ebo);
    gl.deleteVertexArray(this.vao);
    this.vbos = [];
    this.ebo = null;
  }
}
