// glTF export tests — parse the exported document and verify it's a valid
// glTF 2.0 file with the right buffer / mesh structure.

import { defineTest, assert, assertEquals } from '../harness';
import { Scene, MeshObject } from '../scene/Scene';
import { Material } from '../scene/Material';
import { buildCube } from '../mesh/primitives/Cube';
import { exportGltf } from './GltfFormat';

const SUITE = 'gltfIo';

defineTest(SUITE, 'exportGltf produces a glTF 2.0 document with the expected sections', () => {
  const scene = new Scene();
  const node = new MeshObject('Cube');
  node.mesh = buildCube();
  scene.addNode(node);
  const { document, glb, json } = exportGltf(scene);
  assertEquals(document.asset.version, '2.0');
  assertEquals(document.meshes.length, 1);
  assertEquals(document.nodes.length, 1);
  assertEquals(document.buffers.length, 1);
  assert(document.buffers[0].byteLength > 0);
  assert(document.accessors.length >= 4); // POSITION, NORMAL, TEXCOORD_0, indices
  // Re-parsing the JSON should succeed and contain the same mesh count.
  const parsed = JSON.parse(json);
  assertEquals(parsed.meshes.length, 1);
  // GLB header sanity.
  const dv = new DataView(glb);
  assertEquals(dv.getUint32(0, true), 0x46546c67);
  assertEquals(dv.getUint32(4, true), 2);
});

defineTest(SUITE, 'glTF cube node has POSITION + NORMAL + TEXCOORD_0 accessors', () => {
  const scene = new Scene();
  const node = new MeshObject('Cube');
  node.mesh = buildCube();
  scene.addNode(node);
  const { document } = exportGltf(scene);
  const prim = document.meshes[0].primitives[0];
  assert(prim.attributes.POSITION != null);
  assert(prim.attributes.NORMAL != null);
  assert(prim.attributes.TEXCOORD_0 != null);
  // POSITION accessor count should be 6 faces × 4 corners = 24.
  const posAccessor = document.accessors[prim.attributes.POSITION];
  assertEquals(posAccessor.type, 'VEC3');
  assertEquals(posAccessor.count, 24);
});

defineTest(SUITE, 'glTF node transform mirrors the source node transform', () => {
  const scene = new Scene();
  const node = new MeshObject('Cube');
  node.mesh = buildCube();
  node.transform.position[0] = 1.5;
  node.transform.position[1] = -2;
  node.transform.position[2] = 3;
  scene.addNode(node);
  const { document } = exportGltf(scene);
  const gltfNode = document.nodes[0];
  assertEquals(gltfNode.name, 'Cube');
  assert(Math.abs((gltfNode.translation as number[])[0] - 1.5) < 1e-6);
  assert(Math.abs((gltfNode.translation as number[])[1] + 2) < 1e-6);
});

defineTest(SUITE, 'glTF export embeds material baseColorFactor', () => {
  const scene = new Scene();
  const node = new MeshObject('Cube');
  node.mesh = buildCube();
  const mat = new Material('Red');
  mat.setBaseColor(0.9, 0.1, 0.1);
  mat.opacity = 0.8;
  scene.addMaterial(mat);
  node.materialId = mat.id;
  scene.addNode(node);
  const { document } = exportGltf(scene);
  assert(document.materials != null);
  assertEquals(document.materials!.length, 1);
  const m = document.materials![0];
  assertEquals(m.name, 'Red');
  assert(Math.abs(m.pbrMetallicRoughness.baseColorFactor[0] - 0.9) < 1e-4);
  assert(Math.abs(m.pbrMetallicRoughness.baseColorFactor[3] - 0.8) < 1e-4);
  assertEquals(m.alphaMode, 'BLEND');
});

defineTest(SUITE, 'glTF export embeds material texture as a PNG buffer view', () => {
  const scene = new Scene();
  const node = new MeshObject('Cube');
  node.mesh = buildCube();
  const mat = new Material('Tex');
  // 1×1 RGBA red.
  mat.setTexture({ name: 'pixel', width: 1, height: 1, data: new Uint8Array([255, 0, 0, 255]) });
  scene.addMaterial(mat);
  node.materialId = mat.id;
  scene.addNode(node);
  const { document } = exportGltf(scene);
  assert(document.materials != null);
  assert(document.textures != null);
  assert(document.images != null);
  assertEquals(document.textures!.length, 1);
  assert(document.materials![0].pbrMetallicRoughness.baseColorTexture != null);
});
