// Transform — translation + rotation + scale, with a cached local matrix.

import * as Vec3 from '../core/math/Vec3';
import * as Quat from '../core/math/Quat';
import * as Mat4 from '../core/math/Mat4';

export class Transform {
  readonly position: Vec3.Vec3 = Vec3.create();
  readonly rotation: Quat.Quat = Quat.create();
  readonly scale: Vec3.Vec3 = Vec3.fromValues(1, 1, 1);

  private _local: Mat4.Mat4 = Mat4.create();
  private _localDirty = true;

  setPosition(x: number, y: number, z: number): void {
    Vec3.set(this.position, x, y, z);
    this._localDirty = true;
  }

  setRotationQuat(x: number, y: number, z: number, w: number): void {
    this.rotation[0] = x;
    this.rotation[1] = y;
    this.rotation[2] = z;
    this.rotation[3] = w;
    Quat.normalize(this.rotation, this.rotation);
    this._localDirty = true;
  }

  setScale(x: number, y: number, z: number): void {
    Vec3.set(this.scale, x, y, z);
    this._localDirty = true;
  }

  markDirty(): void {
    this._localDirty = true;
  }

  getLocalMatrix(): Readonly<Mat4.Mat4> {
    if (this._localDirty) {
      Mat4.trs(this._local, this.position, this.rotation, this.scale);
      this._localDirty = false;
    }
    return this._local;
  }
}
