// Selection state — mode + per-element id sets, scoped per mesh object.

import type { Id } from '../core/Id';

export type SelectionMode = 'object' | 'vertex' | 'edge' | 'face' | 'uv';

export class Selection {
  mode: SelectionMode = 'object';
  activeObjectId: Id | null = null;
  readonly selectedObjects = new Set<Id>();
  /** meshObjectId → element ids. */
  readonly selectedVertices = new Map<Id, Set<Id>>();
  readonly selectedEdges = new Map<Id, Set<Id>>();
  readonly selectedFaces = new Map<Id, Set<Id>>();
  /** meshObjectId → loop ids (UVs are per-loop). */
  readonly selectedUvs = new Map<Id, Set<Id>>();
  /** Flat set of selected UV loop ids — used by the UV viewport. */
  readonly selectedUvLoops = new Set<Id>();

  setMode(m: SelectionMode): void {
    this.mode = m;
  }

  clearAll(): void {
    this.activeObjectId = null;
    this.selectedObjects.clear();
    this.selectedVertices.clear();
    this.selectedEdges.clear();
    this.selectedFaces.clear();
    this.selectedUvs.clear();
    this.selectedUvLoops.clear();
  }

  selectUvLoop(loopId: Id, additive = false): void {
    if (!additive) this.selectedUvLoops.clear();
    this.selectedUvLoops.add(loopId);
  }

  deselectUvLoop(loopId: Id): void {
    this.selectedUvLoops.delete(loopId);
  }

  clearUvSelection(): void {
    this.selectedUvLoops.clear();
  }

  setObjectSelection(id: Id, additive = false): void {
    if (!additive) this.selectedObjects.clear();
    this.selectedObjects.add(id);
    this.activeObjectId = id;
  }

  toggleObject(id: Id): void {
    if (this.selectedObjects.has(id)) {
      this.selectedObjects.delete(id);
      if (this.activeObjectId === id) this.activeObjectId = null;
    } else {
      this.selectedObjects.add(id);
      this.activeObjectId = id;
    }
  }

  isObjectSelected(id: Id): boolean {
    return this.selectedObjects.has(id);
  }

  selectFace(meshId: Id, faceId: Id, additive = false): void {
    let bucket = this.selectedFaces.get(meshId);
    if (!additive) bucket = undefined;
    if (!bucket) {
      bucket = new Set();
      this.selectedFaces.set(meshId, bucket);
    }
    bucket.add(faceId);
    this.activeObjectId = meshId;
  }

  selectVertex(meshId: Id, vertexId: Id, additive = false): void {
    let bucket = this.selectedVertices.get(meshId);
    if (!additive) bucket = undefined;
    if (!bucket) {
      bucket = new Set();
      this.selectedVertices.set(meshId, bucket);
    }
    bucket.add(vertexId);
    this.activeObjectId = meshId;
  }

  selectEdge(meshId: Id, edgeId: Id, additive = false): void {
    let bucket = this.selectedEdges.get(meshId);
    if (!additive) bucket = undefined;
    if (!bucket) {
      bucket = new Set();
      this.selectedEdges.set(meshId, bucket);
    }
    bucket.add(edgeId);
    this.activeObjectId = meshId;
  }

  isFaceSelected(meshId: Id, faceId: Id): boolean {
    return this.selectedFaces.get(meshId)?.has(faceId) ?? false;
  }

  isVertexSelected(meshId: Id, vertexId: Id): boolean {
    return this.selectedVertices.get(meshId)?.has(vertexId) ?? false;
  }

  isEdgeSelected(meshId: Id, edgeId: Id): boolean {
    return this.selectedEdges.get(meshId)?.has(edgeId) ?? false;
  }

  selectedObjectCount(): number {
    return this.selectedObjects.size;
  }
}
