// RenderMesh — flat triangle buffers generated from an EditableMesh.
//
// Layout: one vertex per loop (no dedup across faces, so UV / normal seams
// are honoured). Triangles are produced by ear-clipping each face.

import * as Vec3 from '../core/math/Vec3';
import type { EditableMesh } from './EditableMesh';
import type { Id } from '../core/Id';
import { earClip } from './Triangulation';
import { recomputeLoopNormals } from './Normals';

export interface RenderBuffers {
  positions: Float32Array; // 3 floats per vertex
  normals: Float32Array;   // 3 floats per vertex
  uvs: Float32Array;       // 2 floats per vertex
  faceIds: Float32Array;   // 1 float per vertex (face id)
  materialIds: Float32Array; // 1 float per vertex (material id, -1 if none)
  indices: Uint32Array;    // 3 per triangle, indices into the vertex arrays
  triangleCount: number;
  vertexCount: number;
}

export class RenderMesh {
  buffers: RenderBuffers = createEmptyBuffers();
  /** Bumped whenever rebuild() runs. Renderer checks this to invalidate VBO uploads. */
  version = 0;
  private _dirty = true;

  markDirty(): void {
    this._dirty = true;
  }

  isDirty(): boolean {
    return this._dirty;
  }

  /** Rebuild from the editable mesh. Idempotent; only does work if dirty. */
  rebuild(mesh: EditableMesh, force = false): boolean {
    if (!force && !this._dirty) return false;
    mesh.recomputeFaceNormals();
    recomputeLoopNormals(mesh);
    this.buffers = buildBuffers(mesh);
    this._dirty = false;
    this.version++;
    return true;
  }
}

function createEmptyBuffers(): RenderBuffers {
  return {
    positions: new Float32Array(0),
    normals: new Float32Array(0),
    uvs: new Float32Array(0),
    faceIds: new Float32Array(0),
    materialIds: new Float32Array(0),
    indices: new Uint32Array(0),
    triangleCount: 0,
    vertexCount: 0,
  };
}

function buildBuffers(mesh: EditableMesh): RenderBuffers {
  // Count.
  let vertexCount = 0;
  let triCount = 0;
  for (const face of mesh.faces.values()) {
    vertexCount += face.loops.length;
    triCount += Math.max(0, face.loops.length - 2);
  }

  const positions = new Float32Array(vertexCount * 3);
  const normals = new Float32Array(vertexCount * 3);
  const uvs = new Float32Array(vertexCount * 2);
  const faceIds = new Float32Array(vertexCount);
  const materialIds = new Float32Array(vertexCount);
  const indices = new Uint32Array(triCount * 3);

  let vp = 0;          // vertex slot pointer (in vertex units, not floats)
  let ip = 0;          // index slot pointer
  const _facePositions: Vec3.Vec3[] = [];

  for (const face of mesh.faces.values()) {
    const baseVertex = vp;
    _facePositions.length = face.loops.length;
    for (let i = 0; i < face.loops.length; i++) {
      const lid = face.loops[i];
      const loop = mesh.loops.get(lid)!;
      const v = mesh.vertices.get(loop.vertexId)!;
      positions[vp * 3 + 0] = v.position[0];
      positions[vp * 3 + 1] = v.position[1];
      positions[vp * 3 + 2] = v.position[2];
      normals[vp * 3 + 0] = loop.normal[0];
      normals[vp * 3 + 1] = loop.normal[1];
      normals[vp * 3 + 2] = loop.normal[2];
      uvs[vp * 2 + 0] = loop.uv[0];
      uvs[vp * 2 + 1] = loop.uv[1];
      faceIds[vp] = face.id as unknown as number;
      materialIds[vp] = (face.materialId ?? -1) as unknown as number;
      _facePositions[i] = v.position;
      vp++;
    }
    // Triangulate.
    let tris: number[];
    if (face.loops.length === 3) {
      tris = [0, 1, 2];
    } else if (face.loops.length === 4) {
      tris = [0, 1, 2, 0, 2, 3];
    } else {
      tris = earClip(_facePositions, face.normal);
    }
    for (let i = 0; i < tris.length; i++) {
      indices[ip++] = baseVertex + tris[i];
    }
  }

  return {
    positions,
    normals,
    uvs,
    faceIds,
    materialIds,
    indices: indices.subarray(0, ip),
    triangleCount: ip / 3,
    vertexCount,
  };
}

/** Helper for testing / external use: rebuild from scratch and return buffers. */
export function buildRenderMesh(mesh: EditableMesh): RenderBuffers {
  const rm = new RenderMesh();
  rm.rebuild(mesh, true);
  return rm.buffers;
}

/** Returns the bounding box of the input mesh's positions, as [min, max]. */
export function meshBoundingBox(mesh: EditableMesh): [Vec3.Vec3, Vec3.Vec3] {
  const min = Vec3.fromValues(Infinity, Infinity, Infinity);
  const max = Vec3.fromValues(-Infinity, -Infinity, -Infinity);
  for (const v of mesh.vertices.values()) {
    if (v.position[0] < min[0]) min[0] = v.position[0];
    if (v.position[1] < min[1]) min[1] = v.position[1];
    if (v.position[2] < min[2]) min[2] = v.position[2];
    if (v.position[0] > max[0]) max[0] = v.position[0];
    if (v.position[1] > max[1]) max[1] = v.position[1];
    if (v.position[2] > max[2]) max[2] = v.position[2];
  }
  return [min, max];
}

// Re-export typedef used by tests.
export type { Id };
