// App — top-level orchestrator. Owns the shared WebGL2 context, the Gwen
// renderer/skin/canvas stack, the frame loop, resize handling, and the
// UI shell (item 4). Items 10+ replace the placeholder scene pass with a
// real 3D pipeline.

import { buildUi, type UiRefs } from '../ui/UiRoot';
import { Scene } from '../scene/Scene';
import { Renderer } from '../render/Renderer';
import { MeshObject } from '../scene/MeshObject';
import { buildCube } from '../mesh/primitives/Cube';
import type { ViewportHost } from '../ui/ViewportHost';
import { CameraController } from './CameraController';
import { Selection } from './Selection';
import { pickObjectInScene, pickFace, pickVertex, pickEdge } from './Picking';
import { History } from './Commands';
import { ToolController, type ToolName } from './ToolController';
import { TouchController } from './TouchController';
import { SetTransformCommand } from './commands/SetTransformCommand';
import { CreatePrimitiveCommand, type PrimitiveKind } from './commands/CreatePrimitiveCommand';
import { primitiveActionBarFields, primitiveParamsFromFields } from './commands/PrimitiveActionBarParams';
import { exportObj } from '../io/ObjFormat';
import { exportGltf } from '../io/GltfFormat';

function absoluteViewportRect(viewport: ViewportHost): { x: number; y: number; w: number; h: number } {
  let x = 0, y = 0;
  let node: Gwen.Base | null = viewport;
  while (node) {
    const b = node.getBounds();
    x += b.x;
    y += b.y;
    node = node.parent;
  }
  const b = viewport.getBounds();
  return { x, y, w: b.w, h: b.h };
}

const APP_BG: [number, number, number, number] = [0.149, 0.149, 0.149, 1.0]; // matches DARK_PALETTE.canvasBg ~ #262626 area
// (#262626 = 0x26 = 38 → 38/255 ≈ 0.149)

export interface AppOptions {
  canvas: HTMLCanvasElement;
}

export class App {
  readonly canvas: HTMLCanvasElement;
  readonly gl: WebGL2RenderingContext;
  readonly renderer: Gwen.WebGL2Renderer;
  readonly skin: Gwen.Skin;
  readonly gwenCanvas: Gwen.Canvas;
  readonly ui: UiRefs;
  readonly scene: Scene;
  readonly sceneRenderer: Renderer;
  readonly selection = new Selection();
  readonly history = new History();
  readonly tools = new ToolController(this);

  private rafId: number | null = null;
  private resizeObs: ResizeObserver | null = null;
  private lastFrameTime = 0;
  private frameCount = 0;
  private fps = 0;
  private fpsTimer = 0;
  private lastFrameMs = 0;

  // GL state Gwen's renderer relies on between begin() calls (it binds
  // them once in init() and never re-asserts them in begin()). After our
  // 3D pass clobbers the program/VAO/buffer bindings, we restore these
  // before handing the frame back to Gwen.
  private gwenProgram: WebGLProgram | null = null;
  private gwenVao: WebGLVertexArrayObject | null = null;
  private gwenVbo: WebGLBuffer | null = null;

  constructor(opts: AppOptions) {
    this.canvas = opts.canvas;

    // CRITICAL: acquire the WebGL2 context FIRST with the attributes we
    // need. Gwen's later `getContext` call will return the same context
    // regardless of the attributes it asks for, so we get depth even though
    // Gwen requests depth:false. See notes/gwen-integration.md §1.
    const dpr = window.devicePixelRatio || 1;
    this.sizeBackingStore(dpr);
    const gl = this.canvas.getContext('webgl2', {
      alpha: true,
      premultipliedAlpha: false,
      antialias: false,
      depth: true,
      stencil: false,
      preserveDrawingBuffer: false,
    });
    if (!gl) throw new Error('BrutalMesh: WebGL2 is not available');
    this.gl = gl;

    this.renderer = new Gwen.WebGL2Renderer(this.canvas, { devicePixelRatio: dpr });
    this.renderer.init();
    // Snapshot Gwen's GL state so we can restore it after our 3D pass.
    const guts = this.renderer as unknown as { program: WebGLProgram; vao: WebGLVertexArrayObject; vbo: WebGLBuffer };
    this.gwenProgram = guts.program;
    this.gwenVao = guts.vao;
    this.gwenVbo = guts.vbo;

    this.skin = new Gwen.Skin(this.renderer);
    this.skin.init();
    this.skin.setTheme(Gwen.DARK_PALETTE);

    this.gwenCanvas = new Gwen.Canvas(this.skin, this.canvas);
    this.gwenCanvas.setBounds(0, 0, this.canvas.clientWidth, this.canvas.clientHeight);
    // Gwen MUST NOT clear/draw the background; our 3D pass owns the framebuffer.
    this.gwenCanvas.setDrawBackground(false);

    this.ui = buildUi(this.gwenCanvas);

    // Build the scene with a real cube mesh so the renderer has something to draw.
    this.scene = Scene.createDefault();
    for (const node of [...this.scene.root.children]) {
      if (node.kind === 'mesh') {
        (node as MeshObject).mesh = buildCube();
      }
    }
    this.sceneRenderer = new Renderer(this.gl);
    this.sceneRenderer.syncScene(this.scene);

    // Compose a delegate that handles camera controls, gizmo drags, and
    // left-click → selection picking. Left button is reserved for gizmo +
    // selection; right is orbit; middle is pan (see installMiddleClickListener).
    const cameraCtl = new CameraController(this.sceneRenderer.layout);
    this.ui.viewport.delegate = {
      pointerDown: (button, x, y) => {
        if (button === 0) {
          if (this.tools.tryStartDrag(x, y)) {
            return;
          }
          this.runPickAt(x, y);
          return;
        }
        cameraCtl.pointerDown(button, x, y);
      },
      pointerMove: (x, y, dx, dy) => {
        if (this.tools.isDragging()) {
          this.tools.drag(x, y);
          return;
        }
        cameraCtl.pointerMove(x, y, dx, dy);
      },
      pointerUp: (button, x, y) => {
        if (button === 0 && this.tools.isDragging()) {
          this.tools.endDrag();
          return;
        }
        cameraCtl.pointerUp(button, x, y);
      },
      wheel: (delta, x, y) => cameraCtl.wheel(delta, x, y),
    };
    this.sceneRenderer.selection = this.selection;
    this.sceneRenderer.tools = this.tools;

    // After every command, mark render meshes dirty so any topology /
    // transform change is picked up next frame.
    this.history.on(() => {
      this.sceneRenderer.markAllDirty();
    });

    // Wire Undo / Redo menu items.
    this.ui.menu.editMenu.getMenu().children.forEach((mc) => {
      // The MenuItem subclass exposes onMenuItemSelected; we wire to the first two items.
    });
    this.wireUndoRedoMenuItems();

    // Wire the Undo / Redo buttons in the top action bar.
    this.ui.actionBar.undoButton.onPress.on(() => this.history.undo());
    this.ui.actionBar.redoButton.onPress.on(() => this.history.redo());

    // Keep the History panel in sync with the stack.
    this.history.on(() => this.refreshHistoryPanel());
    this.refreshHistoryPanel();

    // Sync action-bar numeric fields with the most recent transform command.
    this.history.on(() => this.refreshActionBarFromTop());
    this.wireActionBarEdits();
    this.refreshActionBarFromTop();

    // Wire primitive creation buttons in the tool shelf.
    this.wirePrimitiveButtons();

    // Wire export menu items in the File menu.
    this.wireExportMenuItems();

    // Wire the right-dock panels to the live scene + selection.
    this.wireRightDockPanels();
    this.refreshAllPanels();

    // Wire the upper-right view widget to the perspective camera.
    this.wireViewWidget();

    // Gwen's input router doesn't route middle-button (button=1) clicks
    // to controls. Add a side-channel listener that forwards middle
    // clicks to the viewport host directly.
    this.installMiddleClickListener();

    // Touch interaction (item 32).
    new TouchController(this.canvas, this.ui.viewport, this.sceneRenderer.layout).install();
  }

  start(): void {
    this.installResize();
    this.lastFrameTime = performance.now();
    const tick = (): void => {
      this.frame();
      this.rafId = requestAnimationFrame(tick);
    };
    this.rafId = requestAnimationFrame(tick);
  }

  stop(): void {
    if (this.rafId != null) cancelAnimationFrame(this.rafId);
    this.rafId = null;
    if (this.resizeObs) {
      this.resizeObs.disconnect();
      this.resizeObs = null;
    }
  }

  getFps(): number {
    return this.fps;
  }

  setViewportMode(mode: 'single' | 'fourView' | 'uv'): void {
    this.sceneRenderer.layout.setMode(mode);
  }

  setDisplayMode(mode: 'shaded' | 'xray' | 'textured' | 'unlit'): void {
    this.sceneRenderer.setViewMode(mode);
  }

  setSelectionMode(mode: 'object' | 'vertex' | 'edge' | 'face' | 'uv'): void {
    this.selection.setMode(mode);
  }

  setTool(tool: ToolName): void {
    this.tools.setTool(tool);
  }

  /**
   * Run a CPU pick at viewport-local coords `(x, y)`. The active sub-viewport
   * (under the cursor) determines the camera + rect used. Returns the picked
   * id (object / face / vertex / edge) or null.
   */
  pickAt(canvasX: number, canvasY: number): { kind: string; id: number | null } | null {
    const sub = this.sceneRenderer.layout.subviewportAt(canvasX, canvasY);
    if (!sub) return null;
    const aspect = sub.rect.w / Math.max(1, sub.rect.h);
    const ax = canvasX;
    const ay = canvasY;

    if (this.selection.mode === 'object') {
      const hit = pickObjectInScene(this.scene, ax, ay, sub.rect, sub.camera, aspect);
      if (hit) {
        this.selection.setObjectSelection(hit.node.id);
        return { kind: 'object', id: hit.node.id as unknown as number };
      }
      this.selection.clearAll();
      return { kind: 'object', id: null };
    }

    // Vertex/edge/face all need an active mesh object. Use the previously
    // active mesh if there is one; otherwise pick by ray first.
    const obj = this.findActiveMeshObject() ?? pickObjectInScene(this.scene, ax, ay, sub.rect, sub.camera, aspect)?.node;
    if (!obj || !obj.mesh) return null;
    const world = obj.getWorldMatrix();

    if (this.selection.mode === 'face') {
      const fid = pickFace(obj.mesh, world as Float32Array, ax, ay, sub.rect, sub.camera, aspect);
      if (fid != null) {
        this.selection.selectFace(obj.id, fid);
        return { kind: 'face', id: fid as unknown as number };
      }
    } else if (this.selection.mode === 'vertex') {
      const vid = pickVertex(obj.mesh, world as Float32Array, ax, ay, sub.rect, sub.camera, aspect);
      if (vid != null) {
        this.selection.selectVertex(obj.id, vid);
        return { kind: 'vertex', id: vid as unknown as number };
      }
    } else if (this.selection.mode === 'edge') {
      const eid = pickEdge(obj.mesh, world as Float32Array, ax, ay, sub.rect, sub.camera, aspect);
      if (eid != null) {
        this.selection.selectEdge(obj.id, eid);
        return { kind: 'edge', id: eid as unknown as number };
      }
    }
    return null;
  }

  private findActiveMeshObject(): MeshObject | null {
    if (!this.selection.activeObjectId) return null;
    const n = this.scene.findNodeById(this.selection.activeObjectId);
    return n && n.kind === 'mesh' ? (n as MeshObject) : null;
  }

  private runPickAt(localX: number, localY: number): void {
    this.pickAt(localX, localY);
  }

  /**
   * Locate the Undo / Redo menu items by label inside the Edit menu and
   * subscribe them to the history.
   */
  private refreshHistoryPanel(): void {
    const list = this.ui.rightDock.history;
    // ListBox#clear is fine to call repeatedly.
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const lb = list as any;
    if (typeof lb.clearItems === 'function') lb.clearItems();
    else if (typeof lb.clear === 'function') lb.clear();
    const labels = this.history.undoLabels();
    if (labels.length === 0) list.addItem('(empty history)');
    else for (const l of labels) list.addItem(l);
  }

  private refreshActionBarFromTop(): void {
    const stack = (this.history as unknown as { undoStack: unknown[] }).undoStack;
    const top = stack[stack.length - 1] as { label?: string } | undefined;
    if (top instanceof SetTransformCommand) {
      const t = (top as unknown as { next: { position: number[] } }).next;
      this.ui.actionBar.label.setText('  ' + (top.label ?? ''));
      this.ui.actionBar.xBox.setText(t.position[0].toFixed(3));
      this.ui.actionBar.yBox.setText(t.position[1].toFixed(3));
      this.ui.actionBar.zBox.setText(t.position[2].toFixed(3));
    } else if (top instanceof CreatePrimitiveCommand) {
      const fields = primitiveActionBarFields(top.kind, top.params);
      this.ui.actionBar.label.setText('  ' + (top.label ?? ''));
      this.ui.actionBar.xBox.setText(String(fields.x.value));
      this.ui.actionBar.yBox.setText(String(fields.y.value));
      this.ui.actionBar.zBox.setText(String(fields.z.value));
    } else {
      this.ui.actionBar.label.setText('  ' + (top?.label ?? 'Ready'));
    }
  }

  private wireActionBarEdits(): void {
    const onEdit = (): void => {
      const stack = (this.history as unknown as { undoStack: unknown[] }).undoStack;
      const top = stack[stack.length - 1];
      if (top instanceof SetTransformCommand) {
        const x = parseFloat(this.ui.actionBar.xBox.getText());
        const y = parseFloat(this.ui.actionBar.yBox.getText());
        const z = parseFloat(this.ui.actionBar.zBox.getText());
        if (!Number.isFinite(x) || !Number.isFinite(y) || !Number.isFinite(z)) return;
        const node = (top as unknown as { node: import('../scene/SceneNode').SceneNode }).node;
        const orig = (top as unknown as { next: { rotation: [number, number, number, number]; scale: [number, number, number] } }).next;
        const next = new SetTransformCommand(node, {
          position: [x, y, z],
          rotation: [orig.rotation[0], orig.rotation[1], orig.rotation[2], orig.rotation[3]],
          scale: [orig.scale[0], orig.scale[1], orig.scale[2]],
        }, (top as SetTransformCommand).label);
        this.history.replaceTop(next);
        return;
      }
      if (top instanceof CreatePrimitiveCommand) {
        const x = parseFloat(this.ui.actionBar.xBox.getText());
        const y = parseFloat(this.ui.actionBar.yBox.getText());
        const z = parseFloat(this.ui.actionBar.zBox.getText());
        const params = primitiveParamsFromFields(top.kind, top.params, x, y, z);
        top.rebuildWith(params);
        this.history.notifyTopChanged();
        return;
      }
    };
    this.ui.actionBar.xBox.onReturnPressed.on(onEdit);
    this.ui.actionBar.yBox.onReturnPressed.on(onEdit);
    this.ui.actionBar.zBox.onReturnPressed.on(onEdit);
  }

  /** Trigger a glTF export and return the JSON + GLB binary for tests. */
  exportSceneGltf(): { json: string; glb: ArrayBuffer; document: ReturnType<typeof exportGltf>['document'] } {
    return exportGltf(this.scene);
  }

  /** Trigger an OBJ export and return the OBJ + MTL strings for tests. */
  exportSceneObj(opts?: Parameters<typeof exportObj>[1]): ReturnType<typeof exportObj> {
    return exportObj(this.scene, opts);
  }

  /** Trigger a browser-side download for blob data. No-op in tests / Node. */
  private triggerDownload(filename: string, blob: Blob): void {
    if (typeof document === 'undefined' || typeof URL === 'undefined') return;
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  }

  /** Refresh outliner / inspector / materials panels (public for tests). */
  refreshPanels(): void {
    this.refreshAllPanels();
  }

  private refreshAllPanels(): void {
    this.refreshOutliner();
    this.refreshInspector();
    this.refreshMaterials();
  }

  private refreshOutliner(): void {
    const tree = this.ui.rightDock.outliner;
    // Clear all children (TreeControl supports remove via internal children).
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const treeAny = tree as any;
    if (treeAny.clear) treeAny.clear();
    else if (treeAny.removeAllNodes) treeAny.removeAllNodes();
    else {
      // Fallback: detach each child.
      for (const c of [...(tree as unknown as { children: Gwen.Base[] }).children]) {
        (c as unknown as { parent: Gwen.Base | null }).parent = null;
      }
    }
    const root = tree.addNode('Scene');
    const buildNode = (parent: Gwen.TreeNode, n: import('../scene/SceneNode').SceneNode): void => {
      if (n === this.scene.root) {
        for (const c of n.children) buildNode(parent, c);
        return;
      }
      const tn = parent.addNode(n.name || 'Node');
      for (const c of n.children) buildNode(tn, c);
    };
    buildNode(root, this.scene.root);
    tree.expandAll();
  }

  private refreshInspector(): void {
    const inspector = this.ui.rightDock.inspector;
    // Properties grid stores rows as direct children — each row has a
    // _property field with setPropertyValue().
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const insAny = inspector as any;
    let active: import('../scene/SceneNode').SceneNode | null = null;
    if (this.selection.activeObjectId) active = this.scene.findNodeById(this.selection.activeObjectId);
    const rows = (insAny.children as Gwen.Base[]).filter((c) => {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      return (c as any).getProperty != null;
    });
    const setRow = (idx: number, value: string): void => {
      const r = rows[idx];
      if (!r) return;
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const prop = (r as any).getProperty();
      if (prop && typeof prop.setPropertyValue === 'function') prop.setPropertyValue(value, false);
    };
    if (!active) {
      setRow(0, '(none)');
      setRow(1, '0');
      setRow(2, '0');
      setRow(3, '0');
      setRow(4, '0');
      return;
    }
    setRow(0, active.name);
    setRow(1, active.visible ? '1' : '0');
    if (active.kind === 'mesh') {
      const mesh = (active as MeshObject).mesh;
      setRow(2, String(mesh ? mesh.vertexCount() : 0));
      setRow(3, String(mesh ? mesh.edgeCount() : 0));
      setRow(4, String(mesh ? mesh.faceCount() : 0));
    } else {
      setRow(2, '-');
      setRow(3, '-');
      setRow(4, '-');
    }
  }

  private refreshMaterials(): void {
    const list = this.ui.rightDock.materials;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const lb = list as any;
    if (typeof lb.clearItems === 'function') lb.clearItems();
    else if (typeof lb.clear === 'function') lb.clear();
    const mats = this.scene.materials();
    if (mats.length === 0) list.addItem('(no materials)');
    else for (const m of mats) list.addItem(m.name);
  }

  private wireRightDockPanels(): void {
    // Re-render panels on any history event + selection change.
    this.history.on(() => this.refreshAllPanels());
    // Outliner node clicks change active object.
    const tree = this.ui.rightDock.outliner;
    // Best-effort: listen for selection change on the tree control.
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const treeAny = tree as any;
    if (treeAny.onSelectionChange?.on) {
      treeAny.onSelectionChange.on(() => this.refreshInspector());
    }
    // Export format combo: switch between OBJ / glTF / BMSH on export-trigger.
    const fmt = this.ui.rightDock.exportFormat.getComboBox();
    fmt.onSelection.on(() => {
      // No-op; the format will be consulted next time the user triggers export
      // via the panel's planned Export button (deferred to item 30 follow-up).
    });
  }

  private wireExportMenuItems(): void {
    const file = this.ui.menu.fileMenu.getMenu();
    for (const c of file.children) {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const mi = c as any;
      if (typeof mi.getText !== 'function') continue;
      const text: string = mi.getText();
      if (text === 'Export OBJ...' && mi.onMenuItemSelected) {
        mi.onMenuItemSelected.on(() => {
          const r = this.exportSceneObj({ mtlPath: 'scene.mtl' });
          this.triggerDownload('scene.obj', new Blob([r.obj], { type: 'text/plain' }));
          if (r.mtl) this.triggerDownload('scene.mtl', new Blob([r.mtl], { type: 'text/plain' }));
        });
      } else if (text === 'Export glTF...' && mi.onMenuItemSelected) {
        mi.onMenuItemSelected.on(() => {
          const r = this.exportSceneGltf();
          this.triggerDownload('scene.glb', new Blob([r.glb], { type: 'model/gltf-binary' }));
        });
      }
    }
  }

  private wireViewWidget(): void {
    const w = this.ui.viewWidget;
    const orient = (name: 'top' | 'front' | 'right' | 'back' | 'left' | 'bottom' | 'perspective'): void => {
      const cam = this.sceneRenderer.layout.perspectiveCam;
      cam.setOrientation(name);
      if (name === 'perspective') cam.setMode('perspective');
      else cam.setMode('orthographic');
    };
    w.buttons.top.onPress.on(() => orient('top'));
    w.buttons.front.onPress.on(() => orient('front'));
    w.buttons.right.onPress.on(() => orient('right'));
    w.buttons.back.onPress.on(() => orient('back'));
    w.buttons.left.onPress.on(() => orient('left'));
    w.buttons.bottom.onPress.on(() => orient('bottom'));
    w.buttons.perspective.onPress.on(() => orient('perspective'));
  }

  private wirePrimitiveButtons(): void {
    const buttons = this.ui.toolShelf.buttons;
    const map: Array<{ id: string; kind: PrimitiveKind }> = [
      { id: 'cube', kind: 'cube' },
      { id: 'plane', kind: 'plane' },
      { id: 'cylinder', kind: 'cylinder' },
      { id: 'cone', kind: 'cone' },
      { id: 'disk', kind: 'disk' },
      { id: 'uvsphere', kind: 'uvsphere' },
      { id: 'icosphere', kind: 'icosphere' },
      { id: 'torus', kind: 'torus' },
    ];
    for (const { id, kind } of map) {
      const btn = buttons[id];
      if (!btn) continue;
      btn.onPress.on(() => {
        this.history.execute(new CreatePrimitiveCommand(this.scene, kind, {}));
      });
    }
  }

  private wireUndoRedoMenuItems(): void {
    const editMenu = this.ui.menu.editMenu.getMenu();
    for (const c of editMenu.children) {
      // The MenuItem class has getText() (inherited from Label).
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const mi = c as any;
      if (typeof mi.getText !== 'function') continue;
      const text: string = mi.getText();
      if (text === 'Undo' && mi.onMenuItemSelected) {
        mi.onMenuItemSelected.on(() => this.history.undo());
      } else if (text === 'Redo' && mi.onMenuItemSelected) {
        mi.onMenuItemSelected.on(() => this.history.redo());
      }
    }
  }

  getDisplayMode(): 'shaded' | 'xray' | 'textured' | 'unlit' {
    const modes = ['shaded', 'xray', 'textured', 'unlit'] as const;
    const internal = (this.sceneRenderer as unknown as { meshRenderer: { mode: number } }).meshRenderer?.mode ?? 0;
    return modes[internal] ?? 'shaded';
  }

  private frame(): void {
    const now = performance.now();
    const dt = now - this.lastFrameTime;
    this.lastFrameTime = now;
    this.lastFrameMs = dt;
    this.frameCount++;
    this.fpsTimer += dt;
    if (this.fpsTimer >= 500) {
      this.fps = (this.frameCount * 1000) / this.fpsTimer;
      this.frameCount = 0;
      this.fpsTimer = 0;
    }

    const { gl, canvas } = this;
    // 3D / scene pass — own the framebuffer.
    gl.viewport(0, 0, canvas.width, canvas.height);
    gl.clearColor(APP_BG[0], APP_BG[1], APP_BG[2], APP_BG[3]);
    gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
    gl.enable(gl.DEPTH_TEST);
    gl.disable(gl.BLEND);
    // Compute the viewport host's absolute screen-space rect.
    const vp = absoluteViewportRect(this.ui.viewport);
    this.sceneRenderer.draw(this.scene, vp, window.devicePixelRatio || 1);
    gl.disable(gl.DEPTH_TEST);

    // Restore Gwen's GL state — it caches program/VAO/VBO from init()
    // and doesn't re-assert them in begin().
    if (this.gwenProgram) gl.useProgram(this.gwenProgram);
    if (this.gwenVao) gl.bindVertexArray(this.gwenVao);
    if (this.gwenVbo) gl.bindBuffer(gl.ARRAY_BUFFER, this.gwenVbo);

    // Update the footer with current stats.
    let verts = 0, edges = 0, faces = 0, tris = 0, objects = 0;
    this.scene.forEachNode((n) => {
      if (n.kind !== 'mesh') return;
      objects++;
      const m = (n as MeshObject).mesh;
      if (!m) return;
      verts += m.vertexCount();
      edges += m.edgeCount();
      faces += m.faceCount();
      for (const f of m.faces.values()) tris += Math.max(0, f.loops.length - 2);
    });
    this.ui.footer.setStats({
      fps: this.fps,
      frameMs: this.lastFrameMs,
      objects,
      vertices: verts,
      edges,
      faces,
      triangles: tris,
      status: 'Ready',
    });

    // Gwen UI pass — draws over the cleared/scene framebuffer.
    this.gwenCanvas.doThink();
    this.gwenCanvas.renderCanvas();
  }

  private installResize(): void {
    const onResize = (): void => this.handleResize();
    if (typeof ResizeObserver !== 'undefined') {
      this.resizeObs = new ResizeObserver(onResize);
      this.resizeObs.observe(this.canvas);
    }
    window.addEventListener('resize', onResize);
    // Run once at startup in case CSS-driven sizing settled after construction.
    this.handleResize();
  }

  private handleResize(): void {
    const dpr = window.devicePixelRatio || 1;
    this.sizeBackingStore(dpr);
    this.renderer.resize(this.canvas.width, this.canvas.height);
    this.gwenCanvas.setBounds(0, 0, this.canvas.clientWidth, this.canvas.clientHeight);
    if (this.ui) this.ui.applyResponsiveLayout();
  }

  private installMiddleClickListener(): void {
    const c = this.canvas;
    let middleDown = false;
    let lastX = 0, lastY = 0;
    c.addEventListener('pointerdown', (e) => {
      if (e.button !== 1) return;
      e.preventDefault();
      const rect = c.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;
      const local = this.ui.viewport.canvasToLocal(x, y);
      const vp = this.ui.viewport.getViewportRect();
      if (local.x < 0 || local.y < 0 || local.x >= vp.w || local.y >= vp.h) return;
      middleDown = true;
      lastX = x;
      lastY = y;
      this.ui.viewport.injectMiddleClick(x, y, true);
    });
    c.addEventListener('pointermove', (e) => {
      if (!middleDown) return;
      const rect = c.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;
      // Send a synthetic onMouseMoved through the viewport delegate so the
      // CameraController sees the pan.
      const dx = x - lastX;
      const dy = y - lastY;
      lastX = x;
      lastY = y;
      this.ui.viewport.delegate?.pointerMove?.(x, y, dx, dy);
    });
    const release = (e: PointerEvent): void => {
      if (e.button !== 1) return;
      if (!middleDown) return;
      middleDown = false;
      const rect = c.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;
      this.ui.viewport.injectMiddleClick(x, y, false);
    };
    c.addEventListener('pointerup', release);
    c.addEventListener('pointercancel', release);
  }

  private sizeBackingStore(dpr: number): void {
    const w = Math.max(1, Math.floor(this.canvas.clientWidth * dpr));
    const h = Math.max(1, Math.floor(this.canvas.clientHeight * dpr));
    if (this.canvas.width !== w) this.canvas.width = w;
    if (this.canvas.height !== h) this.canvas.height = h;
  }
}
