// Loop-normal generation. Hard edges break smoothing groups; soft edges
// fuse adjacent faces into one smoothing group at each vertex.

import * as Vec3 from '../core/math/Vec3';
import type { EditableMesh } from './EditableMesh';
import type { Face, Loop } from './Topology';
import type { Id } from '../core/Id';

/**
 * Recompute every loop's per-corner normal. A loop's normal is the
 * (area-weighted) average of the face normals reachable from its face
 * via soft edges only, restricted to faces incident to the loop's vertex.
 */
export function recomputeLoopNormals(mesh: EditableMesh): void {
  // Build per-vertex incident loops (by vertex).
  const loopsByVertex = new Map<Id, Loop[]>();
  for (const l of mesh.loops.values()) {
    let bucket = loopsByVertex.get(l.vertexId);
    if (!bucket) {
      bucket = [];
      loopsByVertex.set(l.vertexId, bucket);
    }
    bucket.push(l);
  }

  for (const [vid, loops] of loopsByVertex) {
    // For each loop at this vertex, walk through faces connected via soft
    // edges that also contain this vertex; average face normals.
    for (const l of loops) {
      const visited = new Set<Id>();
      const stack: Id[] = [l.faceId];
      let nx = 0, ny = 0, nz = 0;
      while (stack.length > 0) {
        const fid = stack.pop()!;
        if (visited.has(fid)) continue;
        visited.add(fid);
        const face = mesh.faces.get(fid);
        if (!face) continue;
        nx += face.normal[0];
        ny += face.normal[1];
        nz += face.normal[2];
        // Walk to neighbours via soft edges incident to this vertex.
        for (const lid of face.loops) {
          const fl = mesh.loops.get(lid);
          if (!fl) continue;
          const edge = mesh.edges.get(fl.edgeId);
          if (!edge) continue;
          if (edge.hard) continue;
          if (edge.a !== vid && edge.b !== vid) continue;
          for (const otherLoop of edge.loops) {
            const ol = mesh.loops.get(otherLoop);
            if (!ol) continue;
            if (ol.faceId !== fid && !visited.has(ol.faceId)) {
              stack.push(ol.faceId);
            }
          }
        }
      }
      const len = Math.hypot(nx, ny, nz);
      if (len > 0) {
        l.normal[0] = nx / len;
        l.normal[1] = ny / len;
        l.normal[2] = nz / len;
      } else {
        Vec3.copy(l.normal, mesh.faces.get(l.faceId)?.normal ?? Vec3.UNIT_Y);
      }
    }
  }

  // Vertex normals (average of all face normals through that vertex,
  // ignoring hardness — purely informational for vertex-level rendering).
  for (const v of mesh.vertices.values()) {
    let nx = 0, ny = 0, nz = 0;
    for (const eid of v.edges) {
      const e = mesh.edges.get(eid);
      if (!e) continue;
      for (const lid of e.loops) {
        const l = mesh.loops.get(lid);
        if (!l) continue;
        const f: Face | undefined = mesh.faces.get(l.faceId);
        if (!f) continue;
        nx += f.normal[0]; ny += f.normal[1]; nz += f.normal[2];
      }
    }
    const len = Math.hypot(nx, ny, nz);
    if (len > 0) {
      v.normal[0] = nx / len; v.normal[1] = ny / len; v.normal[2] = nz / len;
    } else {
      v.normal[0] = 0; v.normal[1] = 1; v.normal[2] = 0;
    }
  }
}
