// Plane primitive: configurable subdivisions on X and Z. Single quad by default.

import { EditableMesh } from '../EditableMesh';
import type { Id } from '../../core/Id';

export interface PlaneParams {
  width?: number;
  depth?: number;
  segmentsX?: number;
  segmentsZ?: number;
}

export function buildPlane(params: PlaneParams = {}): EditableMesh {
  const w = params.width ?? 2;
  const d = params.depth ?? 2;
  const sx = Math.max(1, Math.floor(params.segmentsX ?? 1));
  const sz = Math.max(1, Math.floor(params.segmentsZ ?? 1));
  const m = new EditableMesh();

  // Grid of (sx+1) * (sz+1) verts.
  const ids: Id[] = [];
  for (let j = 0; j <= sz; j++) {
    for (let i = 0; i <= sx; i++) {
      const x = (i / sx - 0.5) * w;
      const z = (j / sz - 0.5) * d;
      ids.push(m.addVertex(x, 0, z).id);
    }
  }

  for (let j = 0; j < sz; j++) {
    for (let i = 0; i < sx; i++) {
      const i0 = j * (sx + 1) + i;
      const i1 = i0 + 1;
      const i2 = i0 + (sx + 1) + 1;
      const i3 = i0 + (sx + 1);
      const face = m.addFace([ids[i0], ids[i1], ids[i2], ids[i3]]);
      const loops = m.faceLoops(face.id);
      const u0 = i / sx, v0 = j / sz;
      const u1 = (i + 1) / sx, v1 = (j + 1) / sz;
      const uvs: Array<[number, number]> = [[u0, v0], [u1, v0], [u1, v1], [u0, v1]];
      for (let k = 0; k < loops.length; k++) {
        loops[k].uv[0] = uvs[k][0];
        loops[k].uv[1] = uvs[k][1];
      }
    }
  }
  m.recomputeFaceNormals();
  return m;
}
