// TouchController — translates raw touch events on the canvas into camera
// operations. Mirrors the desktop gestures:
//   - 1-finger drag    → orbit (no mouse-button correlation; touch UX)
//   - 2-finger drag    → pan
//   - 2-finger pinch   → dolly
//
// We register touch listeners on the canvas itself; they don't intercept
// Gwen UI presses because we only consume events that land inside the
// viewport's host rect.

import type { ViewportHost } from '../ui/ViewportHost';
import type { ViewportLayout } from '../render/ViewportLayout';
import type { Camera } from '../render/Camera';

export class TouchController {
  private active = false;
  private mode: 'none' | 'orbit' | 'pan-pinch' = 'none';
  private last: Array<{ id: number; x: number; y: number }> = [];
  private lastPinchDist = 0;
  private hoverCam: Camera | null = null;

  constructor(
    private canvas: HTMLCanvasElement,
    private viewport: ViewportHost,
    private layout: ViewportLayout,
  ) {}

  install(): void {
    const c = this.canvas;
    c.addEventListener('touchstart', (e) => this.onStart(e), { passive: false });
    c.addEventListener('touchmove', (e) => this.onMove(e), { passive: false });
    c.addEventListener('touchend', (e) => this.onEnd(e));
    c.addEventListener('touchcancel', (e) => this.onEnd(e));
  }

  private localTouches(e: TouchEvent): Array<{ id: number; x: number; y: number }> {
    const rect = this.canvas.getBoundingClientRect();
    return Array.from(e.touches).map((t) => ({ id: t.identifier, x: t.clientX - rect.left, y: t.clientY - rect.top }));
  }

  private touchInsideViewport(t: { x: number; y: number }): boolean {
    const local = this.viewport.canvasToLocal(t.x, t.y);
    const b = this.viewport.getViewportRect();
    return local.x >= 0 && local.y >= 0 && local.x < b.w && local.y < b.h;
  }

  private onStart(e: TouchEvent): void {
    const touches = this.localTouches(e);
    if (!touches.length || !this.touchInsideViewport(touches[0])) {
      this.active = false;
      return;
    }
    e.preventDefault();
    this.active = true;
    this.last = touches;
    const sub = this.layout.subviewportAt(touches[0].x, touches[0].y);
    this.hoverCam = sub?.camera ?? null;
    if (touches.length === 1) {
      this.mode = 'orbit';
    } else if (touches.length >= 2) {
      this.mode = 'pan-pinch';
      this.lastPinchDist = Math.hypot(touches[0].x - touches[1].x, touches[0].y - touches[1].y);
    }
  }

  private onMove(e: TouchEvent): void {
    if (!this.active) return;
    e.preventDefault();
    const touches = this.localTouches(e);
    if (!this.hoverCam) return;
    if (this.mode === 'orbit' && touches.length === 1 && this.last.length === 1) {
      const dx = touches[0].x - this.last[0].x;
      const dy = touches[0].y - this.last[0].y;
      this.hoverCam.orbit(dx * 0.006, dy * 0.006);
    } else if (this.mode === 'pan-pinch' && touches.length >= 2) {
      // Average translation = pan.
      const avgX0 = (this.last[0].x + this.last[1].x) * 0.5;
      const avgY0 = (this.last[0].y + this.last[1].y) * 0.5;
      const avgX1 = (touches[0].x + touches[1].x) * 0.5;
      const avgY1 = (touches[0].y + touches[1].y) * 0.5;
      const dx = avgX1 - avgX0;
      const dy = avgY1 - avgY0;
      if (Math.abs(dx) > 0.1 || Math.abs(dy) > 0.1) this.hoverCam.pan(dx, dy);
      // Pinch → dolly: ratio of new dist vs last dist.
      const dist = Math.hypot(touches[0].x - touches[1].x, touches[0].y - touches[1].y);
      const dDolly = (dist - this.lastPinchDist) * 5;
      this.hoverCam.dolly(dDolly);
      this.lastPinchDist = dist;
    }
    this.last = touches;
  }

  private onEnd(e: TouchEvent): void {
    const touches = this.localTouches(e);
    if (touches.length === 0) {
      this.active = false;
      this.mode = 'none';
      this.last = [];
    } else if (touches.length === 1) {
      this.mode = 'orbit';
      this.last = touches;
    }
  }
}
