// SceneNode — base hierarchy node. Owns a Transform, parent ref, children
// array, visibility flag, selectability flag, and cached world matrix.
//
// MeshObject and ReferenceImage extend this.

import { Transform } from './Transform';
import * as Mat4 from '../core/math/Mat4';
import { nextId, type Id } from '../core/Id';

export type SceneNodeKind = 'empty' | 'mesh' | 'reference';

export class SceneNode {
  readonly id: Id;
  name: string;
  kind: SceneNodeKind;
  readonly transform = new Transform();
  parent: SceneNode | null = null;
  readonly children: SceneNode[] = [];
  visible = true;
  selectable = true;

  private _world: Mat4.Mat4 = Mat4.create();
  private _worldDirty = true;

  constructor(name = 'Node', kind: SceneNodeKind = 'empty') {
    this.id = nextId();
    this.name = name;
    this.kind = kind;
  }

  addChild(child: SceneNode): void {
    if (child.parent === this) return;
    if (child.parent) {
      child.parent.removeChild(child);
    }
    child.parent = this;
    this.children.push(child);
    child.markWorldDirty();
  }

  removeChild(child: SceneNode): void {
    const i = this.children.indexOf(child);
    if (i >= 0) {
      this.children.splice(i, 1);
      child.parent = null;
      child.markWorldDirty();
    }
  }

  setVisible(v: boolean): void {
    this.visible = v;
  }

  /** Effective visibility — false if any ancestor is hidden. */
  isEffectivelyVisible(): boolean {
    let n: SceneNode | null = this;
    while (n) {
      if (!n.visible) return false;
      n = n.parent;
    }
    return true;
  }

  setSelectable(v: boolean): void {
    this.selectable = v;
  }

  markWorldDirty(): void {
    if (this._worldDirty) return;
    this._worldDirty = true;
    this.transform.markDirty();
    for (const c of this.children) c.markWorldDirty();
  }

  getWorldMatrix(): Readonly<Mat4.Mat4> {
    if (!this._worldDirty) return this._world;
    if (this.parent) {
      Mat4.multiply(this._world, this.parent.getWorldMatrix(), this.transform.getLocalMatrix());
    } else {
      Mat4.copy(this._world, this.transform.getLocalMatrix());
    }
    this._worldDirty = false;
    return this._world;
  }

  /** Walks ancestors of self+others, returns true if `ancestor` is on the path. */
  isDescendantOf(ancestor: SceneNode): boolean {
    let n: SceneNode | null = this.parent;
    while (n) {
      if (n === ancestor) return true;
      n = n.parent;
    }
    return false;
  }
}
