// Unwrap + pack tests for seam-aware unwrap.

import { defineTest, assert, assertEquals } from '../harness';
import { buildCube } from './primitives/Cube';
import { buildPlane } from './primitives/Plane';
import { findIslands, unwrap, packIslands, applyUvIslands, autoUnwrapAndPack } from './Unwrap';

const SUITE = 'unwrap';

defineTest(SUITE, 'no seams: cube is one island', () => {
  const m = buildCube();
  const islands = findIslands(m);
  assertEquals(islands.length, 1);
});

defineTest(SUITE, 'marking all cube edges as seams produces 6 islands', () => {
  const m = buildCube();
  for (const e of m.edges.values()) e.seam = true;
  const islands = findIslands(m);
  // Cube has 6 faces; if every edge is a seam, each face is its own island.
  assertEquals(islands.length, 6);
});

defineTest(SUITE, 'marking horizontal cube edges separates top/bottom from sides', () => {
  const m = buildCube();
  // Mark edges where both endpoints have y > 0 (top ring) and y < 0 (bottom ring).
  for (const e of m.edges.values()) {
    const va = m.vertices.get(e.a)!;
    const vb = m.vertices.get(e.b)!;
    const bothTop = va.position[1] > 0 && vb.position[1] > 0;
    const bothBot = va.position[1] < 0 && vb.position[1] < 0;
    if (bothTop || bothBot) e.seam = true;
  }
  // Should isolate top + bottom + remaining side strip(s).
  const islands = findIslands(m);
  assert(islands.length >= 2);
});

defineTest(SUITE, 'unwrap returns one island per group with normalized UVs in [0,1]', () => {
  const m = buildPlane({ segmentsX: 2, segmentsZ: 2 });
  const islands = unwrap(m);
  assertEquals(islands.length, 1);
  for (const [, [u, v]] of islands[0].uvByLoop) {
    assert(u >= -1e-6 && u <= 1 + 1e-6, `u out of range: ${u}`);
    assert(v >= -1e-6 && v <= 1 + 1e-6, `v out of range: ${v}`);
  }
});

defineTest(SUITE, 'packIslands keeps every island inside (0..1) and non-overlapping', () => {
  const m = buildCube();
  for (const e of m.edges.values()) e.seam = true;
  const islands = unwrap(m);
  packIslands(islands, 0.005);
  // Each island bbox should be inside [0,1]² with no overlap.
  for (const island of islands) {
    assert(island.bbox.minU >= 0 - 1e-6 && island.bbox.maxU <= 1 + 1e-6);
    assert(island.bbox.minV >= 0 - 1e-6 && island.bbox.maxV <= 1 + 1e-6);
  }
  for (let i = 0; i < islands.length; i++) {
    for (let j = i + 1; j < islands.length; j++) {
      const a = islands[i].bbox;
      const b = islands[j].bbox;
      const overlap = !(a.maxU <= b.minU || b.maxU <= a.minU || a.maxV <= b.minV || b.maxV <= a.minV);
      assert(!overlap, `bbox overlap: ${i} ${j}`);
    }
  }
});

defineTest(SUITE, 'autoUnwrapAndPack applies UVs to mesh and produces valid UVs', () => {
  const m = buildCube();
  for (const e of m.edges.values()) e.seam = true;
  const islands = autoUnwrapAndPack(m);
  assertEquals(islands.length, 6);
  // Every loop has UVs inside [0,1]².
  for (const l of m.loops.values()) {
    assert(l.uv[0] >= -1e-6 && l.uv[0] <= 1 + 1e-6);
    assert(l.uv[1] >= -1e-6 && l.uv[1] <= 1 + 1e-6);
  }
});

defineTest(SUITE, 'applyUvIslands writes computed UVs to mesh loops', () => {
  const m = buildPlane({ segmentsX: 1, segmentsZ: 1 });
  const islands = unwrap(m);
  // Replace first loop's UV with a known value.
  const lid = Array.from(islands[0].uvByLoop.keys())[0];
  islands[0].uvByLoop.set(lid, [0.42, 0.42]);
  applyUvIslands(m, islands);
  const l = m.loops.get(lid)!;
  assert(Math.abs(l.uv[0] - 0.42) < 1e-6);
  assert(Math.abs(l.uv[1] - 0.42) < 1e-6);
});
