// Scene-graph unit tests.

import { defineTest, assert, assertEquals } from '../harness';
import { Scene } from './Scene';
import { SceneNode } from './SceneNode';
import { MeshObject } from './MeshObject';
import { Material } from './Material';
import * as Vec3 from '../core/math/Vec3';
import * as Mat4 from '../core/math/Mat4';

const SUITE = 'scene';

defineTest(SUITE, 'createDefault has root + default material + placeholder cube', () => {
  const scene = Scene.createDefault();
  assert(scene.root.children.length === 1);
  const cube = scene.root.children[0] as MeshObject;
  assert(cube.kind === 'mesh');
  assert(cube.name === 'Mesh_Cube');
  assert(scene.materials().length === 1);
  assert(cube.materialId !== null);
});

defineTest(SUITE, 'parenting: addNode reparents and updates child pointer', () => {
  const scene = new Scene();
  const a = new SceneNode('A');
  const b = new SceneNode('B');
  scene.addNode(a);
  scene.addNode(b);
  assertEquals(scene.root.children.length, 2);
  // Reparent b under a.
  a.addChild(b);
  assertEquals(scene.root.children.length, 1);
  assertEquals(a.children.length, 1);
  assert(b.parent === a);
});

defineTest(SUITE, 'transform propagation: child world position = parent translation', () => {
  const scene = new Scene();
  const a = new SceneNode('A');
  scene.addNode(a);
  a.transform.setPosition(10, 0, 0);
  const b = new SceneNode('B');
  a.addChild(b);
  b.transform.setPosition(0, 5, 0);
  // World position of b should be (10, 5, 0).
  const world = b.getWorldMatrix();
  const origin = Vec3.create();
  Mat4.transformPoint(origin, Vec3.fromValues(0, 0, 0), world);
  assert(Vec3.equalsApprox(origin, Vec3.fromValues(10, 5, 0), 1e-6));
});

defineTest(SUITE, 'transform dirty propagation: moving parent invalidates child cache', () => {
  const scene = new Scene();
  const a = new SceneNode('A');
  scene.addNode(a);
  const b = new SceneNode('B');
  a.addChild(b);
  a.transform.setPosition(1, 0, 0);
  // Force initial computation.
  b.getWorldMatrix();
  // Now move parent — child cache must rebuild.
  a.transform.setPosition(100, 0, 0);
  a.markWorldDirty();
  const o = Vec3.create();
  Mat4.transformPoint(o, Vec3.fromValues(0, 0, 0), b.getWorldMatrix());
  assert(Vec3.equalsApprox(o, Vec3.fromValues(100, 0, 0), 1e-6));
});

defineTest(SUITE, 'visibility: effective visibility false if ancestor hidden', () => {
  const scene = new Scene();
  const a = new SceneNode('A');
  scene.addNode(a);
  const b = new SceneNode('B');
  a.addChild(b);
  assert(b.isEffectivelyVisible());
  a.setVisible(false);
  assert(!b.isEffectivelyVisible());
  a.setVisible(true);
  b.setVisible(false);
  assert(!b.isEffectivelyVisible());
});

defineTest(SUITE, 'material creation registers id and is retrievable', () => {
  const scene = new Scene();
  const mat = scene.addMaterial(new Material('Mat_Red'));
  assertEquals(scene.materials().length, 1);
  assert(scene.getMaterial(mat.id) === mat);
  assert(scene.getMaterial(99999 as never) === null);
});

defineTest(SUITE, 'id stability: each node has a unique monotonically-increasing id', () => {
  const scene = new Scene();
  const a = new SceneNode('A');
  const b = new SceneNode('B');
  assert((b.id as unknown as number) > (a.id as unknown as number));
  scene.addNode(a);
  scene.addNode(b);
  // findNodeById round-trips.
  assert(scene.findNodeById(a.id) === a);
  assert(scene.findNodeById(b.id) === b);
});

defineTest(SUITE, 'selectability flag persists independently of visibility', () => {
  const scene = new Scene();
  const a = new SceneNode('A');
  scene.addNode(a);
  a.setSelectable(false);
  assertEquals(a.selectable, false);
  a.setVisible(false);
  assertEquals(a.selectable, false);
  a.setVisible(true);
  assertEquals(a.selectable, false);
});

defineTest(SUITE, 'reparent into descendant is rejected at intent layer (we just allow but check isDescendantOf)', () => {
  // Note: addChild itself doesn't detect cycles. Callers (commands) must
  // check `isDescendantOf` before reparenting. The test verifies the helper.
  const scene = new Scene();
  const a = new SceneNode('A');
  const b = new SceneNode('B');
  scene.addNode(a);
  a.addChild(b);
  assert(b.isDescendantOf(a));
  assert(b.isDescendantOf(scene.root));
  assert(!a.isDescendantOf(b));
});

defineTest(SUITE, 'forEachNode visits every node DFS', () => {
  const scene = new Scene();
  const a = new SceneNode('A');
  const b = new SceneNode('B');
  scene.addNode(a);
  a.addChild(b);
  const names: string[] = [];
  scene.forEachNode((n) => names.push(n.name));
  assertEquals(names.length, 3); // Root, A, B
});
