// Mesh-snapshot wrapping for edge-mode ops. Same snapshot-the-whole-mesh
// strategy as VertexCommands / ObjectCommands.

import type { Command } from '../Commands';
import { MeshObject } from '../../scene/MeshObject';
import { cloneMeshPreservingIds } from '../../mesh/MeshClone';
import {
  translateEdges, rotateEdges, scaleEdges,
  extrudeEdges, bevelEdge, loopCut,
  mergeEdges, weldEdges, bridgeEdges, fillEdge,
  deleteEdge, dissolveEdge,
  hardenEdges, softenEdges, markSeamEdges, clearSeamEdges,
} from '../../mesh/OperationsEdge';
import type { Id } from '../../core/Id';
import type { Vec3 as Vec3T } from '../../core/math/Vec3';

abstract class EdgeSnapshotCommand implements Command {
  protected node: MeshObject;
  private snap: ReturnType<typeof cloneMeshPreservingIds>;
  abstract readonly label: string;
  constructor(node: MeshObject) {
    this.node = node;
    if (!node.mesh) throw new Error('EdgeSnapshotCommand: missing mesh');
    this.snap = cloneMeshPreservingIds(node.mesh);
  }
  do(): void { if (this.node.mesh) this.apply(); }
  undo(): void { this.node.mesh = cloneMeshPreservingIds(this.snap); }
  protected abstract apply(): void;
}

export class TranslateEdgesCommand extends EdgeSnapshotCommand {
  readonly label = 'Move Edges';
  constructor(node: MeshObject, private edgeIds: Id[], private dx: number, private dy: number, private dz: number) { super(node); }
  protected apply(): void { translateEdges(this.node.mesh!, this.edgeIds, this.dx, this.dy, this.dz); }
}

export class RotateEdgesCommand extends EdgeSnapshotCommand {
  readonly label = 'Rotate Edges';
  constructor(node: MeshObject, private edgeIds: Id[], private axis: 'x' | 'y' | 'z', private rad: number) { super(node); }
  protected apply(): void { rotateEdges(this.node.mesh!, this.edgeIds, this.axis, this.rad); }
}

