// Pure mesh-transforming routines used by object-mode commands.
// Each function takes an EditableMesh and mutates it in place.

import { EditableMesh } from './EditableMesh';
import { cloneMesh } from './MeshClone';
import * as Vec3 from '../core/math/Vec3';
import type { Id } from '../core/Id';
import type { Edge, Loop, Vertex } from './Topology';

/** Make every edge "soft" (smooth shading). */
export function shadeSmooth(mesh: EditableMesh): void {
  for (const e of mesh.edges.values()) e.hard = false;
}

/** Make every edge "hard" (flat shading). */
export function shadeFlat(mesh: EditableMesh): void {
  for (const e of mesh.edges.values()) e.hard = true;
}

/**
 * One subdivision step. For each face, insert midpoint vertices on each
 * edge plus a single face-center vertex, and split the face into N quads
 * (one per original corner). The result has 4× faces for a quad and
 * face_vert_count × tris for an n-gon. This is the Catmull-Clark-style
 * topology split without the smoothing component.
 */
export function subdivide(mesh: EditableMesh): void {
  // Snapshot existing faces first since we'll mutate the maps.
  const oldFaces = Array.from(mesh.faces.values());
  // Cache edge midpoint vertices so each shared edge gets a single midpoint.
  const edgeMid = new Map<Id, Id>();
  const ensureEdgeMidpoint = (e: Edge): Id => {
    const cached = edgeMid.get(e.id);
    if (cached != null) return cached;
    const va = mesh.vertices.get(e.a)!;
    const vb = mesh.vertices.get(e.b)!;
    const mid = mesh.addVertex(
      (va.position[0] + vb.position[0]) * 0.5,
      (va.position[1] + vb.position[1]) * 0.5,
      (va.position[2] + vb.position[2]) * 0.5,
    );
    edgeMid.set(e.id, mid.id);
    return mid.id;
  };

  for (const face of oldFaces) {
    const loops = face.loops.map((id) => mesh.loops.get(id)!);
    const n = loops.length;
    // Edge midpoints for each loop's edge.
    const mids: Id[] = [];
    for (const l of loops) {
      const e = mesh.edges.get(l.edgeId);
      if (!e) {
        // Edge disappeared; bail this face.
        mids.length = 0;
        break;
      }
      mids.push(ensureEdgeMidpoint(e));
    }
    if (mids.length !== n) continue;
    // Center vertex.
    let cx = 0, cy = 0, cz = 0;
    for (const l of loops) {
      const v = mesh.vertices.get(l.vertexId)!;
      cx += v.position[0]; cy += v.position[1]; cz += v.position[2];
    }
    const center = mesh.addVertex(cx / n, cy / n, cz / n);
    // Remove the old face's loops/face. Edges stay; loose ones cleaned up at end.
    mesh.removeFace(face.id);
    // Create n new quads.
    for (let i = 0; i < n; i++) {
      const prevMid = mids[(i - 1 + n) % n];
      const corner = loops[i].vertexId;
      const nextMid = mids[i];
      mesh.addFace([prevMid, corner, nextMid, center.id], face.materialId);
    }
  }
  mesh.removeLooseGeometry();
  mesh.recomputeFaceNormals();
}

/**
 * Mirror across an axis-aligned plane through the origin.
 * `axis = 'x'` mirrors X coordinates; `'y'` mirrors Y; `'z'` mirrors Z.
 * The mirrored geometry is added as a fresh copy. If `mergeAtPlane` is
 * true, vertices on the mirror plane (within `mergeDistance`) are
 * coalesced with their counterparts.
 */
export function mirror(mesh: EditableMesh, axis: 'x' | 'y' | 'z', mergeAtPlane = true, mergeDistance = 1e-4): void {
  const axisIdx = axis === 'x' ? 0 : axis === 'y' ? 1 : 2;
  const original = cloneMesh(mesh);
  const vertMap = new Map<Id, Id>();
  for (const v of original.vertices.values()) {
    const onPlane = mergeAtPlane && Math.abs(v.position[axisIdx]) < mergeDistance;
    if (onPlane) {
      // Map to an existing vertex of the original mesh at the same (mirrored = same) location.
      // Find a matching vertex in the live mesh.
      let target: Id | null = null;
      for (const lv of mesh.vertices.values()) {
        if (
          Math.abs(lv.position[0] - v.position[0]) < mergeDistance &&
          Math.abs(lv.position[1] - v.position[1]) < mergeDistance &&
          Math.abs(lv.position[2] - v.position[2]) < mergeDistance
        ) {
          target = lv.id;
          break;
        }
      }
      if (target != null) {
        vertMap.set(v.id, target);
        continue;
      }
    }
    const newPos: [number, number, number] = [v.position[0], v.position[1], v.position[2]];
    newPos[axisIdx] = -newPos[axisIdx];
    const n = mesh.addVertex(newPos[0], newPos[1], newPos[2]);
    vertMap.set(v.id, n.id);
  }
  for (const f of original.faces.values()) {
    const verts = f.loops.map((lid) => vertMap.get(original.loops.get(lid)!.vertexId)!);
    // Reverse winding to keep face normals pointing outward after mirror.
    verts.reverse();
    mesh.addFace(verts, f.materialId);
  }
  mesh.recomputeFaceNormals();
}

/** Append all of `other`'s topology into `target` (in target's local space). */
export function append(target: EditableMesh, other: EditableMesh): void {
  const vertMap = new Map<Id, Id>();
  for (const v of other.vertices.values()) {
    const n = target.addVertex(v.position[0], v.position[1], v.position[2]);
    vertMap.set(v.id, n.id);
  }
  for (const f of other.faces.values()) {
    const verts = f.loops.map((lid) => vertMap.get(other.loops.get(lid)!.vertexId)!);
    target.addFace(verts, f.materialId);
  }
  target.recomputeFaceNormals();
}

/**
 * Restore mesh contents from a previously-cloned snapshot. Used by the
 * undo command for any object op that snapshots the whole mesh.
 */
export function restoreMesh(target: EditableMesh, snapshot: EditableMesh): void {
  target.vertices.clear();
  target.edges.clear();
  target.loops.clear();
  target.faces.clear();
  for (const v of snapshot.vertices.values()) {
    const n = target.addVertex(v.position[0], v.position[1], v.position[2]);
    // Override the id so references stay consistent within the test scope.
    target.vertices.delete(n.id);
    target.vertices.set(v.id, { ...n, id: v.id, normal: Vec3.fromValues(v.normal[0], v.normal[1], v.normal[2]) });
    void Vec3;
  }
  // Re-link edges by adding faces. We reuse the loop helpers to ensure consistency.
  // This is a simpler full-rebuild; it allocates fresh edges/loops/face ids in target.
  const vertList = Array.from(target.vertices.keys());
  void vertList;
  for (const f of snapshot.faces.values()) {
    const verts: Id[] = f.loops.map((lid) => snapshot.loops.get(lid)!.vertexId);
    target.addFace(verts, f.materialId);
  }
  // Copy hard / seam flags by endpoint match.
  for (const srcEdge of snapshot.edges.values()) {
    for (const dstEdge of target.edges.values()) {
      if (
        (dstEdge.a === srcEdge.a && dstEdge.b === srcEdge.b) ||
        (dstEdge.a === srcEdge.b && dstEdge.b === srcEdge.a)
      ) {
        dstEdge.hard = srcEdge.hard;
        dstEdge.seam = srcEdge.seam;
        break;
      }
    }
  }
  // Re-copy per-loop UV / normal.
  for (const dstFace of target.faces.values()) {
    const dstLoops = target.faceLoops(dstFace.id);
    // Match by ordered vertex sequence in any source face that shares the same
    // vertex ring (this is naive but adequate for object-op undo where we
    // rebuild everything).
    for (const srcFace of snapshot.faces.values()) {
      const sl = srcFace.loops.map((lid) => snapshot.loops.get(lid)!);
      if (sl.length !== dstLoops.length) continue;
      let ok = true;
      for (let i = 0; i < sl.length; i++) {
        if (sl[i].vertexId !== dstLoops[i].vertexId) { ok = false; break; }
      }
      if (!ok) continue;
      for (let i = 0; i < sl.length; i++) {
        dstLoops[i].uv[0] = sl[i].uv[0];
        dstLoops[i].uv[1] = sl[i].uv[1];
        dstLoops[i].normal[0] = sl[i].normal[0];
        dstLoops[i].normal[1] = sl[i].normal[1];
        dstLoops[i].normal[2] = sl[i].normal[2];
      }
      break;
    }
  }
  target.recomputeFaceNormals();
}
