// Rotate gizmo: three axis rings drawn as polylines.

import * as Vec3 from '../core/math/Vec3';
import { AXIS_VECTORS, getNodeOrigin, pointSegmentDistanceSq, projectToScreen, worldSizeForScreenPx, type Gizmo, type GizmoHit } from './Gizmo';
import type { Camera } from '../render/Camera';
import type { StripBatch } from '../render/StripRenderer';
import type { SceneNode } from '../scene/SceneNode';

const RADIUS_PX = 80;
const SEGMENTS = 48;
const HIT_PX = 6;

const AXIS_COLORS = {
  x: [0.95, 0.25, 0.25],
  y: [0.30, 0.85, 0.30],
  z: [0.30, 0.50, 0.95],
} as const;

function ringPoints(axis: 'x' | 'y' | 'z', origin: Vec3.Vec3, radius: number): Vec3.Vec3[] {
  const pts: Vec3.Vec3[] = [];
  for (let i = 0; i < SEGMENTS; i++) {
    const t = (i / SEGMENTS) * Math.PI * 2;
    const c = Math.cos(t) * radius;
    const s = Math.sin(t) * radius;
    let p: Vec3.Vec3;
    if (axis === 'x') p = Vec3.fromValues(origin[0], origin[1] + c, origin[2] + s);
    else if (axis === 'y') p = Vec3.fromValues(origin[0] + c, origin[1], origin[2] + s);
    else p = Vec3.fromValues(origin[0] + c, origin[1] + s, origin[2]);
    pts.push(p);
  }
  return pts;
}

export class RotateGizmo implements Gizmo {
  render(strips: StripBatch, node: SceneNode, camera: Camera, _vpRect: { x: number; y: number; w: number; h: number }, aspect: number): void {
    const origin = Vec3.create();
    getNodeOrigin(origin, node);
    const distance = Vec3.distance(origin, camera.position());
    const radius = worldSizeForScreenPx(RADIUS_PX, camera, distance, aspect, 2);
    for (const axis of ['x', 'y', 'z'] as const) {
      const col = AXIS_COLORS[axis];
      const pts = ringPoints(axis, origin, radius);
      for (let i = 0; i < pts.length; i++) {
        const a = pts[i];
        const b = pts[(i + 1) % pts.length];
        strips.add(a[0], a[1], a[2], b[0], b[1], b[2], col[0], col[1], col[2]);
      }
    }
  }

  hit(screenX: number, screenY: number, node: SceneNode, camera: Camera, vpRect: { x: number; y: number; w: number; h: number }, aspect: number): GizmoHit | null {
    const origin = Vec3.create();
    getNodeOrigin(origin, node);
    const distance = Vec3.distance(origin, camera.position());
    const radius = worldSizeForScreenPx(RADIUS_PX, camera, distance, aspect, 2);
    const viewProj = camera.viewProj(aspect) as Float32Array;
    let best: GizmoHit | null = null;
    let bestDist = HIT_PX * HIT_PX;
    for (const axis of ['x', 'y', 'z'] as const) {
      const pts = ringPoints(axis, origin, radius);
      const proj: Array<[number, number] | null> = pts.map((p) => {
        const r = projectToScreen(p, viewProj, vpRect);
        return r ? [r[0], r[1]] : null;
      });
      for (let i = 0; i < proj.length; i++) {
        const a = proj[i];
        const b = proj[(i + 1) % proj.length];
        if (!a || !b) continue;
        const d = pointSegmentDistanceSq(screenX, screenY, a[0], a[1], b[0], b[1]);
        if (d < bestDist) { bestDist = d; best = { axis }; }
      }
    }
    void AXIS_VECTORS;
    return best;
  }
}
